INSERT OR IGNORE INTO verses (id, ref, book, chapter, verse, text, text_normalized, text_html, testament, translation_key, dialect, tags, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40411, 'Genesis 31:41', 'Genesis', 31, 41, 'په دې ډول زه شل کاله ستا په کور کې وم. څوارلس کاله مې ستا د لورګانو په خاطر ستا خدمت وکړ او شپږ کاله مې ستا د رمو دپاره. لس ځلې دې زما مزدوري بدله کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_041.mp3', NULL, 1761758886, 1761758886),
(40412, 'Genesis 31:42', 'Genesis', 31, 42, 'که چېرې زما د نیکونو خدای، د ابراهیم او د اسحاق خدای زما سره مل نه وای، نو زه به دې په یقین سره تش لاس لېږلی وای. خو خدای زما سختۍ او د لاسونو خواري ولیدله او تېره شپه یې ملامته کړې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_042.mp3', NULL, 1761758886, 1761758886),
(40413, 'Genesis 31:43', 'Genesis', 31, 43, 'لابان یعقوب ته ځواب ورکړ: «دا ښځې زما لورګانې دي. د هغوی اولادونه زما اولادونه دي او دا رمې زما رمې دي او دا هرڅه چې دلته وینې زما دي. خو زه ستا څخه خپلې لورګانې او د هغوی اولادونه نه شم اخیستلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_043.mp3', NULL, 1761758886, 1761758886),
(40414, 'Genesis 31:44', 'Genesis', 31, 44, 'زه تیار یم چې ستا سره یو تړون وکړم. راځئ چې د تیږو یوه ډېرۍ جوړه کړو چې مونږ ته به زمونږ تړون رایادوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_044.mp3', NULL, 1761758886, 1761758886),
(40415, 'Genesis 31:45', 'Genesis', 31, 45, 'نو یعقوب تیږه راواخیستله او هغه یې د یادګار په توګه ودروله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_045.mp3', NULL, 1761758886, 1761758886),
(40416, 'Genesis 31:46', 'Genesis', 31, 46, 'هغه خپلو خپلوانو ته وویل چې تیږې راټولې کړي. نو هغوی تیږې راواخیستلې او ډېرۍ یې کړې. بیا یعقوب او لابان د هغې ډېرۍ په څنګ کې سره ډوډۍ وخوړله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_046.mp3', NULL, 1761758886, 1761758886),
(40417, 'Genesis 31:47', 'Genesis', 31, 47, 'لابان په هغه باندې یجر سهدوتا نوم کېښود. خو یعقوب هغه د جلعید په نوم یاد کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_047.mp3', NULL, 1761758886, 1761758886),
(40418, 'Genesis 31:48', 'Genesis', 31, 48, 'لابان وویل: «دا د تیږو ډېرۍ به زمونږ دواړو دپاره یو یادګار وي.» په دې خاطر هغه د جلعید په نوم یاده شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_048.mp3', NULL, 1761758886, 1761758886),
(40419, 'Genesis 31:49', 'Genesis', 31, 49, 'همدارنګه هغه د مصفه په نوم هم یاده شوه، ځکه چې لابان وویل: «کله چې مونږ یو د بل څخه بېل شو، نو څښتن دې زمونږ دواړو ناظر اوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_049.mp3', NULL, 1761758886, 1761758886),
(40420, 'Genesis 31:50', 'Genesis', 31, 50, 'که ته زما د لورګانو سره بد چلند وکړې او یا نورې ښځې وکړې، حتی که زه له دې څخه خبر هم نه شم، نو یاد ساته چې خدای زما او ستا ترمنځ شاهد دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_050.mp3', NULL, 1761758886, 1761758886),
(40421, 'Genesis 31:51', 'Genesis', 31, 51, 'همدارنګه لابان یعقوب ته وویل: «دا هغه ډېرۍ او هغه یادګاري تیږه ده چې زما او ستا ترمنځ مې ودرولې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_051.mp3', NULL, 1761758886, 1761758886),
(40422, 'Genesis 31:52', 'Genesis', 31, 52, 'دا ډېرۍ او دا تیږه دواړه زمونږ دپاره د یادګار په توګه دي. زه به د دې ډېرۍ څخه ستا خواته نه درتېرېږم چې حمله درباندې وکړم او ته به د دې ډېرۍ او د دې تیږې څخه نه راتېرېږې چې حمله راباندې وکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_052.mp3', NULL, 1761758886, 1761758886),
(40423, 'Genesis 31:53', 'Genesis', 31, 53, 'د ابراهیم او د ناحور خدای به زمونږ ترمنځ قضاوت کوي.» بیا یعقوب د هغه خدای په نوم چې د هغه پلار اسحاق ورته عبادت کاوه، سخت قسم وخوړ چې په دې وعدې باندې به ودریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_053.mp3', NULL, 1761758886, 1761758886),
(40424, 'Genesis 31:54', 'Genesis', 31, 54, 'یعقوب هلته په هغې غرنۍ سیمه کې قرباني وکړه او خپل خپلوان یې ډوډۍ خوړلو ته راوبلل. د ډوډۍ خوړلو څخه وروسته هغوی هلته شپه تېره کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_054.mp3', NULL, 1761758886, 1761758886),
(40425, 'Genesis 31:55', 'Genesis', 31, 55, 'لابان سهار وختي پاڅېد، خپل لمسیان او لورګانې یې ښکل کړل، خدای پاماني یې ورسره وکړه او بېرته خپل کور ته روان شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_055.mp3', NULL, 1761758886, 1761758886),
(40426, 'Amos 9:1', 'Amos', 9, 1, 'ما ولیدل چې څښتن د قربانۍ د ځای سره ولاړ ؤ. هغه حکم وکړ: «د عبادتځای د ستنو سرونه دومره وټکوه چې ټول بنیادونه یې ولړزیږي. هغه ټوټې ټوټې کړه چې د خلکو په سرونو باندې راولویږي. پاتې خلک به زه په جنګ کې ووژنم. هېڅوک به ونه شي تښتېدلی او هېڅوک به خلاص نه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_001.mp3', NULL, 1761758886, 1761758886),
(40427, 'Amos 9:2', 'Amos', 9, 2, 'که هغوی ځمکه وکني او لاندې د مړو دنیا ته هم کوز شي، نو زه به یې راونیسم. که هغوی اسمان ته هم وخېژي، نو زه به یې لاندې راښکته کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_002.mp3', NULL, 1761758886, 1761758886),
(40428, 'Amos 9:3', 'Amos', 9, 3, 'که هغوی د کرمل د غره په سر هم پټ شي، زه به یې ولټوم او راګېر به یې کړم. که هغوی د بحیرې په تل کې هم زما نه پټ شي، زه به د بحیرې مار ته حکم وکړم چې هغوی وچیچي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_003.mp3', NULL, 1761758886, 1761758886),
(40429, 'Amos 9:4', 'Amos', 9, 4, 'که هغوی د خپلو دښمنانو له خوا اسیران هم شي، زه به حکم وکړم چې هغوی ووژل شي. ما پرېکړه کړې ده چې د هغوی سره مرسته ونه کړم، بلکې هغوی له منځه یوسم.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_004.mp3', NULL, 1761758886, 1761758886),
(40430, 'Amos 9:5', 'Amos', 9, 5, 'لاس به وروړي مطلق قادر څښتن تعالی ځمکې ته او هغه به وښوییږي څوک چې اوسیږي هلته نو ټول به شروع کړي ماتم ټوله دنیا به پورته کیږي او رالویږي د نیل د سیند په شان', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_005.mp3', NULL, 1761758886, 1761758886),
(40431, 'Amos 9:6', 'Amos', 9, 6, 'جوړوي په اسمانونو کې خپل کور څښتن او په ځمکه یې ودروله د اسمان ګنبده هغه راوغوښتلې د بحیرې اوبه او ویې بهولې په ځمکه باندې لکه سیلاب په شان د هغه نوم دی څښتن!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_006.mp3', NULL, 1761758886, 1761758886),
(40432, 'Amos 9:7', 'Amos', 9, 7, 'څښتن داسې وایي: «ای د اسراییلو خلکو، څومره چې زه د ایتوپیا د خلکو په هکله فکر کوم، دومره ستاسو په هکله هم کوم. لکه څنګه چې ما فلسطینیان د کریت نه او د سوریې خلک د قیر نه راوویستل، همداسې مې تاسو هم د مصر نه راوویستلئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_007.mp3', NULL, 1761758886, 1761758886),
(40433, 'Amos 9:8', 'Amos', 9, 8, 'زه څښتن تعالی د اسراییلو ګناهکاره پاچاهي وینم او هغه به د ځمکې د مخ نه ورکه کړم. خو د یعقوب ټوله اولاده به له منځه نه وړم.» دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_008.mp3', NULL, 1761758886, 1761758886),
(40434, 'Amos 9:9', 'Amos', 9, 9, 'نو ګورئ، زه به حکم وکړم او د اسراییلو خلک به داسې غلبېل کړم لکه غله چې په غلبیل کې خوځیږي. کله چې هغوی د نورو قومونو په منځ کې اوسیږي، زه به یې داسې غلبیل کړم چې بد خلک لکه د تیږو په شان ورڅخه لېرې شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_009.mp3', NULL, 1761758886, 1761758886),
(40435, 'Amos 9:10', 'Amos', 9, 10, 'زما په قوم کې چې کوم خلک ګناهکار دي، هغه به په جنګ کې ووژل شي، یعنې هغه ټول خلک چې وایي: «په مونږ به کوم مصیبت نه راځي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_010.mp3', NULL, 1761758886, 1761758886),
(40436, 'Amos 9:11', 'Amos', 9, 11, 'څښتن وایي: «یوه داسې ورځ راروانه ده چې زه به د داود پاچاهي چې لکه د یو کور په شان ورانه شوې وه، بېرته جوړه کړم. زه به د هغه دېوالونه بېرته جوړ کړم او هغه کنډوالې به بېرته ابادې کړم او زه به هغه د پخوا په شان بېرته ودان کړم،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_011.mp3', NULL, 1761758886, 1761758886),
(40437, 'Amos 9:12', 'Amos', 9, 12, 'ترڅو د اسراییلو خلک به هغه څه چې په ادوم کې پاتې دي او هغه ټول قومونه چې په یو وخت کې زما وو، ونیسي.» څښتن وایي چې همداسې به وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_012.mp3', NULL, 1761758886, 1761758886),
(40438, 'Amos 9:13', 'Amos', 9, 13, 'څښتن داسې وایي: راروان دی هغه وخت چې فصلونه به پخیږي د رېبلو وخت نه مخکې او پخیږي به انګور د شرابو جوړېدو نه مخکې او له غونډیو راتوییږي به', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_013.mp3', NULL, 1761758886, 1761758886),
(40439, 'Amos 9:14', 'Amos', 9, 14, 'زه به راولم خپل قوم بېرته خپل وطن ته بېرته اباد به کړي دوی خپل کنډوالې ښارونه او په کې اوسیږي به هغوی به وکري باغونه د انګورو او شراب به یې څښي هغوی به وکري باغونه او مېوه به یې خوري', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_014.mp3', NULL, 1761758886, 1761758886),
(40440, 'Amos 9:15', 'Amos', 9, 15, 'زه به وکرم خپل قوم هغه وطن کې او ویستلی به بیا نه شي هغوی له هغه وطنه چې ورکړی مې دی دا هغه څه دي چې څښتن، ستاسو خدای ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos9_verse_015.mp3', NULL, 1761758886, 1761758886),
(40441, 'Isaiah 3:1', 'Isaiah', 3, 1, 'اوس څښتن، مطلق قادر څښتن به د اورشلیم او یهودا نه ټول شیان چې د خلکو ژوند ورسره تړلي دي، واخلي. هغه به د خوړو او اوبو قحطي راولي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_001.mp3', NULL, 1761758886, 1761758886),
(40442, 'Isaiah 3:2', 'Isaiah', 3, 2, 'څښتن به د هغوی جنګیالیان او د هغوی عسکر، د هغوی قاضیان او پیغمبران، د هغوی فال کتونکي او سپین ږیري،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_002.mp3', NULL, 1761758886, 1761758886),
(40443, 'Isaiah 3:3', 'Isaiah', 3, 3, 'د هغوی نظامي او ملکي مشران، د هغوی مشاوران، ماهر کسبګران او جادوګران، هم واخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_003.mp3', NULL, 1761758886, 1761758886),
(40444, 'Isaiah 3:4', 'Isaiah', 3, 4, 'څښتن به هلکان د هغوی مشران کړي او ماشومان به په هغوی باندې حکومت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_004.mp3', NULL, 1761758886, 1761758886),
(40445, 'Isaiah 3:5', 'Isaiah', 3, 5, 'خلک به په یو بل باندې ظلم او زیاتی کوي. ځوانان به د خپلو مشرانو سپکاوی کوي او سپک خلک به د شریفو خلکو عزت نه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_005.mp3', NULL, 1761758886, 1761758886),
(40446, 'Isaiah 3:6', 'Isaiah', 3, 6, 'داسې وخت به راشي چې د یوې طایفې خلک به د خپل منځ نه یو کس خوښ کړي او هغه ته به ووایي: «ته خو یوه چپنه لرې، راشه د دې کنډوالې مشر شه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_006.mp3', NULL, 1761758886, 1761758886),
(40447, 'Isaiah 3:7', 'Isaiah', 3, 7, 'خو هغه به په ټینګه ځواب ورکړي: «نه! زه ستاسو سره مرسته نه شم کولای. زما سره نه خواړه شته او نه چپنه. ما د خپل مشر په توګه مه ټاکئ!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_007.mp3', NULL, 1761758886, 1761758886),
(40448, 'Isaiah 3:8', 'Isaiah', 3, 8, 'هو، اورشلیم تباه کیږي! او یهودا سقوط کوي! هغوی چې هرڅه وایي او هرڅه کوي هغه د څښتن په خلاف دي. هغوی د هغه د جلال په وړاندې سرکښي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_008.mp3', NULL, 1761758886, 1761758886),
(40449, 'Isaiah 3:9', 'Isaiah', 3, 9, 'د هغوی د مخونو څخه د هغوی ملامتیا ښکاره ده. هغوی د سدوم د خلکو په شان په ښکاره ګناه کوي. افسوس د هغوی په حال! ځکه هغوی په خپله دا تباهي په خپل ځان باندې راوستې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_009.mp3', NULL, 1761758886, 1761758886),
(40450, 'Isaiah 3:10', 'Isaiah', 3, 10, 'نېکو خلکو ته ووایئ: «ستاسو هر کار به سم روان وي. تاسو به د خپل کار او زحمت ثمره ووینئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_010.mp3', NULL, 1761758886, 1761758886),
(40451, 'Isaiah 3:11', 'Isaiah', 3, 11, 'بدو خلکو ته ووایئ: «افسوس ستاسو په حال! ځکه ستاسو سره به د بدو کارونو په بدل کې عمل وشي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_011.mp3', NULL, 1761758886, 1761758886),
(40452, 'Isaiah 3:12', 'Isaiah', 3, 12, 'ماشومان زما په قوم باندې ظلم کوي او ښځې په هغوی باندې حکومت کوي. ای زما قومه، ستاسو مشران تاسو بې لارې کوي، نه غواړي چې تاسو په سمه لاره لاړ شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_012.mp3', NULL, 1761758886, 1761758886),
(40453, 'Isaiah 3:13', 'Isaiah', 3, 13, 'څښتن دې ته تیار دی چې خپله محاکمه دایره کړي او د خلکو قضاوت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_013.mp3', NULL, 1761758886, 1761758886),
(40454, 'Isaiah 3:14', 'Isaiah', 3, 14, 'څښتن د خپل قوم سپین ږیري او مشران د محاکمې دپاره راولي. هغوی ته وایي: «تاسو زما د انګورو باغ لوټ کړی دی او د غریبانو څخه مو چې هرڅه وړي دي، د هغو څخه مو خپل کورونه ډک کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_014.mp3', NULL, 1761758886, 1761758886),
(40455, 'Isaiah 3:15', 'Isaiah', 3, 15, 'تاسو حق نه لرئ چې زما قوم تر پښو لاندې کړئ او د غریبانو سرونه په ځمکه ووهئ. زه مطلق قادر څښتن خدای داسې وایم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_015.mp3', NULL, 1761758886, 1761758886),
(40456, 'Isaiah 3:16', 'Isaiah', 3, 16, 'څښتن وویل: «وګورئ، د اورشلیم ښځې څومره مغرورې دي! هغوی هسکې غاړې نیولې او روانې دي. هغوی د شهوت په سترګو هرې خواته ګوري. په ناز او نخرو باندې قدمونه اخلي او خپل پایزیبونه شرنګوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_016.mp3', NULL, 1761758886, 1761758886),
(40457, 'Isaiah 3:17', 'Isaiah', 3, 17, 'خو زه به هغوی ته سزا ورکړم - د هغوی سرونه به وخرایم او هغوی به بې پردې او رسوا کړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_017.mp3', NULL, 1761758886, 1761758886),
(40458, 'Isaiah 3:18', 'Isaiah', 3, 18, 'داسې ورځ راورانه ده چې څښتن به د اورشلیم د ښځو څخه هغه ټول شیان چې هغوی ورباندې مغروره دي، اخلي، یعنې: د هغوی پایزیبونه، د سر ټیک، د نوې میاشتې د سپوږمۍ په شان غاړکۍ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_018.mp3', NULL, 1761758886, 1761758886),
(40459, 'Isaiah 3:19', 'Isaiah', 3, 19, 'غوږوالۍ، بنګړي او نقابونه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_019.mp3', NULL, 1761758886, 1761758886),
(40460, 'Isaiah 3:20', 'Isaiah', 3, 20, 'ټیکري، بازوبندونه، کمربندونه، د عطرو بوتلونه او تعویذونه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_020.mp3', NULL, 1761758886, 1761758886),
(40461, 'Isaiah 3:21', 'Isaiah', 3, 21, 'ګوتې او پېزوانونه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_021.mp3', NULL, 1761758886, 1761758886),
(40462, 'Isaiah 3:22', 'Isaiah', 3, 22, 'ښکلې چپنې، بې لستوڼو چپنې، شالونه، لاسي بکسونه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_022.mp3', NULL, 1761758886, 1761758886),
(40463, 'Isaiah 3:23', 'Isaiah', 3, 23, 'آئینې، د کتان کالي، تاجونه او څادرونه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_023.mp3', NULL, 1761758886, 1761758886),
(40464, 'Isaiah 3:24', 'Isaiah', 3, 24, 'د عطرو په ځای به د هغوی نه بد بوی خېژي، د ښایسته کمربندونو په ځای به هغوی زیږه پړي له ځانه راتاو کړي وي، د ښایسته ویښتانو په ځای به هغوی ګنجیانې وي، د ښکلو جامو په ځای به هغوی بدرنګې جامې اغوستې وي، د هغوی ښایست به د شرم په داغ بدل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_024.mp3', NULL, 1761758886, 1761758886),
(40465, 'Isaiah 3:25', 'Isaiah', 3, 25, 'د ښار سړي به په توره او ستاسو تکړه سړي به د جګړې په ډګر کې ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_025.mp3', NULL, 1761758886, 1761758886),
(40466, 'Isaiah 3:26', 'Isaiah', 3, 26, 'د ښار د دروازو څخه به د ژړا او ویر اوازونه اورېدل کیږي او خپله ښار به په ماتم کې ویجاړیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah3_verse_026.mp3', NULL, 1761758886, 1761758886),
(40467, 'Esther 10:1', 'Esther', 10, 1, 'خشایار پاچا په خپلې امپراتورۍ کې هر یو دې ته مجبور کړ چې باج ورکړي، حتی هغه خلک چې د جزیرو څخه لېرې اوسېدل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther10_verse_001.mp3', NULL, 1761758886, 1761758886),
(40468, 'Esther 10:2', 'Esther', 10, 2, 'هغه ټول لوی او عجیبه کارونه چې خشایار پاچا کړي وو او هغه پوره کیسه چې هغه څنګه مردخای ته لوړ مقام ورکړ، هغه د ماد او فارس د پاچاهانو د تاریخ په کتاب کې لیکل شوي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther10_verse_002.mp3', NULL, 1761758886, 1761758886),
(40469, 'Esther 10:3', 'Esther', 10, 3, 'یهودي مردخای د خشایار پاچا څخه وروسته دوهم کس ؤ. یهودیانو هغه ته په درنه سترګه کتل او ورباندې ګران ؤ. هغه د خپلو خلکو د ښېګڼې او د هغوی د ټولې اولادې د ارامۍ دپاره غږ پورته کاوه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther10_verse_003.mp3', NULL, 1761758886, 1761758886),
(40470, 'Isaiah 33:1', 'Isaiah', 33, 1, 'افسوس ستاسو په حال چې خلک تباه کوئ او خیانت کوئ، که څه هم تاسو تباه او برباد شوي نه یئ او نه ستاسو سره خیانت شوی دی. ستاسو د تباهۍ او خیانت وخت به پای ته ورسیږي او هغه وخت به راورسیږي چې تاسو د تباهۍ او خیانت ښکار شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_001.mp3', NULL, 1761758886, 1761758886),
(40471, 'Isaiah 33:2', 'Isaiah', 33, 2, 'ای څښتنه، په مونږ رحم وکړه. زمونږ هیله تاته ده. هر سهار مونږ ته قوت راکړه او د کړاوونو په وخت کې زمونږ ژغورونکی شه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_002.mp3', NULL, 1761758886, 1761758886),
(40472, 'Isaiah 33:3', 'Isaiah', 33, 3, 'کله چې دښمن ستا د تندر په شان اواز اوري، نو تښتي. ستا له پاڅېدو سره قومونه خواره واره کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_003.mp3', NULL, 1761758886, 1761758886),
(40473, 'Isaiah 33:4', 'Isaiah', 33, 4, 'زمونږ د دښمنانو شتمني به داسې لوټ او تالا شي، لکه ملخان چې په کروندو باندې حمله وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_004.mp3', NULL, 1761758886, 1761758886),
(40474, 'Isaiah 33:5', 'Isaiah', 33, 5, 'څښتن څومره لوی دی. هغه په اسمان کې اوسیږي. هغه به صهیون د عدالت او انصاف څخه ډک کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_005.mp3', NULL, 1761758886, 1761758886),
(40475, 'Isaiah 33:6', 'Isaiah', 33, 6, 'او ستاسو دپاره به یو ټینګ بنیاد وي. هغه به تل تاسو وژغوري او تاسو ته به ډېر حکمت او ډېره پوهه درکړي. د څښتن څخه وېره د صهیون دپاره د خزانې په شان ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_006.mp3', NULL, 1761758886, 1761758886),
(40476, 'Isaiah 33:7', 'Isaiah', 33, 7, 'واورئ! زړور خلک په کوڅو کې د مرستې دپاره چیغې وهي. د سولې استازي اوس په چیغو چیغو ژاړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_007.mp3', NULL, 1761758886, 1761758886),
(40477, 'Isaiah 33:8', 'Isaiah', 33, 8, 'لویي لارې دومره له خطره ډکې شوې دي چې هېڅوک ورباندې سفر نه شي کولای. خلکو تړونونه مات کړي دي او هغه وعدې چې د شاهدانو په وړاندې یې کړې وې، نه دي عملي کړې. هغوی نور د هېچا درناوی نه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_008.mp3', NULL, 1761758886, 1761758886),
(40478, 'Isaiah 33:9', 'Isaiah', 33, 9, 'د اسراییلو ځمکه وچه او شاړه پرته ده. د لبنان ځنګلونه وچ شوي دي. د شارون حاصلخېزه دره لکه د دښتې په شان شوې ده. د باشان او د کرمل د ونو پاڼې رالویږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_009.mp3', NULL, 1761758886, 1761758886),
(40479, 'Isaiah 33:10', 'Isaiah', 33, 10, 'څښتن قومونو ته وایي: «اوس پاڅېږم. زه به تاسو ته خپل قدرت او لویي وښایم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_010.mp3', NULL, 1761758886, 1761758886),
(40480, 'Isaiah 33:11', 'Isaiah', 33, 11, 'ستاسو نقشې بې ارزښته دي او هرڅه چې کوئ هغه بې ګټې دي. ستاسو نفس به په اور بدل شي، تاسو به په خپله وسوځوي او له منځه به مو یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_011.mp3', NULL, 1761758886, 1761758886),
(40481, 'Isaiah 33:12', 'Isaiah', 33, 12, 'تاسو به لکه د اغزیو د بوټو په شان په اور کې وغورځول شئ، وبه سوځئ او په ایرو به بدل شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_012.mp3', NULL, 1761758886, 1761758886),
(40482, 'Isaiah 33:13', 'Isaiah', 33, 13, 'ای لرې او نژدې خلکو، څه چې مې تر سره کړي، هغه ته پام وکړئ او زما قدرت ومنئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_013.mp3', NULL, 1761758886, 1761758886),
(40483, 'Isaiah 33:14', 'Isaiah', 33, 14, 'د صهیون ګناهکاران وېرېږي، بې ایمانه خلک رپیږي او وایي: «د خدای قضاوت د یو تباه کوونکي اور په شان دی. څوک به زمونږ څخه په داسې تل بلېدونکي اور کې ژوندی پاتې شي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_014.mp3', NULL, 1761758886, 1761758886),
(40484, 'Isaiah 33:15', 'Isaiah', 33, 15, 'هغه څوک ژوندی پاتې کېدای شي چې په خپل ژوند کې نېک وي او رښتیا وایي، د غریبانو د غولولو دپاره د خپل زور څخه کار وانخلي او د رشوت اخیستلو څخه لاس واخلي، د قتل په نقشو کې برخه وانخلي او د بدۍ څخه هم ځان وساتي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_015.mp3', NULL, 1761758886, 1761758886),
(40485, 'Isaiah 33:16', 'Isaiah', 33, 16, 'داسې کسان به په امن کې ژوند کوي او هغوی به داسې په امن کې اوسیږي لکه څنګه چې څوک د تیږو په کلاګانو کې اوسیږي. هغوی ته به خواړه ورکړل شي او بې له شکه به اوبه ولري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_016.mp3', NULL, 1761758886, 1761758886),
(40486, 'Isaiah 33:17', 'Isaiah', 33, 17, 'تاسو به د پاچا هغه شان او شوکت ووینئ چې په یو لوی او پراخ هېواد پاچاهي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_017.mp3', NULL, 1761758886, 1761758886),
(40487, 'Isaiah 33:18', 'Isaiah', 33, 18, 'بیا به د تېر شوي ظلم په اړه فکر وکړئ، له خپل ځانه به پوښتنه وکړئ او وبه وایئ: «هغه پردي مامورین چېرته دي چې زمونږ نه به یې باج اخیسته؟ هغه جاسوسان چېرته دي چې زمونږ برجونه به یې شمېرل؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_018.mp3', NULL, 1761758886, 1761758886),
(40488, 'Isaiah 33:19', 'Isaiah', 33, 19, 'خو تاسو به نور د هغه پردي هېواد کبرجن خلک ونه وینئ چې په پردۍ ژبه یې خبرې کولې او تاسو د هغه په معنی نه پوهېدلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_019.mp3', NULL, 1761758886, 1761758886),
(40489, 'Isaiah 33:20', 'Isaiah', 33, 20, 'صهیون ته وګورئ، یعنې هغه ښار ته چې مونږ په کې خپل دیني اخترونه لمانځو. تاسو به اورشلیم ووینئ چې هغه د اوسېدلو دپاره څنګه خوندي ځای دی. اورشلیم به د هغې خېمې په شان وي چې نه خوځیږي او موږي به یې هېڅکله راونه ویستل شي او رسۍ به یې هېڅکله ونه شلیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_020.mp3', NULL, 1761758886, 1761758886),
(40490, 'Isaiah 33:21', 'Isaiah', 33, 21, 'هلته به زمونږ د جلال څخه ډک څښتن د لویو سیندونو او ویالو په شان زمونږ څخه ساتنه وکړي او نور به د دښمن کشتۍ ونه شي کولای د هغه نه تېرې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_021.mp3', NULL, 1761758886, 1761758886),
(40491, 'Isaiah 33:22', 'Isaiah', 33, 22, 'څښتن په خپله زمونږ قاضي، حکم ورکوونکی او پاچا دی او هغه به مونږ وژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_022.mp3', NULL, 1761758886, 1761758886),
(40492, 'Isaiah 33:23', 'Isaiah', 33, 23, 'د دښمن د کشتۍ ګانو طنابونه او رسۍ به سستې شي، نه به یې ستنې ټینګې شي او نه به یې بادوانونه خلاص شي. د دښمن د لښکرو ټول مالونه به د غنیمت په توګه ووېشل شي او دا مال به دومره ډېر وي چې ګوډانو ته به هم په کې خپله برخه ورسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_023.mp3', NULL, 1761758886, 1761758886),
(40493, 'Isaiah 33:24', 'Isaiah', 33, 24, 'زمونږ د وطن اوسېدونکي به هېڅکله دا شکایت ونه کړي: «زه ناروغ یم» او د هغوی ټول ګناهونه به وبخښل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah33_verse_024.mp3', NULL, 1761758886, 1761758886),
(40494, 'Job 5:1', 'Job', 5, 1, 'آواز وکړه، داسې څوک شته چې تا له جواب درکړى؟ داسې يوه فرښته شته څۀ چې د هغې نه مدد وغواړې؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_001.mp3', NULL, 1761758886, 1761758886),
(40495, 'Job 5:2', 'Job', 5, 2, 'په حقيقت کښې نفرت کم عقل خلق وژنى، او حسد ساده خلق وژنى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_002.mp3', NULL, 1761758886, 1761758886),
(40496, 'Job 5:3', 'Job', 5, 3, 'ما دا ليدلى دى چې څۀ کم عقل خلق د لږ وخت دپاره کامياب وى، خو بيا ناڅاپه تباهى ورباندې راشى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_003.mp3', NULL, 1761758886, 1761758886),
(40497, 'Job 5:4', 'Job', 5, 4, 'د هغوئ د بچو دپاره به د پناه هيڅ امکان نۀ وى، او داسې به څوک نۀ وى چې په عدالت کښې يې خلاص کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_004.mp3', NULL, 1761758886, 1761758886),
(40498, 'Job 5:5', 'Job', 5, 5, 'اوږى خلق د کم عقلو فصلونه خورى، کۀ د هغۀ د پټو نه د حِفاظت دپاره ازغى هم تاو وى، لالچى خلق د هغوئ دولت ختم کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_005.mp3', NULL, 1761758886, 1761758886),
(40499, 'Job 5:6', 'Job', 5, 6, 'ځکه چې خفګان د زمکې نه نۀ راځى، او نۀ مصيبت د زمکې نه پېدا کيږى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_006.mp3', NULL, 1761758886, 1761758886),
(40500, 'Job 5:7', 'Job', 5, 7, 'خو انسانان د مصيبت دپاره داسې پېدا شوى دى لکه چې د اور بڅرکى بره الوځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_007.mp3', NULL, 1761758886, 1761758886),
(40501, 'Job 5:8', 'Job', 5, 8, 'کۀ زۀ ستا په ځائ وے نو ما به خُدائ پاک لټولے، او خُدائ پاک ته به مې فرياد اورولے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_008.mp3', NULL, 1761758886, 1761758886),
(40502, 'Job 5:9', 'Job', 5, 9, 'هغه داسې لوئ لوئ کارونه کوى چې څوک ورباندې نۀ پوهيږى، هغه بې‌شمېره عجيبه کارونه کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_009.mp3', NULL, 1761758886, 1761758886),
(40503, 'Job 5:10', 'Job', 5, 10, 'هغه په زمکه باندې باران ورَوى او هغه پټو ته اوبۀ رالېږى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_010.mp3', NULL, 1761758886, 1761758886),
(40504, 'Job 5:11', 'Job', 5, 11, 'چې څوک غريب وى نو خُدائ پاک يې مالداره کړى، او چې څوک غمژن وى نو خوشحالى ورکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_011.mp3', NULL, 1761758886, 1761758886),
(40505, 'Job 5:12', 'Job', 5, 12, 'هغه د چالاکو منصوبې ګډې وډې کړى، نو داسې د هغوئ په لاس کښې هيڅ کاميابى نۀ راځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_012.mp3', NULL, 1761758886, 1761758886),
(40506, 'Job 5:13', 'Job', 5, 13, 'هغه هوښيار د خپلې چالاکۍ په جال کښې راګېروى، او چالاک خلق زر فنا شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_013.mp3', NULL, 1761758886, 1761758886),
(40507, 'Job 5:14', 'Job', 5, 14, 'د ورځې په وخت په هغوئ تيارۀ راشى او د غرمې په وخت داسې تيندکونه خورى لکه چې شپه وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_014.mp3', NULL, 1761758886, 1761758886),
(40508, 'Job 5:15', 'Job', 5, 15, 'خو هغه ضرورتمند خلق د مرګ نه بچ کوى، او د زورَور د زور نه يې بچ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_015.mp3', NULL, 1761758886, 1761758886),
(40509, 'Job 5:16', 'Job', 5, 16, 'نو چې غريبانان اُميد ولرى، او د بې‌اِنصافه خلقو خولې بندې کړے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_016.mp3', NULL, 1761758886, 1761758886),
(40510, 'Job 5:17', 'Job', 5, 17, 'چې خُدائ پاک څوک ټيک کړى نو هغوئ څومره خوشحاله وى، نو په دې وجه د قادر خُدائ تربيت ته سپک مۀ ګورئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_017.mp3', NULL, 1761758886, 1761758886),
(40511, 'Job 5:18', 'Job', 5, 18, 'کۀ هغه زخمى کول کوى، نو هغه يې مرهم پټۍ هم کوى، کۀ هغه وهل کوى، نو د هغۀ لاسونه يې علاج هم کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_018.mp3', NULL, 1761758886, 1761758886),
(40512, 'Job 5:19', 'Job', 5, 19, 'هغه به تاسو د شپږو افتونو نه بچ کوى، او په اوؤم کښې به تاسو ته هيڅ نقصان نۀ رسيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_019.mp3', NULL, 1761758886, 1761758886),
(40513, 'Job 5:20', 'Job', 5, 20, 'په قحط کښې به هغه تاسو د مرګ نه په بيعه واخلى، او په جنګ کښې به مو د مرګ نه بچ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_020.mp3', NULL, 1761758886, 1761758886),
(40514, 'Job 5:21', 'Job', 5, 21, 'تاسو به د سپکو خبرو نه بچ شئ، او چې کله تباهى راځى نو تاسو به نۀ يرېږئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_021.mp3', NULL, 1761758886, 1761758886),
(40515, 'Job 5:22', 'Job', 5, 22, 'په تباهۍ او قحط پورې به تاسو خندا کوئ، او د زمکې د ځنګلى ځناورو نه به نۀ يرېږئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_022.mp3', NULL, 1761758886, 1761758886),
(40516, 'Job 5:23', 'Job', 5, 23, 'تاسو چې کوم پټى کَرئ نو په هغې کښې به کاڼى نۀ وى، او ځنګلى ځناور به په تاسو حمله نۀ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_023.mp3', NULL, 1761758886, 1761758886),
(40517, 'Job 5:24', 'Job', 5, 24, 'تاسو ته به پته ولګى چې ستاسو کور محفوظ دے، تاسو به وګورئ چې ستاسو د رَمو نه به هيڅ ورک نۀ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_024.mp3', NULL, 1761758886, 1761758886),
(40518, 'Job 5:25', 'Job', 5, 25, 'تاسو ته به پته ولګى چې ستاسو اولاد به ډېر وى، داسې بې‌شمېره لکه په زمکه چې واښۀ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_025.mp3', NULL, 1761758886, 1761758886),
(40519, 'Job 5:26', 'Job', 5, 26, 'تاسو به خپل قبر ته په بوډاتوب کښې ځئ، لکه چې د فصل ګېډۍ درمند ته په خپل موسم کښې راځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_026.mp3', NULL, 1761758886, 1761758886),
(40520, 'Job 5:27', 'Job', 5, 27, 'ګوره، زمونږه چې د عمر په حقله کومه تجربه ده، دا حقيقت دے. دا نصيحت واوره او په دې باندې عمل وکړه.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job5_verse_027.mp3', NULL, 1761758886, 1761758886),
(40521, 'Deuteronomy 8:1', 'Deuteronomy', 8, 1, 'په وفادارۍ سره د هغو ټولو قوانینو څخه پیروي وکړئ چې نن یې تاسو ته درکوم ترڅو ژوند وکړئ، شمېر مو زیات شي او هغې خاورې ته چې د هغې وعده څښتن ستاسو د نیکونو سره کړې ده، ورننوځئ او هغه ونیسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_001.mp3', NULL, 1761758886, 1761758886),
(40522, 'Deuteronomy 8:2', 'Deuteronomy', 8, 2, 'در په یاد کړئ چې په تېرو څلوېښتو کلونو کې ستاسو څښتن خدای څنګه تاسو ته په دښته کې په دې اوږده سفر کې لارښوونه وکړه. په تاسو باندې یې سختۍ راوستلې چې ومو ازمایي، ترڅو هغه پوه شي چې ستاسو په زړونو کې څه دي او د هغه په حکمونو باندې عمل کوئ یا نه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_002.mp3', NULL, 1761758886, 1761758886),
(40523, 'Deuteronomy 8:3', 'Deuteronomy', 8, 3, 'هغه په تاسو باندې لوږه راوستله او بیا یې د خوراک دپاره من درکړ، یعنې هغه خواړه چې تاسو او ستاسو نیکونو مخکې هېڅکله خوړلي نه وو. هغه د دې دپاره دا کار وکړ چې تاسو ته دا خبره درزده کړي چې انسان یوازې په ډوډۍ نه بلکې په هره خبره باندې ژوندی دی چې د څښتن د خولې څخه راوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_003.mp3', NULL, 1761758886, 1761758886),
(40524, 'Deuteronomy 8:4', 'Deuteronomy', 8, 4, 'د دغو څلوېښتو کلونو په دوران کې ستاسو کالي نه دي زاړه شوي او نه مو پښې پړسېدلې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_004.mp3', NULL, 1761758886, 1761758886),
(40525, 'Deuteronomy 8:5', 'Deuteronomy', 8, 5, 'په یاد لرئ چې ستاسو څښتن خدای تاسو اصلاح کوي او داسې سزا درکوي لکه څنګه چې یو پلار خپل اولادونه اصلاح کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_005.mp3', NULL, 1761758886, 1761758886),
(40526, 'Deuteronomy 8:6', 'Deuteronomy', 8, 6, 'نو بیا هغه کار کوئ چې څښتن یې درباندې امر کړی دی، یعنې د هغه د قوانینو سره سم ژوند کوئ او د هغه څخه وېرېږئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_006.mp3', NULL, 1761758886, 1761758886),
(40527, 'Deuteronomy 8:7', 'Deuteronomy', 8, 7, 'ستاسو څښتن خدای تاسو یوې حاصلخېزې ځمکې یعنې داسې ځمکې ته راولي چې سیندونه او چینې لري او د ځمکې لاندې داسې ویالې لري چې اوبه یې درو او غونډیو ته راوځي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_007.mp3', NULL, 1761758886, 1761758886),
(40528, 'Deuteronomy 8:8', 'Deuteronomy', 8, 8, 'یوه داسې ځمکه چې غنم او اوربشې، انګور، انځر، انار، زیتون او شات په کې پیدا کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_008.mp3', NULL, 1761758886, 1761758886),
(40529, 'Deuteronomy 8:9', 'Deuteronomy', 8, 9, 'دا داسې وطن دی چې خواړه په کې پرېمانه دي او د هېڅ شي کمی په کې نشته. د دې ځای تیږې د اوسپنې څخه ډکې دي او د غونډیو څخه یې مس راویستلی شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_009.mp3', NULL, 1761758886, 1761758886),
(40530, 'Deuteronomy 8:10', 'Deuteronomy', 8, 10, 'هرڅه چې تاسو غواړئ وخورئ هغه به درورسیږي او تاسو به د هغې حاصلخېزې ځمکې دپاره چې ستاسو څښتن خدای درکړې ده د هغه شکر ادا کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_010.mp3', NULL, 1761758886, 1761758886),
(40531, 'Deuteronomy 8:11', 'Deuteronomy', 8, 11, 'پام کوئ چې تاسو به هېڅکله خپل څښتن خدای نه هېروئ. هېڅکله د هغه د هغو قوانینو څخه سرغړونه ونه کړئ چې نن یې تاسو ته درکوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_011.mp3', NULL, 1761758886, 1761758886),
(40532, 'Deuteronomy 8:12', 'Deuteronomy', 8, 12, 'کله چې تاسو ته د خوراک دپاره هرڅه درورسیږي او د اوسېدلو دپاره ښه ښه کورونه ودان کړئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_012.mp3', NULL, 1761758886, 1761758886),
(40533, 'Deuteronomy 8:13', 'Deuteronomy', 8, 13, 'او کله چې ستاسو پادې او رمې، ستاسو سپین زر او سره زر او نور ټول شیان زیات شي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_013.mp3', NULL, 1761758886, 1761758886),
(40534, 'Deuteronomy 8:14', 'Deuteronomy', 8, 14, 'نو پام کوئ چې تاسو به نه مغروره کېږئ او خپل څښتن خدای به چې تاسو یې د مصر د غلامۍ څخه ازاد کړئ، نه هېروئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_014.mp3', NULL, 1761758886, 1761758886),
(40535, 'Deuteronomy 8:15', 'Deuteronomy', 8, 15, 'هغه د هغې پراخې او وېروونکې دښتې په لاره تاسو بوتلئ چې زهرجن ماران او لړمان په کې وو. هغه په هغې وچې او بې اوبو ځمکه کې د کلک ګټ څخه ستاسو دپاره اوبه راوویستلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_015.mp3', NULL, 1761758886, 1761758886),
(40536, 'Deuteronomy 8:16', 'Deuteronomy', 8, 16, 'هغه په دښته کې تاسو ته د خوراک دپاره من درکړ چې داسې خواړه وو چې ستاسو نیکونو هېڅکله خوړلي نه وو. له دې امله هغه په تاسو باندې سختۍ راوستلې چې تاسو وازمایي، ترڅو په اخر کې هغه تاسو ته د ښو ښو شیانو سره برکت درکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_016.mp3', NULL, 1761758886, 1761758886),
(40537, 'Deuteronomy 8:17', 'Deuteronomy', 8, 17, 'نو بیا باید هېڅکله داسې فکر ونه کړئ چې تاسو په خپل قدرت او قوت سره خپل ځانونه شتمن کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_017.mp3', NULL, 1761758886, 1761758886),
(40538, 'Deuteronomy 8:18', 'Deuteronomy', 8, 18, 'په یاد ولرئ چې دا ستاسو څښتن خدای دی چې تاسو ته دا توان درکوي چې شتمن شئ. څښتن ځکه دا کار کوي چې هغه نن هم هغه لوظ ته وفادار پاتې دی چې ستاسو د نیکونو سره یې کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy8_verse_018.mp3', NULL, 1761758886, 1761758886),
(40539, 'Hosea 9:1', 'Hosea', 9, 1, 'ای د اسراییلو خلکو، د نورو قومونو د اخترونو د لمانځلو نه لاس واخلئ، ځکه چې تاسو خپل خدای پریښی دی او د هغه سره مو بې‌وفایي کړې ده. تاسو بتانو ته په عبادت کولو سره په ټولو ځایونو خپل ځانونه لکه د فاحشو په شان خرڅ کړي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_001.mp3', NULL, 1761758886, 1761758886),
(40540, 'Hosea 9:2', 'Hosea', 9, 2, 'خو اوس به نور تاسو سره په پوره اندازه غلې دانې او شراب نه وي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_002.mp3', NULL, 1761758886, 1761758886),
(40541, 'Hosea 9:3', 'Hosea', 9, 3, 'د اسراییلو خلک به نور د څښتن په وطن کې پاتې نه شي، بلکې هغوی باید بېرته مصر ته لاړ شي او په آشور کې به حرام خواړه خوري.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_003.mp3', NULL, 1761758886, 1761758886),
(40542, 'Hosea 9:4', 'Hosea', 9, 4, 'هلته به هغوی د دې توان نه لري چې څښتن ته د نذرانې په توګه شراب توی کړي او د هغوی په قربانیو باندې به څښتن خوشحاله نه شي. هرڅوک چې د هغوی خواړه وخوري، هغوی به داسې ناپاکه شي لکه څوک چې د مړي د جنازې په مراسمو کې خواړه خوري. په دې باندې به یوازې د هغوی لوږه له منځه ځي. خو هغه خواړه باید د څښتن عبادتځای ته رانه وړل شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_004.mp3', NULL, 1761758886, 1761758886),
(40543, 'Hosea 9:5', 'Hosea', 9, 5, 'نو تاسو به د اختر په ورځو کې څه کوئ او څنګه به د څښتن اخترونه لمانځئ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_005.mp3', NULL, 1761758886, 1761758886),
(40544, 'Hosea 9:6', 'Hosea', 9, 6, 'ګورئ، که څه هم هغوی به د تباهۍ څخه وتښتي، خو مصریان به هغوی سره راټول کړي او د ممفیس په ښار کې به یې ښخ کړي! په هغو ځایونو کې چې د هغوی د سپینو زرو خزانې او یو وخت په کې د هغوی کورونه وو، په هغو کې به هرزه بوټي او د اغزیو بوټي راشنه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_006.mp3', NULL, 1761758886, 1761758886),
(40545, 'Hosea 9:7', 'Hosea', 9, 7, 'اسراییلو ته د سزا ورکولو او د حساب کولو ورځ رارسېدلې ده. کله چې دا کار وشي، نو اسراییل به ورباندې پوه شي. تاسو وایئ چې دا پیغمبر کم‌عقل دی او دا د الهام رسوونکی سړی لېونی دی. تاسو داسې وایئ، ځکه چې ستاسو ګناهونه ډېر زیات دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_007.mp3', NULL, 1761758886, 1761758886),
(40546, 'Hosea 9:8', 'Hosea', 9, 8, 'پیغمبر د خدای له خوا د اسراییلو پهره‌دار دی. خو زه چې هر‌چېرته ځم، نو تاسو کوښښ کوئ چې د مرغۍ په شان مې په دام کې راګېر کړئ. حتی تر دې پورې چې د خدای په کور کې هم خلک د پیغمبر دښمنان شوي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_008.mp3', NULL, 1761758886, 1761758886),
(40547, 'Hosea 9:9', 'Hosea', 9, 9, 'هغوی په خپلو کارونو کې داسې فاسد شوي دي، لکه څنګه چې د جبعې په ښار کې وو. خدای به د هغوی ګناهونه رایاد کړي او د هغو په خاطر به ورته سزا ورکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_009.mp3', NULL, 1761758886, 1761758886),
(40548, 'Hosea 9:10', 'Hosea', 9, 10, 'څښتن وایي: «کله چې ما د لومړي ځل دپاره اسراییل ولیدل، نو هغه داسې وو لکه په دښته کې چې انګور پیدا شي. کله چې ما د لومړي ځل دپاره ستاسو نیکونه ولیدل، هغه داسې وو لکه د موسم لومړني پاخه شوي انځران مې چې لیدلي وي. خو کله چې هغوی د فغور غره ته راغلل، نو هغوی خپل ځانونه د بعل شرمناک بت ته وقف کړل او ډېر زر د بعل د بت په شان چې هغوی ورسره مینه کوله، د کرکې وړ وګرځېدل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_010.mp3', NULL, 1761758886, 1761758886),
(40549, 'Hosea 9:11', 'Hosea', 9, 11, 'د اسراییلو شان او شوکت به لکه د مرغۍ په شان والوځي او د هغوی به نور اولادونه نه پیدا کیږي، د هغوی ښځې به نورې نه امیدوارې کیږي او نه به یې اولاد په خېټه کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_011.mp3', NULL, 1761758886, 1761758886),
(40550, 'Hosea 9:12', 'Hosea', 9, 12, 'خو که د هغوی اولادونه هم پیدا شي، نو زه به یې ورڅخه واخلم او یو به یې هم ژوندی پرېنږدم. کله چې زه دا خلک پرېږدم، نو هغوی به د ډېرو وېروونکو پېښو سره مخ شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_012.mp3', NULL, 1761758886, 1761758886),
(40551, 'Hosea 9:13', 'Hosea', 9, 13, 'ما لیدلي دي چې اسراییل لکه د خرما د نیالګیو په شان په ښه ځای کې کرل شوي دي، خو هغوی باید خپل زامن جنګ ته ولېږي چې ووژل شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_013.mp3', NULL, 1761758886, 1761758886),
(40552, 'Hosea 9:14', 'Hosea', 9, 14, 'ای څښتنه، زه به ستا نه د دې خلکو دپاره د څه شي سوال وکړم؟ د هغوی ښځې شنډې کړه چې ماشومان ونه زېږوي او د هغوی په سینو کې شیدې وچې کړه چې ونه شي کولای خپل ماشومان وروزي!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_014.mp3', NULL, 1761758886, 1761758886),
(40553, 'Hosea 9:15', 'Hosea', 9, 15, 'څښتن وایي: «د هغوی ټوله بدکاري د جلجال په ښار کې پیل شوه. په هماغه ځای کې ما د هغوی څخه کرکه پیل کړه. د همدې بدو عملونو په خاطر به زه هغوی د خپل وطن نه وشړم. زه به نور د هغوی سره مینه نه کوم. د هغوی ټولو مشرانو زما په وړاندې سرکښي کړې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_015.mp3', NULL, 1761758886, 1761758886),
(40554, 'Hosea 9:16', 'Hosea', 9, 16, 'د اسراییلو خلک د هغه بوټي په شان دي چې ریښې یې وچې شوې وي او مېوه نه نیسي. د هغوی به اولادونه نه پیدا کیږي، خو که پیدا هم شي، زه به د ‎هغوی ګران اولادونه ووژنم.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_016.mp3', NULL, 1761758886, 1761758886),
(40555, 'Hosea 9:17', 'Hosea', 9, 17, 'زما خدای به هغوی پرېږدي، ځکه چې هغوی د هغه خبرو ته غوږ ونه نیوه. نو هغوی به د نورو قومونو په منځ کې سرګردانه ګرځي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea9_verse_017.mp3', NULL, 1761758886, 1761758886),
(40556, 'Leviticus 19:1', 'Leviticus', 19, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_001.mp3', NULL, 1761758886, 1761758886),
(40557, 'Leviticus 19:2', 'Leviticus', 19, 2, '«د اسراییلو د ټول قوم سره خبرې وکړه او ورته ووایه: سپېڅلي اوسئ، ځکه چې زه ستاسو څښتن خدای سپېڅلی یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_002.mp3', NULL, 1761758886, 1761758886),
(40558, 'Leviticus 19:3', 'Leviticus', 19, 3, 'تاسو هر یو باید د خپل مور او پلار درناوی وکړئ او باید د سبت د ورځې څخه پیروي وکړئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_003.mp3', NULL, 1761758886, 1761758886),
(40559, 'Leviticus 19:4', 'Leviticus', 19, 4, 'ما مه پرېږدئ او د بتانو عبادت مه کوئ. د فلزاتو څخه خدایان مه جوړوئ او عبادت یې مه کوئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_004.mp3', NULL, 1761758886, 1761758886),
(40560, 'Leviticus 19:5', 'Leviticus', 19, 5, 'کله چې تاسو د سلامتۍ د نذرانې دپاره څښتن ته یو حیوان قرباني کوئ، هغه په یوې داسې طریقې سره قرباني کړئ چې زما له خوا قبوله شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_005.mp3', NULL, 1761758886, 1761758886),
(40561, 'Leviticus 19:6', 'Leviticus', 19, 6, 'غوښه باید په هماغه ورځ چې قرباني کوئ وخورئ یا په راتلونکې ورځ. هرڅه چې تر درېمې ورځې پورې پاتې شي، باید وسوځول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_006.mp3', NULL, 1761758886, 1761758886),
(40562, 'Leviticus 19:7', 'Leviticus', 19, 7, 'که چېرې د هغې څخه لږه په درېمه ورځ وخوړل شي، هغه ناپاکه ده او دا نذرانه به قبوله نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_007.mp3', NULL, 1761758886, 1761758886),
(40563, 'Leviticus 19:8', 'Leviticus', 19, 8, 'هرڅوک چې هغه وخوري، هغه به ګناهکار وي، ځکه چې هغه څه چې څښتن ته سپېڅلي دي، هغه یې عادي ګڼلي دي. هغه کس باید د خدای د قوم څخه وشړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_008.mp3', NULL, 1761758886, 1761758886),
(40564, 'Leviticus 19:9', 'Leviticus', 19, 9, 'کله چې تاسو د خپلې ځمکې حاصلات لو کوئ، نو هغه د پټي تر غاړو پورې مه لو کوئ او هغه وږي چې د لو څخه پاتې شوي وي، هغه مه راټولوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_009.mp3', NULL, 1761758886, 1761758886),
(40565, 'Leviticus 19:10', 'Leviticus', 19, 10, 'خپل د انګورو باغ ته دوهم ځل مه ورځئ او هغه انګور مه راټولوئ چې رالوېدلي وي. هغه غریبانو او پردیو خلکو ته پرېږدئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_010.mp3', NULL, 1761758886, 1761758886),
(40566, 'Leviticus 19:11', 'Leviticus', 19, 11, 'غلا مه کوئ. یو بل ته دروغ مه وایئ او یو بل مه غولوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_011.mp3', NULL, 1761758886, 1761758886),
(40567, 'Leviticus 19:12', 'Leviticus', 19, 12, 'زما په نوم په دروغو قسم مه خورئ او په دې ډول د خپل خدای نوم مه سپکوئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_012.mp3', NULL, 1761758886, 1761758886),
(40568, 'Leviticus 19:13', 'Leviticus', 19, 13, 'خپل ګاونډی مه لوټوئ او هغه مه غولوئ. د یو مزدور اجوره حتی د یوې شپې دپاره هم مه ځنډوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_013.mp3', NULL, 1761758886, 1761758886),
(40569, 'Leviticus 19:14', 'Leviticus', 19, 14, 'کڼو خلکو ته ښکنځلې مه کوئ او د ړندو په مخکې داسې شی مه ږدئ چې هغوی ورباندې وښوییږي، زما څخه ووېرېږئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_014.mp3', NULL, 1761758886, 1761758886),
(40570, 'Leviticus 19:15', 'Leviticus', 19, 15, 'عدالت تر پښو مه لاندې کوئ. د غریب طرفداري مه کوئ او د لویانو خاطر مه کوئ، خو د نورو سره په انصاف قضاوت وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_015.mp3', NULL, 1761758886, 1761758886),
(40571, 'Leviticus 19:16', 'Leviticus', 19, 16, 'د هېچا په اړه دروغ مه خپروئ او کله چې یو کس په محکمه کې په مرګ باندې محکوم وي، نو ښکاره خبرې وکړئ، کېدای شي چې ستاسو شاهدي د هغه سره مرسته وکړي. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_016.mp3', NULL, 1761758886, 1761758886),
(40572, 'Leviticus 19:17', 'Leviticus', 19, 17, 'د خپل ورور سره په خپل زړه کې کینه مه ساتئ. هغه په ښکاره د خپلې ګناه په خاطر ورټئ، ترڅو د هغه په ګناه کې شریک نه شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_017.mp3', NULL, 1761758886, 1761758886),
(40573, 'Leviticus 19:18', 'Leviticus', 19, 18, 'د خپلو خلکو څخه د بدل اخیستلو پسې مه ګرځئ. د هغوی څخه کرکه مه کوئ، خو د خپل ګاونډي سره د خپل ځان په شان مینه کوئ. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_018.mp3', NULL, 1761758886, 1761758886),
(40574, 'Leviticus 19:19', 'Leviticus', 19, 19, 'زما د فرمانونو څخه پیروي وکړئ. غیر همجنس کورني حیوانات د نسل د پیدا کولو دپاره سره مه یوځای کوئ. په خپل پټي کې دوه ډوله تخمونه مه کرئ. داسې کالي مه اغوندئ چې د دوو مختلفو جنسونو څخه جوړ شوي وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_019.mp3', NULL, 1761758886, 1761758886),
(40575, 'Leviticus 19:20', 'Leviticus', 19, 20, 'که چېرې یو کس د یوې داسې وینځې سره چې هغه د بل کس سره کوژدن شوې وي زنا وکړي، که څه هم هغه بل کس د هغې د ازادېدلو په خاطر پیسې نه وي ورکړې، نو باید هغې وینځې او هغه کس ته چې د هغې سره یې زنا کړې وه، سزا ورکړل شي. خو هغوی دې ونه وژل شي، ځکه چې هغه ازاده شوې نه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_020.mp3', NULL, 1761758886, 1761758886),
(40576, 'Leviticus 19:21', 'Leviticus', 19, 21, 'هغه سړی به د تاوان د نذرانې په توګه یو پسه د سپېڅلې خېمې د دروازې په خوله کې څښتن ته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_021.mp3', NULL, 1761758886, 1761758886),
(40577, 'Leviticus 19:22', 'Leviticus', 19, 22, 'په هغه باندې به کاهن د څښتن په حضور کې د هغه د ګناه په خاطر کفاره ادا کړي او د هغه ګناه به وبخښل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_022.mp3', NULL, 1761758886, 1761758886),
(40578, 'Leviticus 19:23', 'Leviticus', 19, 23, 'کله چې تاسو د کنعان خاورې ته ورننوځئ او د مېوې یوه ونه وکرئ، هغه مېوه د لومړنیو درېو کلونو دپاره حرامه وګڼئ. په دې موده کې تاسو باید هغه مېوه ونه خورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_023.mp3', NULL, 1761758886, 1761758886),
(40579, 'Leviticus 19:24', 'Leviticus', 19, 24, 'په څلورم کال به هغه ټوله مېوه ما یعنې څښتن ته د شکرګزارۍ په خاطر وقف شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_024.mp3', NULL, 1761758886, 1761758886),
(40580, 'Leviticus 19:25', 'Leviticus', 19, 25, 'خو په پنځم کال به هغه مېوه تاسو ته حلاله وي. که چېرې تاسو دا ټول کارونه وکړئ، ستاسو ونې به زیاته مېوه ونیسي. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_025.mp3', NULL, 1761758886, 1761758886),
(40581, 'Leviticus 19:26', 'Leviticus', 19, 26, 'داسې غوښه مه خورئ چې وینه په کې وي. فال مه ګورئ او کوډې مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_026.mp3', NULL, 1761758886, 1761758886),
(40582, 'Leviticus 19:27', 'Leviticus', 19, 27, 'د خپلو شقیقو ویښتان مه خرایئ او ږیره مه لنډوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_027.mp3', NULL, 1761758886, 1761758886),
(40583, 'Leviticus 19:28', 'Leviticus', 19, 28, 'د مړي په غم کې خپل بدنونه مه غوڅوئ او خالونه ورباندې مه جوړوئ. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_028.mp3', NULL, 1761758886, 1761758886),
(40584, 'Leviticus 19:29', 'Leviticus', 19, 29, 'د خپلو لورګانو څخه بدلمنې مه جوړوئ او هغوی مه شرموئ. که داسې وکړئ، نو دا خاوره به په بدلمنۍ بدله شي او د بدکارۍ څخه به ډکه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_029.mp3', NULL, 1761758886, 1761758886),
(40585, 'Leviticus 19:30', 'Leviticus', 19, 30, 'د سبت د ورځې څخه پیروي وکړئ او د هغه ځای درناوی وکړئ چې زما عبادت په کې کیږي. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_030.mp3', NULL, 1761758886, 1761758886),
(40586, 'Leviticus 19:31', 'Leviticus', 19, 31, 'هغو خلکو ته مه ورځئ چې هغوی دعوه کوي چې دوی کولای شي د مړو سره خبرې وکړي. همدارنګه د فال کتونکو پسې مه ګرځئ، ځکه چې د هغوی په وسیله به تاسو ناپاک شئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_031.mp3', NULL, 1761758886, 1761758886),
(40587, 'Leviticus 19:32', 'Leviticus', 19, 32, 'د سپین ږیرو په مخکې پاڅېږئ، د مشرانو درناوی کوئ او زما څخه وېرېږئ. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_032.mp3', NULL, 1761758886, 1761758886),
(40588, 'Leviticus 19:33', 'Leviticus', 19, 33, 'د هغو پردیو خلکو سره بد چلند مه کوئ چې ستاسو په خاوره کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_033.mp3', NULL, 1761758886, 1761758886),
(40589, 'Leviticus 19:34', 'Leviticus', 19, 34, 'د هغوی سره د یو اسراییلي په شان چلند وکړئ او د خپلو ځانونو په شان ورسره مینه وکړئ. دا یاد ساتئ چې تاسو هم یو وخت د مصر په خاوره کې پردي وئ. زه ستاسو څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_034.mp3', NULL, 1761758886, 1761758886),
(40590, 'Leviticus 19:35', 'Leviticus', 19, 35, 'کله چې تاسو یو شی اندازه کوئ یا هغه وزن کوئ، نو غلطي په کې مه کوئ او هېڅوک مه غولوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_035.mp3', NULL, 1761758886, 1761758886),
(40591, 'Leviticus 19:36', 'Leviticus', 19, 36, 'د سمو ترازوګانو، سمو وزنونو او سمو اندازو څخه کار اخلئ. زه ستاسو څښتن خدای یم او ما تاسو د مصر څخه راوویستلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_036.mp3', NULL, 1761758886, 1761758886),
(40592, 'Leviticus 19:37', 'Leviticus', 19, 37, 'زما د ټولو فرمانونو او قوانینو څخه پیروي کوئ. زه څښتن یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus19_verse_037.mp3', NULL, 1761758886, 1761758886),
(40593, 'Exodus 38:1', 'Exodus', 38, 1, 'بزل ییل د اکاسۍ د لرګي څخه یو د قربانۍ ځای جوړ کړ چې یو متر او دېرش سانتي لوړ ؤ. هغه څلور کنجه ؤ، دوه متره او شل سانتي اوږد ؤ او دوه متره او شل سانتي پلن ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_001.mp3', NULL, 1761758886, 1761758886),
(40594, 'Exodus 38:2', 'Exodus', 38, 2, 'هغه د څلورو کنجونو دپاسه ښکرونه جوړ کړل چې هغه د قربانۍ د خای سره ټول د یوې ټوټې لرګي څخه جوړ شول او ټولو ته یې د برنجو پوښ ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_002.mp3', NULL, 1761758886, 1761758886),
(40595, 'Exodus 38:3', 'Exodus', 38, 3, 'د هغه ټول سامان یې د برنجو څخه جوړ کړ، یعنې د ایرو د لېرې کولو لوښي او د هغه بېلچې، د وینې د شیندلو کاسې، د غوښې قاشق پنجې او د اور لوښي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_003.mp3', NULL, 1761758886, 1761758886),
(40596, 'Exodus 38:4', 'Exodus', 38, 4, 'هغه یوه د برنجو جالۍ جوړه کړه او د قربانۍ د ځای د څنډې لاندې یې کېښودله، ترڅو د قربانۍ د ځای تر نیمایي پورې ورسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_004.mp3', NULL, 1761758886, 1761758886),
(40597, 'Exodus 38:5', 'Exodus', 38, 5, 'د دې دپاره یې د برنجو کړۍ ګانې جوړې کړې چې د جالۍ د څلورو کنجونو میلې ونیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_005.mp3', NULL, 1761758886, 1761758886),
(40598, 'Exodus 38:6', 'Exodus', 38, 6, 'د اکاسۍ د لرګي څخه یې د وړلو میلې جوړې کړې او د برنجو پوښ یې ورته ورکړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_006.mp3', NULL, 1761758886, 1761758886),
(40599, 'Exodus 38:7', 'Exodus', 38, 7, 'او د قربانۍ د ځای د دواړو اړخونو په کړیو کې یې ولګولې. د قربانۍ ځای د تختو څخه جوړ شوی ؤ او تش ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_007.mp3', NULL, 1761758886, 1761758886),
(40600, 'Exodus 38:8', 'Exodus', 38, 8, 'بزل ییل برنجي تشت او د هغه برنجي پایه د هغو ښځو د برنجي آیینو څخه جوړ کړل چې د سپېڅلې خېمې په دروازه کې یې خدمت کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_008.mp3', NULL, 1761758886, 1761758886),
(40601, 'Exodus 38:9', 'Exodus', 38, 9, 'بزل ییل د سپېڅلې خېمې دپاره یوه حوېلۍ جوړه کړه. جنوب خوا یې پنځه څلوېښت متره اوږده وه او د ښه کتان پردې یې درلودلې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_009.mp3', NULL, 1761758886, 1761758886),
(40602, 'Exodus 38:10', 'Exodus', 38, 10, 'چې د برنجو په شلو پایو کې د شلو برنجي ستنو په وسیله ټینګې شوې وې، چې د سپینو زرو څخه جوړ شوي چنګکونه او سیخونه په کې وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_010.mp3', NULL, 1761758886, 1761758886),
(40603, 'Exodus 38:11', 'Exodus', 38, 11, 'حوېلۍ د شمال خواته هم همداسې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_011.mp3', NULL, 1761758886, 1761758886),
(40604, 'Exodus 38:12', 'Exodus', 38, 12, 'د حوېلۍ په لوېدیځه خوا کې پردې وې چې دوه ویشت متره اوږدې وې او لس ستنې او پایې یې درلودلې چې د سپینو زرو څخه جوړ شوي چنګکونه او سیخونه ورسره وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_012.mp3', NULL, 1761758886, 1761758886),
(40605, 'Exodus 38:13', 'Exodus', 38, 13, 'ختیځې خواته یعنې هغه ځای کې چې د ننوتلو دروازه وه، هم حوېلۍ دوه ویشت متره پلنه وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_013.mp3', NULL, 1761758886, 1761758886),
(40606, 'Exodus 38:16', 'Exodus', 38, 16, 'د حوېلۍ ګردچاپېره ټولې پردې د ښه کتان څخه جوړې شوې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_016.mp3', NULL, 1761758886, 1761758886),
(40607, 'Exodus 38:17', 'Exodus', 38, 17, 'د ستنو دپاره چې کومې پایې وې، هغه د برنجو څخه جوړې شوې وې او چنګکونه، سیخونه او د ستنو د سرونو پوښونه د سپینو زرو څخه جوړ شوي وو. د حوېلۍ ګردچاپېره ټولې ستنې د سپینو زرو د سیخونو سره نښلول شوې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_017.mp3', NULL, 1761758886, 1761758886),
(40608, 'Exodus 38:18', 'Exodus', 38, 18, 'د حوېلۍ د دروازې پرده د ابي، بانجاني او سرو وړیو او د ښه کتان څخه جوړه شوې وه او ګلدوزي شوې وه. هغه نهه متره اوږده او د حوېلۍ د پردو په شان دوه متره او شل سانتي لوړه وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_018.mp3', NULL, 1761758886, 1761758886),
(40609, 'Exodus 38:19', 'Exodus', 38, 19, 'هغه په څلورو داسې ستنو باندې ټینګه شوې وه چې په څلورو برنجي پایو کې وې. چنګکونه، د سرونو پوښونه او سیخونه یې د سپینو زرو څخه جوړ شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_019.mp3', NULL, 1761758886, 1761758886),
(40610, 'Exodus 38:20', 'Exodus', 38, 20, 'د خېمې او د هغې د ګردچاپېره حوېلۍ ټول موږي برنجي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_020.mp3', NULL, 1761758886, 1761758886),
(40611, 'Exodus 38:21', 'Exodus', 38, 21, 'دا هغه لست دی چې د فلزاتو هغه اندازه په کې ده چې په سپېڅلې خېمه کې په هغه ځای کې ورڅخه کار واخیستل شو چې د تیږو دوه لوحې چې لس حکمونه ورباندې لیکل شوي وو، ساتل شوې وې. د لست فرمایش موسی ورکړی ؤ او هغو لاویانو جوړ کړ چې د هارون کاهن د زوی ایتامار تر لارښوونې لاندې یې کار کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_021.mp3', NULL, 1761758886, 1761758886),
(40612, 'Exodus 38:22', 'Exodus', 38, 22, 'د یهودا د قبیلې بزل ییل د اوري زوی او د حور لمسي هغه ټول شیان جوړ کړل چې د هغو د جوړولو حکم څښتن په موسی باندې کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_022.mp3', NULL, 1761758886, 1761758886),
(40613, 'Exodus 38:23', 'Exodus', 38, 23, 'د هغه سره د دان د قبیلې د اخیسامک زوی اهولیاب ؤ، هغه یو کسبګر او طرح کوونکی ؤ او د ابي، بانجاني او سرو وړیو او د ښه کتان ګلدوز هم ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_023.mp3', NULL, 1761758886, 1761758886),
(40614, 'Exodus 38:24', 'Exodus', 38, 24, 'د هغو ټولو سرو زرو وزن چې خلکو څښتن ته وقف کړي وو او د سپېڅلي ځای په کار کې ورڅخه کار واخیستل شو، زر کیلو ګرامه ؤ. دا د هغه وزن له مخې وو چې په سپېڅلي ځای کې ورڅخه کار اخیستل کېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_024.mp3', NULL, 1761758886, 1761758886),
(40615, 'Exodus 38:25', 'Exodus', 38, 25, 'د هغو سپینو زرو اندازه چې د اسراییلو د قوم د هغو خلکو څخه تر لاسه شول چې په سرشمېرنه کې شمېرل شوي وو، ۳۴۲۵ کیلو ګرامه وه، د هغه وزن له مخې چې په سپېڅلي ځای کې ورڅخه کار اخیستل کېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_025.mp3', NULL, 1761758886, 1761758886),
(40616, 'Exodus 38:26', 'Exodus', 38, 26, 'د کس په سر یو مثقال راتله، (دا مثقال د سپېڅلي ځای د مثقال له مخې ؤ)، ټول خلک چې شمېرل شوي وو او عمر یې د شلو کالو څخه زیات ؤ، ټول ۶۰۳۵۵۰ تنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_026.mp3', NULL, 1761758886, 1761758886),
(40617, 'Exodus 38:27', 'Exodus', 38, 27, 'د سپینو زرو څخه ۳۴۰۰ کیلو ګرامه د دې دپاره وکارول شول چې د سپېڅلي ځای او پردې دپاره سل پایې جوړې شي او د هرې پایې دپاره څلوردېرش کیلو ګرامه کارول شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_027.mp3', NULL, 1761758886, 1761758886),
(40618, 'Exodus 38:28', 'Exodus', 38, 28, 'د پاتې پنځه ویشتو کیلو ګرامو سپینو زرو څخه بزل ییل سیخونه، د ستنو دپاره چنګکونه او د هغو د سرونو دپاره پوښونه جوړ کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_028.mp3', NULL, 1761758886, 1761758886),
(40619, 'Exodus 38:29', 'Exodus', 38, 29, 'د هغو برنجو اندازه چې خلکو څښتن ته وقف کړي وو، ۲۴۰۰ کیلو ګرامه وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_029.mp3', NULL, 1761758886, 1761758886),
(40620, 'Exodus 38:30', 'Exodus', 38, 30, 'هغه له دې برنجو څخه د لاندېنیو شیانو په جوړولو کې کار واخیست: د سپېڅلې خېمې د دروازې دپاره پایې، د قربانۍ برنجي ځای او د هغې جالۍ او ټول لوښي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_030.mp3', NULL, 1761758886, 1761758886),
(40621, 'Exodus 38:31', 'Exodus', 38, 31, 'د ګردچاپېره حوېلۍ او د هغې د دروازې دپاره پایې او د خېمې او ګردچاپېره حوېلۍ دپاره ټول موږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus38_verse_031.mp3', NULL, 1761758886, 1761758886),
(40622, 'Psalms 31:1', 'Psalms', 31, 1, 'ما پناه راوړې تاته ای څښتنه! مه پرېږده مې ته هېڅکله خجالت ته ته عادل یې ماته راکړه نجات', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_001.mp3', NULL, 1761758886, 1761758886),
