(40624, 'Psalms 31:3', 'Psalms', 31, 3, 'زما کلا او پناه ځای یې ته ته د خپل نوم په خاطر وکړه هدایت او لارښوونه راته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_003.mp3', NULL, 1761758886, 1761758886),
(40625, 'Psalms 31:4', 'Psalms', 31, 4, 'ما له هغه دامه وساته چې دوی دی راته ایښی ځکه ته مې پناه ځای یې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_004.mp3', NULL, 1761758886, 1761758886),
(40626, 'Psalms 31:5', 'Psalms', 31, 5, 'زه خپل روح سپارمه تاته ما به وژغورې څښتنه وفادار یې ته ای خدایه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_005.mp3', NULL, 1761758886, 1761758886),
(40627, 'Psalms 31:6', 'Psalms', 31, 6, 'له هغو خلکو څخه کرکه کوم چې عبادت کړي د بتانو بې‌ارزښتو خو زه په تا باندې توکل کومه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_006.mp3', NULL, 1761758886, 1761758886),
(40628, 'Psalms 31:7', 'Psalms', 31, 7, 'زه به خوشحاله یم خوښي به کوم ستا په تلپاتې مینه ځکه چې تا زما درد ولیدلو او د تکلیف نه مې خبر شولې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_007.mp3', NULL, 1761758886, 1761758886),
(40629, 'Psalms 31:8', 'Psalms', 31, 8, 'زه دې ورنه کړم په لاس د دښمنانو خوندي ځای ته دې زه بوتلم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_008.mp3', NULL, 1761758886, 1761758886),
(40630, 'Psalms 31:9', 'Psalms', 31, 9, 'رحم وکړه په ما باندې ای څښتنه ځکه یمه په تکلیف کې زما سترګې ستړې شوې له ژړا نه زه بیخي یمه ستومانه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_009.mp3', NULL, 1761758886, 1761758886),
(40631, 'Psalms 31:10', 'Psalms', 31, 10, 'ژوند مې شو په غم تالا د خفګان د لاسه عمر مې لنډ شوی زه مې خپلو ګناهونو کړم کمزوری ان هډوکي مې له کاره دي وتلي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_010.mp3', NULL, 1761758886, 1761758886),
(40632, 'Psalms 31:11', 'Psalms', 31, 11, 'راته په سپکه سترګه ګوري دښمنان ټول زما په تېره بیا ګاونډیان هغوی چې پېژني ما زړه یې چوي زما څخه کله چې دوی مې په کوڅه کې ویني دوی کاندي تېښته زما څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_011.mp3', NULL, 1761758886, 1761758886),
(40633, 'Psalms 31:12', 'Psalms', 31, 12, 'زه هرچا یمه هېر کړی لکه مړی چې څوک هېر کړي زه په شان یم د کودي چې وي چا لېرې غورځولی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_012.mp3', NULL, 1761758886, 1761758886),
(40634, 'Psalms 31:13', 'Psalms', 31, 13, 'کړي ګونګوسي راپسې ډېر دښمنان اورم یې زه له هرې خوا راباندې وېره ډېره دوی پلانونه زما په ضد جوړوي هم جوړوي مې د مرګي دسیسې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_013.mp3', NULL, 1761758886, 1761758886),
(40635, 'Psalms 31:14', 'Psalms', 31, 14, 'خو توکل زما په تا دی ای څښتنه زه دا وایم: «ته مې خدای یې»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_014.mp3', NULL, 1761758886, 1761758886),
(40636, 'Psalms 31:15', 'Psalms', 31, 15, 'زما ژوند دی ستا په لاس کې د دښمنانو د لاسونو نه مې خلاص کړه او له هغو نه مې خلاص کړه چې په ما پسې دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_015.mp3', NULL, 1761758886, 1761758886),
(40637, 'Psalms 31:16', 'Psalms', 31, 16, 'په ورین تندي وګوره خپل خدمتګار ته وژغوره ما ته په خپلې تلپاتې مینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_016.mp3', NULL, 1761758886, 1761758886),
(40638, 'Psalms 31:17', 'Psalms', 31, 17, 'ته مې مه پرېږده څښتنه چې خجل شم ځکه تاته زه فریاد کړم بدکاران دې خجالت شي پټه خوله دې دوی شي ښکته خپلو قبرو ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_017.mp3', NULL, 1761758886, 1761758886),
(40639, 'Psalms 31:18', 'Psalms', 31, 18, 'د هغوی دروغجنې ژبې دې شي غلې چې مغرور او کبرجن دي چې نېکانو پسې کړي سپکې خبرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_018.mp3', NULL, 1761758886, 1761758886),
(40640, 'Psalms 31:19', 'Psalms', 31, 19, 'څه عجیبه دا ښه شیان دي چې تا ساتلي دي هغوی ته چې کړي وېره له تا هر یو پوهیږي چې ته څومره نېک یې څنګه ته ساتې هغوی چې غواړي پناه ستا نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_019.mp3', NULL, 1761758886, 1761758886),
(40641, 'Psalms 31:20', 'Psalms', 31, 20, 'ته هغوی د نورو خلکو دسیسو نه خپل حضور کې خوندي ساتې دوی د خپلو دښمنانو له تورونو په ډاډمنه پناه ځای کې پټ ساتې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_020.mp3', NULL, 1761758886, 1761758886),
(40642, 'Psalms 31:21', 'Psalms', 31, 21, 'ثنا او صفت دې وي څښتن ته! کله چې زه په کلا بند ښار کې ګېر شوی ومه څه عجیبه مینه یې وکړه له ما سره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_021.mp3', NULL, 1761758886, 1761758886),
(40643, 'Psalms 31:22', 'Psalms', 31, 22, 'زه وېرېدلی وم او خیال مې کاوه چې ستا حضور ځینې زه لېرې شړل شوی یمه خو کله ما چې زارۍ وکړې د کومک دپاره نو تا زما دعا قبوله کړله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_022.mp3', NULL, 1761758886, 1761758886),
(40644, 'Psalms 31:23', 'Psalms', 31, 23, 'ای خپل څښتن ته وفادارو خلکو ده سره مینه وکړئ څښتن ساتنه کوي د وفادارو خلکو خو کبرجنو ته د خپل عمل پوره سزا ورکوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_023.mp3', NULL, 1761758886, 1761758886),
(40645, 'Psalms 31:24', 'Psalms', 31, 24, 'اوسئ ځواکمن او زړور ای خلکو ټول هغه چې هیله له څښتن لرئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms31_verse_024.mp3', NULL, 1761758886, 1761758886),
(40646, 'Deuteronomy 13:1', 'Deuteronomy', 13, 1, 'فرض کړئ ستاسو په منځ کې یو نبي یا یو څوک راپیدا شي چې خوبونه تعبیروي او تاسو ته د کومې معجزې یا کوم عجیبه کار په اړه پېشګویي وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_001.mp3', NULL, 1761758886, 1761758886),
(40647, 'Deuteronomy 13:2', 'Deuteronomy', 13, 2, 'که چېرې هغه نښه یا هغه عجیبه کار چې د هغه په اړه یې خبرې کړې وي، رښتیا شي او هغه ووایي: ‹راځئ چې د نورو خدایانو څخه پیروي او عبادت وکړو، هغه خدایان چې مخکې مو د هغو عبادت نه دی کړی›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_002.mp3', NULL, 1761758886, 1761758886),
(40648, 'Deuteronomy 13:3', 'Deuteronomy', 13, 3, 'نو تاسو باید د هغه نبي یا د خوب تعبیروونکي خبرو ته غوږ ونه نیسئ. ستاسو څښتن خدای په تاسو باندې د دې دپاره ازمېښت کوي چې دا معلومه کړي چې د هغه سره د زړه له کومي مینه کوئ او که نه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_003.mp3', NULL, 1761758886, 1761758886),
(40649, 'Deuteronomy 13:4', 'Deuteronomy', 13, 4, 'د څښتن څخه پیروي کوئ او د هغه څخه وېره کوئ. د هغه د امرونو څخه اطاعت کوئ، عبادت یې کوئ او ورته وفادار اوسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_004.mp3', NULL, 1761758886, 1761758886),
(40650, 'Deuteronomy 13:5', 'Deuteronomy', 13, 5, 'خو هغه خوب تعبیروونکی یا نبي ووژنئ چې تاسو ته وایي چې د څښتن یعنې هغه چا په وړاندې سرکښي وکړئ چې تاسو یې د مصر څخه چې په کې غلامان وئ، ازاد کړئ. داسې خلک بدکاره دي او هڅه کوي چې تاسو د هغې لارې څخه واړوي چې څښتن یې تاسو ته د پیروۍ کولو حکم کړی دی. د دې دپاره چې تاسو خپل ځانونه د دې بدکارۍ څخه خلاص کړئ، نو هغوی باید ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_005.mp3', NULL, 1761758886, 1761758886),
(40651, 'Deuteronomy 13:6', 'Deuteronomy', 13, 6, 'حتی کېدای شي چې خپل ورور یا خپل زوی یا خپله لور یا ښځه چې تاسو ورسره مینه کوئ یا خپل تر ټولو نژدې ملګری په پټه تاسو دې ته وهڅوي چې د نورو خدایانو عبادت وکړئ، یعنې د هغو خدایانو چې تاسو او ستاسو نیکونو یې هېڅکله عبادت نه دی کړی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_006.mp3', NULL, 1761758886, 1761758886),
(40652, 'Deuteronomy 13:7', 'Deuteronomy', 13, 7, 'کېدای شي چې د هغوی څخه کوم یو تاسو دې ته وهڅوي چې د هغو خلکو د خدایانو عبادت وکړئ چې ستاسو سره نژدې اوسیږي یا د هغو خلکو چې ستاسو څخه لېرې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_007.mp3', NULL, 1761758886, 1761758886),
(40653, 'Deuteronomy 13:8', 'Deuteronomy', 13, 8, 'خو هغه مه پرېږدئ چې تاسو وهڅوي، حتی غوږ هم ورته مه نیسئ. په هغه باندې رحم مه کوئ یا زړه ورباندې مه سوځوئ او د هغه راز پټ مه ساتئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_008.mp3', NULL, 1761758886, 1761758886),
(40654, 'Deuteronomy 13:9', 'Deuteronomy', 13, 9, 'هغه ووژنئ! لومړی یې تاسو سنګسار کړئ او بیا نور ټول خلک پرېږدئ چې سنګسار یې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_009.mp3', NULL, 1761758886, 1761758886),
(40655, 'Deuteronomy 13:10', 'Deuteronomy', 13, 10, 'هغه سنګسار کړئ چې مړ شي! ځکه چې د دې هڅه یې کړې ده چې تاسو د خپل څښتن خدای څخه چې تاسو یې د مصر څخه چې په کې غلامان وئ ازاد کړئ، واړوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_010.mp3', NULL, 1761758886, 1761758886),
(40656, 'Deuteronomy 13:11', 'Deuteronomy', 13, 11, 'نو د اسراییلو ټول قوم به د دې پېښې څخه خبر شي، نو هغوی به ووېریږي او بیا به هېڅوک داسې بد کار ونه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_011.mp3', NULL, 1761758886, 1761758886),
(40657, 'Deuteronomy 13:12', 'Deuteronomy', 13, 12, 'کله چې تاسو په هغو ښارونو کې واوسېږئ چې ستاسو څښتن خدای یې درکوي، کېدای شي تاسو واورئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_012.mp3', NULL, 1761758886, 1761758886),
(40658, 'Deuteronomy 13:13', 'Deuteronomy', 13, 13, 'چې ستاسو د قوم ځینې بدکاره خلکو د خپل ښار خلک بې لارې کړي دي چې د داسې خدایانو عبادت وکړي چې مخکې تاسو هېڅکله د هغو عبادت نه وي کړی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_013.mp3', NULL, 1761758886, 1761758886),
(40659, 'Deuteronomy 13:14', 'Deuteronomy', 13, 14, 'که چېرې تاسو داسې اوازې واورئ، د هغو په هکله پوره څېړنه وکړئ او که چېرې هغه رښتیا وي او داسې د کرکې وړ پېښه شوې وي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_014.mp3', NULL, 1761758886, 1761758886),
(40660, 'Deuteronomy 13:15', 'Deuteronomy', 13, 15, 'بیا د هغه ښار ټول خلک او د هغوی ټول حیوانات هم ووژنئ او هغه ښار په پوره توګه وران کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_015.mp3', NULL, 1761758886, 1761758886),
(40661, 'Deuteronomy 13:16', 'Deuteronomy', 13, 16, 'د هغه ځای د اوسېدونکو ټول مال او جایداد راوړئ او د ښار په چوک کې یې انبار کړئ. بیا هغه ښار د هرڅه سره چې په کې دي خپل څښتن خدای ته د نذرانې په توګه وسوځوئ. هغه باید د تل دپاره کنډواله پاتې شي او بیا هېڅکله ودان نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy13_verse_016.mp3', NULL, 1761758886, 1761758886),
(40662, 'Jeremiah 31:1', 'Jeremiah', 31, 1, 'مالِک خُدائ فرمائى چې، ”په هغه وخت کښې به زۀ د بنى اِسرائيلو د ټولو قبيلو خُدائ يم، او هغوئ به زما خلق وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_001.mp3', NULL, 1761758886, 1761758886),
(40663, 'Jeremiah 31:2', 'Jeremiah', 31, 2, 'مالِک خُدائ داسې فرمائى چې، ”د بنى اِسرائيلو کوم خلق چې د مرګ نه بچ پاتې شوى وُو ما په هغوئ په بيابان کښې فضل وکړو، کله چې هغوئ د آرام په تلاش کښې روان وُو ما د هغوئ ساتنه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_002.mp3', NULL, 1761758886, 1761758886),
(40664, 'Jeremiah 31:3', 'Jeremiah', 31, 3, 'ډېر پخوا مالِک خُدائ بنى اِسرائيلو ته راڅرګند شو، او ورته يې وفرمائيل چې، ما تاسو سره نۀ ختمېدونکې مينه کړې ده، ما تاسو په خپله مينه او رحم سره خپل ځان ته رانزدې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_003.mp3', NULL, 1761758886, 1761758886),
(40665, 'Jeremiah 31:4', 'Jeremiah', 31, 4, 'زۀ به تا بيا آباد کړم، او تۀ به بيا آباد شې، اے پېغلې اِسرائيله. تۀ به بيا تمبل راواخلې او بهر به د ګډا دپاره په خوشحالۍ سره راووځې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_004.mp3', NULL, 1761758886, 1761758886),
(40666, 'Jeremiah 31:5', 'Jeremiah', 31, 5, 'تاسو به دوباره د سامريه په غونډو باندې د انګورو باغونه وکَرئ، او څوک چې دا باغونه کَرى هغوئ به يې په مېوه خوشحاله شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_005.mp3', NULL, 1761758886, 1761758886),
(40667, 'Jeremiah 31:6', 'Jeremiah', 31, 6, 'نو هغه ورځ راروانه ده چې د اِفرائيم د غونډو نه به چوکيداران آوازونه وکړى او وائى به چې، راځئ چې صيون ته د عبادت دپاره او مالِک خُدائ خپل خُدائ پاک ته لاړ شو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_006.mp3', NULL, 1761758886, 1761758886),
(40668, 'Jeremiah 31:7', 'Jeremiah', 31, 7, 'مالِک خُدائ فرمائى چې، ”د يعقوب دپاره د خوشحالۍ سندرې ووايئ او چغې ووهئ چې بنى اِسرائيل د ټولو نه لوئ قوم دے. مالِک خُدائ ته د حمد و ثناء چغې ووهئ او ووايئ چې، اے مالِکه خُدايه، په بنى اِسرائيلو کښې پاتې شوے خپل قوم دې بچ کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_007.mp3', NULL, 1761758886, 1761758886),
(40669, 'Jeremiah 31:8', 'Jeremiah', 31, 8, 'نو زۀ به هغوئ د شمالى مُلک نه واپس راولم او د زمکې د لرو ځايونو نه به يې راغونډ کړم. تر دې چې ړاندۀ، ګوډيان، اُميدوارې ښځې او د ماشوم د پېدا کېدو په حالت کښې ښځې، نو هغوئ ټول به د لوئ قبيلې په شکل کښې دلته بيا راواپس شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_008.mp3', NULL, 1761758886, 1761758886),
(40670, 'Jeremiah 31:9', 'Jeremiah', 31, 9, 'کله چې هغوئ واپس راشى نو د پښېمانۍ نه به اوښکې د هغوئ په مخ روانې وى او زۀ به هغوئ په ډېره مينه خپلو کورونو ته واپس بوځم، نو زۀ به هغوئ د روانو اوبو په خوا کښې او په هواره لاره بوځم هسې نه چې چرته تيندک وخورى، ځکه چې زۀ د بنى اِسرائيلو پلار يم، او اِفرائيم زما مشر زوئ دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_009.mp3', NULL, 1761758886, 1761758886),
(40671, 'Jeremiah 31:10', 'Jeremiah', 31, 10, 'مالِک خُدائ فرمائى، ”اے قومونو، د مالِک خُدائ کلام واورئ، او هغه لرې ساحلى وطنونو ته يې بيان کړئ. هغه چا چې بنى اِسرائيل خوارۀ کړى دى هم هغه به يې راغونډ کړى. لکه څنګه چې شپونکے د خپلې رمې ساتنه کوى هم داسې به هغه د هغوئ خيال ساتى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_010.mp3', NULL, 1761758886, 1761758886),
(40672, 'Jeremiah 31:11', 'Jeremiah', 31, 11, 'مالِک خُدائ به د بنى اِسرائيلو فديه ورکړى او هغوئ به د هغه کسانو نه آزاد کړى چې د دوئ نه زورَور دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_011.mp3', NULL, 1761758886, 1761758886),
(40673, 'Jeremiah 31:12', 'Jeremiah', 31, 12, 'هغوئ به راشى او پاس د صيون په غرۀ به د خوشحالۍ چغې ووهى، او هغوئ به د مالِک خُدائ په برکتونو لکه غله دانه، مے، تېل، او د رمو په زياتولو خوشحاله شى. د هغوئ ژوند به لکه د سيرابه باغ په شان وى، او هغوئ به نور غمژن نۀ شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_012.mp3', NULL, 1761758886, 1761758886),
(40674, 'Jeremiah 31:13', 'Jeremiah', 31, 13, 'نو پېغلې به د خوشحالۍ نه ګډيږى، ځوانان او بوډاګان به هم خوشحالى کوى. زۀ به د هغوئ غم په خوشحالۍ باندې بدل کړم، او زۀ به هغوئ له تسلى ورکړم، او زۀ به د هغوئ خفګان په خوشحالۍ بدل کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_013.mp3', NULL, 1761758886, 1761758886),
(40675, 'Jeremiah 31:14', 'Jeremiah', 31, 14, 'زۀ به د هغوئ اِمامان په غوړو زېړو خوراکونو ماړۀ کړم، او زما خلق به زما په نعمتونو باندې ماړۀ پټ شى. مالِک خُدائ دا فرمائى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_014.mp3', NULL, 1761758886, 1761758886),
(40676, 'Jeremiah 31:15', 'Jeremiah', 31, 15, 'مالِک خُدائ فرمائى چې، ”په راما کښې د چغو آواز واورېدلے شو، د ماتم او لوئ ژړا آواز. راحيل په خپلو بچو باندې ژړا کوى، هيڅ قسم تسلى نۀ قبلوى ځکه چې د هغې ماشومان غېب کړے شوى دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_015.mp3', NULL, 1761758886, 1761758886),
(40677, 'Jeremiah 31:16', 'Jeremiah', 31, 16, 'خو مالِک خُدائ فرمائى چې، ”ژړا او اوښکې توېدل بس کړئ، تاسو ته به د خپلو کارونو اجر مِلاو شى.“ مالِک خُدائ داسې فرمائى چې، ”ستاسو ماشومان به د دشمن د مُلک نه راواپس شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_016.mp3', NULL, 1761758886, 1761758886),
(40678, 'Jeremiah 31:17', 'Jeremiah', 31, 17, 'مالِک خُدائ داسې فرمائى چې، ”ستا د راتلونکى ژوند دپاره اُميد شته دے، ستاسو ماشومان به خپل مُلک ته بيا واپس راشى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_017.mp3', NULL, 1761758886, 1761758886),
(40679, 'Jeremiah 31:18', 'Jeremiah', 31, 18, 'د اِفرائيم ژړا او فرياد ما ته رارسېدلے دے، تا ما ته تربيت راکړو چې په لاره شم، لکه د ناجوته سخى په شان دې تربيت راکړو او زۀ اوس په لاره شوے يم. ما دې خپل حضور ته واپس راوله، نو زۀ به واپس راشم، ځکه چې تۀ زما مالِک خُدائ او خُدائ پاک يې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_018.mp3', NULL, 1761758886, 1761758886),
(40680, 'Jeremiah 31:19', 'Jeremiah', 31, 19, 'ستا نه د اوړېدو نه پس مونږ توبه وکړه، د پوهېدو نه وروستو مونږ خپله سينه ووهله. مونږ چې کوم کم عقل کارونه په ځوانۍ کښې کړى وُو د هغې په وجه سپک او شرمنده شُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_019.mp3', NULL, 1761758886, 1761758886),
(40681, 'Jeremiah 31:20', 'Jeremiah', 31, 20, 'مالِک خُدائ فرمائى چې، ”ولې اِسرائيل تر اوسه زما محبوب زوئ نۀ دے څۀ په چا کښې چې زۀ خوشحالېږم؟ کۀ څۀ هم چې زۀ د دۀ خلاف بار بار خبرې کوم، نو بيا هم هغه يادوم. نو په دې وجه زما زړۀ ورپسې زهيريږى، زما په زړۀ کښې د دۀ دپاره ډېر رحم دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_020.mp3', NULL, 1761758886, 1761758886),
(40682, 'Jeremiah 31:21', 'Jeremiah', 31, 21, 'اے زما قومه، تاسو د تلو په وخت په خپله لار داسې نښې ودروئ چې د هغې نه په واپسۍ کښې خلقو ته د صحيح لارې پته ولګى. اے پېغلې اِسرائيله راوګرځه، خپلو ښارونو ته راوګرځه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_021.mp3', NULL, 1761758886, 1761758886),
(40683, 'Jeremiah 31:22', 'Jeremiah', 31, 22, 'اے زما بې‌وفا لورې، تۀ به ترڅو پورې سرګردانه ګرځې؟ مالِک خُدائ به يو نوے کار وکړى او هغه دا دے چې بنى اِسرائيل به خپل مالِک خُدائ ته غاړه ورکړى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_022.mp3', NULL, 1761758886, 1761758886),
(40684, 'Jeremiah 31:23', 'Jeremiah', 31, 23, 'مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى، ”کله چې زۀ هغوئ د غلامۍ نه واپس راولم، په يهوداه او د هغې په ښارونو کښې به هغوئ بيا داسې ووائى چې، اے د صداقت ځايه، اے مقدس غره، مالِک خُدائ دې تا له برکت درکړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_023.mp3', NULL, 1761758886, 1761758886),
(40685, 'Jeremiah 31:24', 'Jeremiah', 31, 24, 'ښاريان او زمينداران او شپونکى به د خپلو رمو سره په شريکه د يهوداه په مُلک کښې اوسيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_024.mp3', NULL, 1761758886, 1761758886),
(40686, 'Jeremiah 31:25', 'Jeremiah', 31, 25, 'زۀ به ستړو ستومانو ته طاقت ورکړم او مړاوى شوى به تازه کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_025.mp3', NULL, 1761758886, 1761758886),
(40687, 'Jeremiah 31:26', 'Jeremiah', 31, 26, 'نو کله چې زۀ راپاڅېدم او خپلې سترګې مې پرانستلې، نو زۀ پوهه شوم چې په خوږ خوب اودۀ وم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_026.mp3', NULL, 1761758886, 1761758886),
(40688, 'Jeremiah 31:27', 'Jeremiah', 31, 27, 'مالِک خُدائ فرمائى چې، ”هغه ورځ راروانه ده چې زۀ به د اِسرائيل او يهوداه او د هغوئ د ځناورو نسلونه زيات کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_027.mp3', NULL, 1761758886, 1761758886),
(40689, 'Jeremiah 31:28', 'Jeremiah', 31, 28, 'او لکه څنګه چې ما هغوئ د بېخ نه راويستل، او ټوکړې ټوکړې مې کړل، او راومې غورزول، او تباه مې کړل او افتونه مې پرې نازل کړل، نو دغه شان به زۀ هغوئ دوباره آباد او قائم کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_028.mp3', NULL, 1761758886, 1761758886),
(40690, 'Jeremiah 31:29', 'Jeremiah', 31, 29, 'په هغه ورځو کښې به نور خلق داسې نۀ وائى چې، تراوۀ انګور يې پلارانو وخوړل، او غاښونه يې د بچو وبرېښېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_029.mp3', NULL, 1761758886, 1761758886),
(40691, 'Jeremiah 31:30', 'Jeremiah', 31, 30, 'خو هر سړے به د خپلې ګناه په وجه مړ کيږى، هر څوک چې تراوۀ انګور وخورى هم د هغۀ غاښونه به برېښيږى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_030.mp3', NULL, 1761758886, 1761758886),
(40692, 'Jeremiah 31:31', 'Jeremiah', 31, 31, 'مالِک خُدائ فرمائى چې، ”هغه وخت راروان دے چې کله زۀ د اِسرائيل او د يهوداه د خلقو سره يو نوے لوظ وکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_031.mp3', NULL, 1761758886, 1761758886),
(40693, 'Jeremiah 31:32', 'Jeremiah', 31, 32, 'دا به د هغه لوظ په شان نۀ وى کوم چې ما د هغوئ د پلار نيکۀ سره کړے وو کله چې ما هغوئ د لاس نه ونيول او د مِصر نه مې بهر وويستل، ځکه چې هغوئ ما سره کړے لوظ مات کړو، کۀ څۀ هم چې زما مثال هغوئ ته د وفادار خاوند په شان وو. مالِک خُدائ داسې فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_032.mp3', NULL, 1761758886, 1761758886),
(40694, 'Jeremiah 31:33', 'Jeremiah', 31, 33, 'خو دا هغه نوے لوظ دے کوم به چې زۀ پس د دې نه د بنى اِسرائيلو د قبيلې سره وکړم، زۀ به خپل شريعت د هغوئ په مازغو کښې واچوم او د هغوئ په زړونو به يې وليکم. زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما بنده ګان وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_033.mp3', NULL, 1761758886, 1761758886),
(40695, 'Jeremiah 31:34', 'Jeremiah', 31, 34, 'نور به د هغوئ نه يو کس هم خپل ګاونډى ته، او يا خپل ورور ته دا تعليم نۀ ورکوى چې مالِک خُدائ وپېژنه، ځکه چې د وړو نه واخله تر لويو پورې به هغوئ ټول ما پېژنى، مالِک خُدائ داسې فرمائى. زۀ به د هغوئ شرارتونه معاف کړم او د هغوئ ګناهونه به نور نۀ يادوم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_034.mp3', NULL, 1761758886, 1761758886),
(40696, 'Jeremiah 31:35', 'Jeremiah', 31, 35, 'مالِک خُدائ داسې فرمائى، هغه څوک چې نمر په دې مقرروى چې د ورځې وځليږى، او هغه چا چې سپوږمۍ او ستورى مقرر کړل چې د شپې وځليږى، څوک چې سمندر راپاڅوى چې د هغې چپې شور وکړى نو د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_035.mp3', NULL, 1761758886, 1761758886),
(40697, 'Jeremiah 31:36', 'Jeremiah', 31, 36, 'مالِک خُدائ داسې فرمائى چې، ”ترڅو پورې د کائنات دا نظام موجود وى، نو تر هغه وخته پورې به د بنى اِسرائيلو قوم زما د وړاندې قائم وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_036.mp3', NULL, 1761758886, 1761758886),
(40698, 'Jeremiah 31:37', 'Jeremiah', 31, 37, 'مالِک خُدائ داسې فرمائى چې، ”لکه څنګه چې د آسمان د ناپ تول اندازه نۀ شى لګولے او د زمکې د بنياد اندازه نۀ شى معلومولے نو زۀ به هم د اِسرائيل د ګناهونو په وجه د هغوئ نه اِنکار ونۀ کړم.“ دا د مالِک خُدائ فرمان دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_037.mp3', NULL, 1761758886, 1761758886),
(40699, 'Jeremiah 31:38', 'Jeremiah', 31, 38, '”هغه ورځ راتلونکى ده،“ مالِک خُدائ فرمائى چې، ”کله چې دا ښار د حنن‌ايل د برج نه واخله تر د ګوټ د دروازې پورې به دوباره زما دپاره آباد شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_038.mp3', NULL, 1761758886, 1761758886),
(40700, 'Jeremiah 31:39', 'Jeremiah', 31, 39, 'او د هغه ځائ نه به سيدها د ښار حدود جارب غونډۍ پورې ورسيږى او بيا به د جوعه طرف ته راتاو شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_039.mp3', NULL, 1761758886, 1761758886),
(40701, 'Jeremiah 31:40', 'Jeremiah', 31, 40, 'نو بيا به ټوله دره چرته چې د مړو لاشونه او ايرې غورزولے شى او هغه ټوله زمکه د کومې مېدانونه چې د قِدرون د درې د نمرخاتۀ پورې پراتۀ دى، او د آسونو د دروازې پورې، ټوله به مالِک خُدائ ته مقدسه وى. دا ښار به هيڅکله بيا د بېخ نه راونۀ ويستلے شى او نۀ به تباه شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah31_verse_040.mp3', NULL, 1761758886, 1761758886),
(40702, 'Daniel 5:1', 'Daniel', 5, 1, 'يوه ورځ بيلشضر بادشاه يوه لويه مېلمستيا تياره کړه او د خپلو آفسرانو نه يې زر کسان راوغوښتل او د هغوئ سره يې يوځائ مے وڅښل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_001.mp3', NULL, 1761758886, 1761758886),
(40703, 'Daniel 5:2', 'Daniel', 5, 2, 'کله چې بيلشضر خپل مے څښل، نو هغۀ حکم وکړو چې هغه د سرو زرو او سپينو زرو جامونه او پيالۍ راوړئ کومې چې د هغۀ پلار نبوکدنضر په يروشلم کښې د مالِک خُدائ د کور نه راوړې وې، چې بادشاه او د هغۀ آفسران، د هغۀ ښځې او د هغۀ وينځې په کښې مے وڅښى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_002.mp3', NULL, 1761758886, 1761758886),
(40704, 'Daniel 5:3', 'Daniel', 5, 3, 'نو بيا هغوئ د سرو زرو جامونه او پيالۍ راوړې کومې چې په يروشلم کښې د خُدائ پاک د کور نه راوړلے شوې وې، او بادشاه او د هغۀ آفسرانو، د هغۀ ښځو او د هغۀ وينځو په هغو کښې وڅښل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_003.mp3', NULL, 1761758886, 1761758886),
(40705, 'Daniel 5:4', 'Daniel', 5, 4, 'کله چې هغوئ مے څښل، نو بيا هغوئ د سرو زرو، سپينو زرو، پيتلو، اوسپنو، د لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_004.mp3', NULL, 1761758886, 1761758886),
(40706, 'Daniel 5:5', 'Daniel', 5, 5, 'او ناګهانه د انسان د لاس ګوتې راښکاره شوې او د شاهى محل د دېوال په پلستر باندې د شمعدان سره نزدې ليکل وکړل. کله چې هغه لاس ليکل کول نو بادشاه په خپله هغه وليدلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_005.mp3', NULL, 1761758886, 1761758886),
(40707, 'Daniel 5:6', 'Daniel', 5, 6, 'د هغۀ رنګ د يرې نه تک زېړ شو او دومره يرېدلے وو چې د پښو د رپېدو په وجه په ځائ ودرېدلے نۀ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_006.mp3', NULL, 1761758886, 1761758886),
(40708, 'Daniel 5:7', 'Daniel', 5, 7, 'نو بادشاه په تېزه آواز وکړو چې جادوګر، فالګر او نجوميان راوغواړئ. نو د بابل دې هوښيارو سړو ته بادشاه ووئيل چې، ”هر څوک چې دا ليکلے شوى الفاظ ولولى او د هغې مطلب راته بيان کړى نو هغۀ ته به کاسنى چُوغه د عزت دپاره ورواغوستلے شى او د هغۀ په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به ورته درېم مقام مِلاو شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_007.mp3', NULL, 1761758886, 1761758886),
(40709, 'Daniel 5:8', 'Daniel', 5, 8, 'نو بيا د بادشاه ټول هوښياران راغلل، خو هغوئ هغه ليکل ونۀ شُو لوستلے او نۀ يې بادشاه ته دا وئيلے شُو چې د دې څۀ مطلب دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_008.mp3', NULL, 1761758886, 1761758886),
(40710, 'Daniel 5:9', 'Daniel', 5, 9, 'نو بيا بيلشضر بادشاه نور هم يرې واخستو او د هغۀ رنګ نور هم زېړ شو. او د هغۀ ټول آفسران هم پرېشانه شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_009.mp3', NULL, 1761758886, 1761758886),
(40711, 'Daniel 5:10', 'Daniel', 5, 10, 'خو کله چې د بادشاه مور د بادشاه او د هغۀ د مشيرانو شور شرابه واورېده، نو هغه د مېلمنو هال ته راننوتله. هغې ووئيل چې، ”اے بادشاه سلامت تۀ دې د تل دپاره ژوندے يې. مۀ وارخطا کېږه، ډېر مۀ زېړېږه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_010.mp3', NULL, 1761758886, 1761758886),
(40712, 'Daniel 5:11', 'Daniel', 5, 11, 'ستا په بادشاهۍ کښې يو سړے دے چې په هغۀ کښې د پاکو معبودانو روح دے. ستا د پلار په زمانه کښې په هغۀ کښې د معبودانو په شان عقل، حکمت او پوهه ښکاره شوه. نبوکدنضر بادشاه ستا پلار هغه د جادوګرو، فالګرو، نجوميانو او پېشګويانو والا مشر مقرر کړے وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_011.mp3', NULL, 1761758886, 1761758886),
(40713, 'Daniel 5:12', 'Daniel', 5, 12, 'دا سړے دانيال، چا ته چې بادشاه بيلطشضر نوم ورکړو، بې‌شانه قابليت او پوهه لرى، او هغه د خوبونو په تعبير، د مشکلو دوڼو په حل کولو او د راز په خبرو څرګندولو کښې تکړه او ماهِر دے. نو دانيال راوغواړه، هغه به درته ووائى چې د دې ليکلو مطلب څۀ دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_012.mp3', NULL, 1761758886, 1761758886),
(40714, 'Daniel 5:13', 'Daniel', 5, 13, 'نو بيا دانيال د بادشاه حضور ته راوستلے شو، او بادشاه هغۀ ته ووئيل، ”تۀ هغه دانيال يې څۀ، څوک چې زما پلار نبوکدنضر بادشاه د يهوداه د جلاوطنو سره د يهوداه نه دلته راوستے وو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_013.mp3', NULL, 1761758886, 1761758886),
(40715, 'Daniel 5:14', 'Daniel', 5, 14, 'ما اورېدلى دى چې په تا کښې د خُدايانو علم دے، او ستا عقل، پوهه او خاص حِکمت ډېر لوئ دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_014.mp3', NULL, 1761758886, 1761758886),
(40716, 'Daniel 5:15', 'Daniel', 5, 15, 'زما په وړاندې هوښياران او جادوګران راوستلے شوى وُو چې دا ليکلے شوى الفاظ ولولى او ما ته يې مطلب بيان کړى، خو هغوئ د دې مطلب بيان نۀ کړے شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_015.mp3', NULL, 1761758886, 1761758886),
(40717, 'Daniel 5:16', 'Daniel', 5, 16, 'خو اوس ما دا اورېدلى دى چې تۀ تعبير ورکولے شې او مشکلې مسئلې حل کولے شې. کۀ تۀ دا ليکل لوستلے شې او ما ته د دې مطلب بيانولے شې، نو ستا د عزت دپاره به تا ته کاسنى شاهى چُوغه درواغوستلے شى او ستا په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به درته درېم لوئ مقام درکړے شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_016.mp3', NULL, 1761758886, 1761758886),
(40718, 'Daniel 5:17', 'Daniel', 5, 17, 'نو دانيال بادشاه ته جواب ورکړو، ”قربان تحفې دې بل چا له ورکړه او يا يې ځان سره کړه. خو بيا به هم زۀ دا ليکل بادشاه ته ولولم او هغۀ ته به يې مطلب بيان کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_017.mp3', NULL, 1761758886, 1761758886),
(40719, 'Daniel 5:18', 'Daniel', 5, 18, 'اے بادشاه سلامت، خُدائ تعالىٰ ستا پلار نبوکدنضر ته بادشاهت، لويوالے، جلال او شان و شوکت ورکړى وُو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_018.mp3', NULL, 1761758886, 1761758886),
(40720, 'Daniel 5:19', 'Daniel', 5, 19, 'هغۀ، هغۀ له ډېر اوچت مقام ورکړے وو نو په دې وجه د ټولو خلقو د ټولو قومونو، او ټولو ژبو خلق د هغۀ په وړاندې د يرې نه ريږدېدل. څوک به چې هغۀ مړ کول غوښتل نو مړ به يې کړو، څوک به يې چې ژوندے پرېښودل غوښتل نو هغه به يې ژوندے پرېښودو، او چا ته به يې چې ترقى ورکول غوښتل نو هغۀ له به يې ترقى ورکړه، او څوک به يې چې عاجز کول غوښتل هغه به يې عاجز کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_019.mp3', NULL, 1761758886, 1761758886),
(40721, 'Daniel 5:20', 'Daniel', 5, 20, 'خو کله چې د هغۀ زړۀ مغروره شو، او کبر يې اختيار کړو، نو هغه د خپلې بادشاهۍ تخت نه کوز کړے شو او هغه د خپل عزت نه محروم کړے شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_020.mp3', NULL, 1761758886, 1761758886),
(40722, 'Daniel 5:21', 'Daniel', 5, 21, 'هغه د بنيادمو د مينځ نه وشړلے شو او هغۀ ته د ځناورو عقل ورکړے شو، او هغه د ځنګلى خرو سره اوسېدو. هغۀ لکه د څاروى په شان ګياه وخوړه، او د هغۀ بدن د آسمان په پرخه باندې تر شو، ترڅو چې هغۀ دا وپېژندل چې خُدائ تعالىٰ د بنيادمو په بادشاهت باندې اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_021.mp3', NULL, 1761758886, 1761758886),
(40723, 'Daniel 5:22', 'Daniel', 5, 22, 'خو تا د هغۀ زويه بيلشضره، خپل ځان د هغۀ په وړاندې عاجز نۀ کړے شو، باوجود د دې چې تۀ په دې هر څۀ باندې خبر وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_022.mp3', NULL, 1761758886, 1761758886),
(40724, 'Daniel 5:23', 'Daniel', 5, 23, 'بلکې، تا خپل ځان د آسمانى مالِک په خلاف راپورته کړو. د هغۀ د کور جامونه او پيالۍ ستا په وړاندې راوړلے شوى دى. تا او ستا آفسرانو، ستا ښځو، او ستا وينځو په هغې کښې مے وڅښل. تا د سرو زرو او سپينو زرو، د زېړو، د اوسپنې، لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو، څوک چې نۀ ليدلے شى او نۀ اورېدلے شى او نۀ پوهيږى. خو تا د هغه مالِک خُدائ عزت ونۀ کړو د چا په لاس کښې چې ستا ژوند او ستا ټولې لارې دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_023.mp3', NULL, 1761758886, 1761758886),
(40725, 'Daniel 5:24', 'Daniel', 5, 24, 'نو په دې وجه خُدائ پاک لاس راولېږلو کوم چې دا پېغام وليکلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_024.mp3', NULL, 1761758886, 1761758886),
(40726, 'Daniel 5:25', 'Daniel', 5, 25, 'دا هغه پېغام دے کوم چې ليکلے شوے وو، منې، منې تقيل، فرسين.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_025.mp3', NULL, 1761758886, 1761758886),
(40727, 'Daniel 5:26', 'Daniel', 5, 26, 'د دې الفاظو مطلب دا دے. منې، د دې مطلب دے شمېر، خُدائ پاک ستا د بادشاهۍ ورځې شمېرلې دى او هغه يې ختمې کړې دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_026.mp3', NULL, 1761758886, 1761758886),
(40728, 'Daniel 5:27', 'Daniel', 5, 27, 'تقيل، مطلب دے وزن، تۀ په تله باندې وتللے شوې او په وزن ډېر سپک وختلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_027.mp3', NULL, 1761758886, 1761758886),
(40729, 'Daniel 5:28', 'Daniel', 5, 28, 'د فرسين، معنىٰ دا ده چې تقسيم، ستا بادشاهى تقسيم شوې ده او هغه ميديانو او فارسيانو ته ورکړے شوې ده.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_028.mp3', NULL, 1761758886, 1761758886),
(40730, 'Daniel 5:29', 'Daniel', 5, 29, 'نو بيا د بيلشضر په حکم، دانيال ته کاسنى رنګ چُوغه ورواغوستلے شوه، د هغۀ په غاړه کښې يې د سرو زرو هار ورواچولو، او په بادشاهۍ کښې هغه د درېم اوچت مقام په توګه اعلان کړے شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_029.mp3', NULL, 1761758886, 1761758886),
(40731, 'Daniel 5:30', 'Daniel', 5, 30, 'نو په هم هغه شپه بيلشضر د بابل بادشاه ووژلے شو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_030.mp3', NULL, 1761758886, 1761758886),
(40732, 'Daniel 5:31', 'Daniel', 5, 31, 'داريوس ميدى چې د دوو شپيتو کالو وو نو بادشاهى يې ونيوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel5_verse_031.mp3', NULL, 1761758886, 1761758886),
(40733, 'Deuteronomy 24:1', 'Deuteronomy', 24, 1, 'فرض کړئ یو سړی د یوې انجلۍ سره واده وکړي او وروسته یې بد ایسي، ځکه چې په هغې کې یو داسې شی ګوري چې د هغه نه خوښیږي. نو هغه طلاق نامه لیکي، هغې ته یې ورکوي او د خپل کور څخه یې شړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_001.mp3', NULL, 1761758886, 1761758886),
(40734, 'Deuteronomy 24:2', 'Deuteronomy', 24, 2, 'بیا فرض کړئ هغه د یو بل سړي سره واده کوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_002.mp3', NULL, 1761758886, 1761758886),
(40735, 'Deuteronomy 24:3', 'Deuteronomy', 24, 3, 'او د دوهم مېړه هم هغه ښځه نه خوښیږي، نو هغه هم طلاق نامه لیکي، هغې ته یې ورکوي او د خپل کور څخه یې شړي. یا فرض کړئ د هغې دوهم مېړه مړ کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_003.mp3', NULL, 1761758886, 1761758886),
(40736, 'Deuteronomy 24:4', 'Deuteronomy', 24, 4, 'په دواړو صورتونو کې دې د هغې لومړنی مېړه بیا د هغې سره واده نه کوي، ځکه چې هغه نجسه شوې ده. که چېرې هغه ورسره بیا واده وکړي، د هغوی واده به هغه ځمکه ناپاکه کړي چې خپل څښتن خدای یې درکوي او څښتن د دې کار څخه کرکه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_004.mp3', NULL, 1761758886, 1761758886),
(40737, 'Deuteronomy 24:5', 'Deuteronomy', 24, 5, 'که چېرې یو سړي نوی واده کړی وي، هغه دې جنګ یا کومې بلې وظیفې ته نه لېږل کیږي. هغه دې یو کال د وظیفې څخه معاف وي، ترڅو هغه په کور کې پاتې شي او خپله ښځه خوشحاله وساتي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_005.mp3', NULL, 1761758886, 1761758886),
(40738, 'Deuteronomy 24:6', 'Deuteronomy', 24, 6, 'کله چې تاسو چاته کوم شی په پور ورکوئ، باید د هغه د مېچنې پلونه چې د غلو دانو د میده کولو دپاره ورڅخه کار اخیستل کیږي د ضمانت په توګه وانخلئ. په دې کار سره به د هغې کورنۍ هغه وسیله له منځه لاړه شي چې هغوی ورباندې د ژوندي پاتې کېدلو دپاره خواړه تیاروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_006.mp3', NULL, 1761758886, 1761758886),
(40739, 'Deuteronomy 24:7', 'Deuteronomy', 24, 7, 'که چېرې یو کس ونیول شي چې خپل اسراییلی ورور یې تښتاوه چې هغه خپل غلام کړي یا یې د غلام په توګه خرڅ کړي، نو تښتوونکی دې ووژل شي. په دې ډول به تاسو د دې بدکارۍ څخه خلاص شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_007.mp3', NULL, 1761758886, 1761758886),
(40740, 'Deuteronomy 24:8', 'Deuteronomy', 24, 8, 'کله چې تاسو د پوستکي په ساري ناروغۍ اخته شئ، نو څه چې لاوي کاهنان درته وایي کټ مټ هماغسې وکړئ. د هغو لارښوونو څخه پیروي وکړئ چې ما هغوی ته ورکړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_008.mp3', NULL, 1761758886, 1761758886),
(40741, 'Deuteronomy 24:9', 'Deuteronomy', 24, 9, 'په یاد ساتئ کله چې تاسو د مصر څخه راوتلئ، ستاسو څښتن خدای په مریم باندې څه وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_009.mp3', NULL, 1761758886, 1761758886),
(40742, 'Deuteronomy 24:10', 'Deuteronomy', 24, 10, 'کله چې تاسو چاته کوم شی په پور ورکوئ، د هغه کور ته د دې دپاره مه ورننوځئ چې د هغه څخه کوم شی د ضمانت په توګه واخلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_010.mp3', NULL, 1761758886, 1761758886),
(40743, 'Deuteronomy 24:11', 'Deuteronomy', 24, 11, 'دباندې انتظار وباسئ او پرېږدئ چې هغه یې په خپله تاسو ته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_011.mp3', NULL, 1761758886, 1761758886),
(40744, 'Deuteronomy 24:12', 'Deuteronomy', 24, 12, 'فرض کړئ یو کس دومره غریب وي چې یوازېنی شی چې هغه یې کولای شي تاسو ته د ضمانت په توګه درکړي د هغه چپنه وي، نو د هغه چپنه د شپې د خپل ځان سره ونه ساتئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_012.mp3', NULL, 1761758886, 1761758886),
(40745, 'Deuteronomy 24:13', 'Deuteronomy', 24, 13, 'هغه د لمرپرېواته څخه مخکې بېرته ورکړئ، ترڅو د هغې خاوند وکولای شي هغه واغوندي او ویده شي او د څښتن څخه ستاسو دپاره برکت وغواړي. نو دا کار به ستاسو د څښتن خدای په نظر کې نېک عمل وګڼل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_013.mp3', NULL, 1761758886, 1761758886),
(40746, 'Deuteronomy 24:14', 'Deuteronomy', 24, 14, 'که چېرې تاسو غریب خلک د خپل کار دپاره مزدوران ونیسئ، نو د هغوی اجوره مه ځنډوئ، که هغه اسراییلیان وي یا هغه پردي خلک چې ستاسو په ښارونو کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_014.mp3', NULL, 1761758886, 1761758886),
(40747, 'Deuteronomy 24:15', 'Deuteronomy', 24, 15, 'د هرې ورځې اجوره د لمرپرېواته څخه مخکې ورکوئ. هغوی خپل ژوند په نېستۍ کې تېروي او د ژوندي پاتې کېدلو دپاره پیسو ته اړتیا لري. که چېرې هغوی ته په خپل وخت سره اجوره ورنه کړئ، هغوی به ستاسو په ضد څښتن ته فریاد وکړي او تاسو به ګناهکار وګڼل شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_015.mp3', NULL, 1761758886, 1761758886),
(40748, 'Deuteronomy 24:16', 'Deuteronomy', 24, 16, 'پلرونه دې د هغو جرمونو په خاطر نه وژل کیږي چې د هغوی اولادونو کړي وي او اولادونه دې د هغو جرمونو په خاطر نه وژل کیږي چې د هغوی پلرونو کړي وي. هرڅوک دې یوازې د هغو جرمونو دپاره ووژل شي چې هغوی په خپله کړي وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_016.mp3', NULL, 1761758886, 1761758886),
(40749, 'Deuteronomy 24:17', 'Deuteronomy', 24, 17, 'پردي خلک او یتیمان د خپلو حقونو څخه مه محروموئ او د پور په خاطر د یوې کونډې کالي د ضمانت په توګه مه اخلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_017.mp3', NULL, 1761758886, 1761758886),
(40750, 'Deuteronomy 24:18', 'Deuteronomy', 24, 18, 'په یاد ساتئ چې تاسو په مصر کې غلامان وئ او خپل څښتن خدای ازاد کړئ، نو ځکه زه تاسو ته دا امر کوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_018.mp3', NULL, 1761758886, 1761758886),
(40751, 'Deuteronomy 24:19', 'Deuteronomy', 24, 19, 'کله چې تاسو خپل فصلونه لو کوئ او په پټي کې درڅخه کومه ګېډۍ پاتې شي، د هغې پسې بېرته مه ورځئ. هغه پردیو خلکو، یتیمانو او کونډو ته پرېږدئ، ترڅو ستاسو څښتن خدای ستاسو په هر کار کې برکت واچوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_019.mp3', NULL, 1761758886, 1761758886),
(40752, 'Deuteronomy 24:20', 'Deuteronomy', 24, 20, 'کله چې تاسو یوځل خپل زیتون راټول کړل، نو د پاتې شویو زیتونو پسې بېرته مه ورځئ چې هغه هم راوړئ. هغه د پردیو خلکو، یتیمانو او کونډو دپاره پرېږدئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_020.mp3', NULL, 1761758886, 1761758886),
(40753, 'Deuteronomy 24:21', 'Deuteronomy', 24, 21, 'کله چې تاسو یوځل خپل انګور راټول کړل، دوهم ځل تاکونو ته مه ورځئ. کوم انګور چې پاتې وي هغه د پردیو خلکو، یتیمانو او کونډو دپاره دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_021.mp3', NULL, 1761758886, 1761758886),
(40754, 'Deuteronomy 24:22', 'Deuteronomy', 24, 22, 'دا خبره هېڅکله مه هېروئ چې تاسو په مصر کې غلامان وئ، نو ځکه زه تاسو ته دا حکم کوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy24_verse_022.mp3', NULL, 1761758886, 1761758886),
(40755, 'Leviticus 5:1', 'Leviticus', 5, 1, 'په دې لاندېنیو حالتونو کې د ګناه نذرانې ضروري دي: که چېرې څوک د شاهدۍ ورکولو دپاره محکمې ته وغوښتل شي او د هغو شیانو په اړه چې هغه لیدلي یا اورېدلي دي معلومات ورنه کړي، نو هغه ته دې د خپلو بدو سزا ورکړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_001.mp3', NULL, 1761758886, 1761758886),
(40756, 'Leviticus 5:2', 'Leviticus', 5, 2, 'که چېرې د چا لاس په سهوې سره د یو شي سره چې په مذهبي لحاظ ناپاک وي لکه مړ شوي حیوان سره ولګیږي، نو کله چې پوه شي چې هغه څه کړي دي، نو هغه کس ناپاکه او ګناهکار دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_002.mp3', NULL, 1761758886, 1761758886),
(40757, 'Leviticus 5:3', 'Leviticus', 5, 3, 'که چېرې څوک په سهوې سره د انساني ناپاکۍ سره که هغه هرڅه وي ولګیږي، نو څنګه چې پوه شي چې څه یې کړي دي، هغه به ګناهکار وګڼل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_003.mp3', NULL, 1761758886, 1761758886),
(40758, 'Leviticus 5:4', 'Leviticus', 5, 4, 'که چېرې د یو چا فکر نه وي او قسم وخوري، مهمه نه ده چې د څه شي په هکله وي، څنګه چې ورڅخه خبر شي، نو هغه به ګناهکار وګڼل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_004.mp3', NULL, 1761758886, 1761758886),
(40759, 'Leviticus 5:5', 'Leviticus', 5, 5, 'کله چې څوک د دغو ګناهونو څخه یوه ګناه وکړي، هغه باید د هغې ګناه اقرار وکړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_005.mp3', NULL, 1761758886, 1761758886),
(40760, 'Leviticus 5:6', 'Leviticus', 5, 6, 'او د خپلې ګناه د جریمې په توګه باید څښتن ته د نذرانې په توګه یوه مېږه یا وزه راولي او کاهن به د هغه د ګناه دپاره کفاره ادا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_006.mp3', NULL, 1761758886, 1761758886),
(40761, 'Leviticus 5:7', 'Leviticus', 5, 7, 'که چېرې هغه کس مېږه یا وزه نه شي اخیستلی، نو څښتن ته دې د خپلې ګناه د جریمې په توګه دوه کوترې یا دوه قمري ګانې راوړي یعنې یوه د ګناه د نذرانې او بله د سوځېدونکې نذرانې دپاره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_007.mp3', NULL, 1761758886, 1761758886),
(40762, 'Leviticus 5:8', 'Leviticus', 5, 8, 'هغه دې کاهن ته راوړي او کاهن به لومړی یوه د ګناه د نذرانې دپاره وړاندې کړي. هغه دې په داسې طریقې سره د هغې ورمېږ تاو کړي چې سر ورڅخه بېل نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_008.mp3', NULL, 1761758886, 1761758886),
(40763, 'Leviticus 5:9', 'Leviticus', 5, 9, 'هغه دې د ګناه د نذرانې څخه لږه وینه د قربانۍ د ځای په اړخ کې وشیندي، پاتې وینه باید د قربانۍ د ځای په بېخ کې تویه شي. دا د ګناه نذرانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_009.mp3', NULL, 1761758886, 1761758886),
(40764, 'Leviticus 5:10', 'Leviticus', 5, 10, 'بیا به د مقرراتو له مخې هغه دوهمه مرغۍ د سوځېدونکې نذرانې په توګه وړاندې کړي. په دې ډول به کاهن د هغه کس د ګناه دپاره کفاره ادا کړي او هغه به وبخښل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_010.mp3', NULL, 1761758886, 1761758886),
(40765, 'Leviticus 5:11', 'Leviticus', 5, 11, 'که چېرې هغه کس دوه کوترې یا دوه قمري ګانې هم نه شي اخیستلی، نو د خپلې ګناه د نذرانې دپاره دې یو کیلو ګرام ښه اوړه راوړي. په هغو باندې دې د زیتونو تېل یا قیمتي خوشبویي نه اچوي، ځکه چې دا د ګناه نذرانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_011.mp3', NULL, 1761758886, 1761758886),
(40766, 'Leviticus 5:12', 'Leviticus', 5, 12, 'هغه باید کاهن ته راوړي، کاهن به د هغو اوړو څخه چې ټول څښتن ته وړاندې کیږي، یو موټی د نمونې په توګه راواخلي او د نورو نذرانو سره به یې د قربانۍ په ځای باندې وسوځوي. دا د ګناه د لېرې کولو نذرانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_012.mp3', NULL, 1761758886, 1761758886),
(40767, 'Leviticus 5:13', 'Leviticus', 5, 13, 'په دې ډول به کاهن د هغه د ګناهونو دپاره کفاره ادا کړي او هغه به وبخښل شي. پاتې نذرانه به د غلې دانې د نذرانې په شان د کاهن وي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_013.mp3', NULL, 1761758886, 1761758886),
(40768, 'Leviticus 5:14', 'Leviticus', 5, 14, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_014.mp3', NULL, 1761758886, 1761758886),
(40769, 'Leviticus 5:15', 'Leviticus', 5, 15, '«که چېرې څوک په سهوې سره هغه شیان چې څښتن ته وقف شوي دي یا د هغو بیه کاهن ته ورنه کړي، نو هغه دې د تاوان د نذرانې په توګه څښتن ته یو داسې پسه راولي چې کوم عیب په کې نه وي. د هغه بیه دې د هغو پیسو له مخې وي چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_015.mp3', NULL, 1761758886, 1761758886),
(40770, 'Leviticus 5:16', 'Leviticus', 5, 16, 'برسېره پردې، نوموړی باید هغه پیسې ورکړي چې د هغو په ورکولو نه دی بریالی شوی او شل فیصده دې زیاتې هم ورکړي. هغه به دا ټولې پیسې کاهن ته ورکوي. کاهن به د هغه دپاره په پسه باندې د تاوان د نذرانې په توګه کفاره ادا کړي او هغه به وبخښل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_016.mp3', NULL, 1761758886, 1761758886),
(40771, 'Leviticus 5:17', 'Leviticus', 5, 17, 'که چېرې څوک په سهوې سره ګناه وکړي او د څښتن د حکمونو څخه کوم حکم مات کړي، نو هغه ګناهکار دی او د هغې جرمانه به ورکوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_017.mp3', NULL, 1761758886, 1761758886),
(40772, 'Leviticus 5:18', 'Leviticus', 5, 18, 'هغه دې د تاوان د نذرانې په توګه کاهن ته یو داسې پسه راولي چې کوم عیب په کې نه وي او مناسبه بیه ولري. په دې ډول به کاهن د هغه د ګناه دپاره چې په سهوې سره یې کړې ده، کفاره ادا کړي او هغه به وبخښل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_018.mp3', NULL, 1761758886, 1761758886),
(40773, 'Leviticus 5:19', 'Leviticus', 5, 19, 'دا د هغې ګناه دپاره د تاوان یوه نذرانه ده چې د څښتن په وړاندې یې کړې ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus5_verse_019.mp3', NULL, 1761758886, 1761758886),
(40774, 'Psalms 53:1', 'Psalms', 53, 1, 'کم‌عقلان خپلو ځانونو سره وایي چې خدای نشته هغوی ټول دي فاسد شوي او کوي ډېر بد کارونه دوی کې هېڅ یو نېک کار نه کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_001.mp3', NULL, 1761758886, 1761758886),
(40775, 'Psalms 53:2', 'Psalms', 53, 2, 'په انسانانو له اسمانه خدای نظر ساتي خپل ترڅو وګوري کوم شته داسې عاقل چې رجوع وکړي هغه ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_002.mp3', NULL, 1761758886, 1761758886),
(40776, 'Psalms 53:3', 'Psalms', 53, 3, 'خو هغوی ټول مرتدان شول ورسره هم فاسدان شول دوی کې هېڅ یو نېک کار نه کړي یو هم نه کړي نېک کردار', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_003.mp3', NULL, 1761758886, 1761758886),
(40777, 'Psalms 53:4', 'Psalms', 53, 4, 'خدای کوي دغه پوښتنه: «بدکاران هېڅ نه پوهیږي؟ زما خلک داسې خوري دوی لکه وږي چې ډوډۍ خوري هېڅ دعا نه کوي ماته»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_004.mp3', NULL, 1761758886, 1761758886),
(40778, 'Psalms 53:5', 'Psalms', 53, 5, 'خو په دوی باندې به داسې وېره راشي چې به هېڅ نه وي موجود په حقیقت کې وشیندي خدای به د هغو هډوکي چا چې د خدای قوم کلابند کړی دی دغه خلک دي خدای رد کړي نو اسراییل به پوره ماتې ورکړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_005.mp3', NULL, 1761758886, 1761758886),
(40779, 'Psalms 53:6', 'Psalms', 53, 6, 'کاشکې راشي نجات د اسراییلو له صهیونه برکت چې کله بیا ورکړې خدایه خپل ولس ته بیا خوشحاله کورنۍ به د یعقوب شي اسراییل به په دې کار سره خوشحال شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms53_verse_006.mp3', NULL, 1761758886, 1761758886),
(40780, 'Zechariah 1:1', 'Zechariah', 1, 1, 'د فارس بادشاه داريوس د بادشاهۍ د دوېم کال په اتمه مياشت، د مالِک خُدائ کلام په زکرياه پېغمبر، د برکياه په زوئ چې د عدو زوئ وو نازل شو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_001.mp3', NULL, 1761758886, 1761758886),
(40781, 'Zechariah 1:2', 'Zechariah', 1, 2, '”ستاسو پلار نيکۀ ته مالِک خُدائ ډېر غصه وو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_002.mp3', NULL, 1761758886, 1761758886),
(40782, 'Zechariah 1:3', 'Zechariah', 1, 3, 'نو په دې وجه خلقو ته ووايه چې، مالِک خُدائ ربُ الافواج فرمائى چې ما ته راواپس شئ، او زۀ به تاسو ته راواپس شم، مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_003.mp3', NULL, 1761758886, 1761758886),
(40783, 'Zechariah 1:4', 'Zechariah', 1, 4, 'د خپل پلار نيکۀ په شان مۀ جوړېږئ، چا ته به چې پخوانو پېغمبرانو فرمائيل چې، ”مالِک خُدائ دا فرمائى چې، د خپلې بدعملۍ نه او د خپل بدعمله کارونو نه واوړئ.“ خو هغوئ به ما ته غوږ نۀ نيولو او نۀ به يې توجو راکوله، مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_004.mp3', NULL, 1761758886, 1761758886),
(40784, 'Zechariah 1:5', 'Zechariah', 1, 5, 'خو ستاسو پلار نيکۀ اوس چرته دى؟ ولې هغوئ او پېغمبران به تر ابده ژوندى وى څۀ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_005.mp3', NULL, 1761758886, 1761758886),
(40785, 'Zechariah 1:6', 'Zechariah', 1, 6, 'خو هر څۀ چې ما د خپلو خِدمتګارانو پېغمبرانو په وسيله ستاسو پلار نيکۀ ته وفرمائيل، هم هغه شان وشُو لکه څنګه چې ما حکم ورکړے وو. نو بيا هغوئ توبه وويسته او وې وئيل، مالِک خُدائ ربُ الافواج مونږ سره هغه څۀ وکړل د کوم چې زمونږ طريقې او عملونه حقدار وُو، هغۀ مونږ سره هغه څۀ وکړل د څۀ کولو چې هغۀ اراده کړې وه.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_006.mp3', NULL, 1761758886, 1761758886),
(40786, 'Zechariah 1:7', 'Zechariah', 1, 7, 'د داريوس د بادشاهۍ په دوېم کال، د يوولسمې مياشتې په څليريشتمه ورځ چې د شيباط مياشت وه، د مالِک خُدائ کلام زکرياه د برکياه په زوئ چې د عدو زوئ وو نازل شو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_007.mp3', NULL, 1761758886, 1761758886),
(40787, 'Zechariah 1:8', 'Zechariah', 1, 8, 'په شپه کښې ما يوه رويا وليده، او هلته زما په وړاندې يو سړے په سُور آس سور وو. هغه آس د سر درو ونو په مينځ کښې په يو تنګه وادۍ کښې ولاړ وو. د هغۀ نه شاته سرۀ، نسوارى او سپين آسونه وُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_008.mp3', NULL, 1761758886, 1761758886),
(40788, 'Zechariah 1:9', 'Zechariah', 1, 9, 'ما تپوس وکړو، ”دا څۀ دى، زما مالِکه؟“ هغه فرښتې چې ما سره يې خبرې کولې جواب راکړو، ”زۀ به تا ته وښايم چې دا څۀ دى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_009.mp3', NULL, 1761758886, 1761758886),
(40789, 'Zechariah 1:10', 'Zechariah', 1, 10, 'بيا هغه سړے چې د سر درو ونو مينځ کښې ولاړ وو هغۀ جواب راکړو، ”دا هغه څوک دے چې مالِک خُدائ رالېږلے دے چې په دُنيا کښې ګشت وکړى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_010.mp3', NULL, 1761758886, 1761758886),
(40790, 'Zechariah 1:11', 'Zechariah', 1, 11, 'او هغوئ د مالِک خُدائ فرښتې ته خبر ورکړو، څوک چې د سر درو ونو په مينځ کښې ولاړه وه، ”مونږ په ټوله دُنيا کښې ګشت وکړو او پته راته ولګېده چې ټوله دُنيا په آرام او امن کښې ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_011.mp3', NULL, 1761758886, 1761758886),
(40791, 'Zechariah 1:12', 'Zechariah', 1, 12, 'بيا د مالِک خُدائ فرښتې وفرمائيل، ”مالِکه خُدايه، ربُ الافواجه، تۀ به ترڅو پورې په يروشلم او د يهوداه په علاقو رحم نۀ کوې، چا ته چې تۀ د اويا کالو نه غصه يې؟“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_012.mp3', NULL, 1761758886, 1761758886),
(40792, 'Zechariah 1:13', 'Zechariah', 1, 13, 'نو مالِک خُدائ په رحم او نرم لفظونو هغه فرښتې سره خبرې وکړې چا چې ما سره خبرې کولې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_013.mp3', NULL, 1761758886, 1761758886),
(40793, 'Zechariah 1:14', 'Zechariah', 1, 14, 'بيا هغه فرښتې چا چې ما سره خبرې کولې راته يې وفرمائيل، ”د دې کلام اعلان وکړه چې مالِک خُدائ ربُ الافواج دا فرمائى، زۀ په يروشلم او صيون ډېر زيات غېرت کوم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_014.mp3', NULL, 1761758886, 1761758886),
(40794, 'Zechariah 1:15', 'Zechariah', 1, 15, 'خو زۀ هغه نورو قومونو ته ډېر غصه يم چې په امن او سکون کښې ژوند کوى. زۀ خپلو خلقو ته لږ غصه وم، خو دې قومونو هغوئ ته زما د ارادې نه زيات نقصان ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_015.mp3', NULL, 1761758886, 1761758886),
(40795, 'Zechariah 1:16', 'Zechariah', 1, 16, 'په دې وجه، مالِک خُدائ دا فرمائى، زۀ به يروشلم ته واپس رحم سره راشم، او هلته به زما کور بيا آباد شى. او د ناپ تول تارونه به په يروشلم راښکلے شى، دا مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_016.mp3', NULL, 1761758886, 1761758886),
(40796, 'Zechariah 1:17', 'Zechariah', 1, 17, 'نو دا هم ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، زما ښارونه به بيا د برکت نه ډک شى، او مالِک خُدائ به بيا صيون له تسلى ورکړى او يروشلم به لکه د خپل ښار دوباره غوره کړى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_017.mp3', NULL, 1761758886, 1761758886),
(40797, 'Zechariah 1:18', 'Zechariah', 1, 18, 'بيا ما بره وکتل، او هلته زما په وړاندې څلور ښکرونه وُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_018.mp3', NULL, 1761758886, 1761758886),
(40798, 'Zechariah 1:19', 'Zechariah', 1, 19, 'ما تپوس وکړو، د هغه فرښتې نه چې ما سره يې خبرې کولې، ”دا څۀ دى؟“ هغې جواب راکړو، ”دا هغه ښکرونه دى چې يهوداه، اِسرائيل او يروشلم يې خوارۀ وارۀ کړى دى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_019.mp3', NULL, 1761758886, 1761758886),
(40799, 'Zechariah 1:20', 'Zechariah', 1, 20, 'بيا مالِک خُدائ ما ته څلور لوهاران وښودل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_020.mp3', NULL, 1761758886, 1761758886),
(40800, 'Zechariah 1:21', 'Zechariah', 1, 21, 'ما ترې نه تپوس وکړو چې، ”دا څلور کسان د څۀ دپاره راروان دى؟“ نو فرښتې جواب راکړو، ”دا څلور ښکرونه هغه قومونه دى چې يهوداه يې عاجز او تس نس کړو. نو اوس دا لوهاران راغلى دى چې دا قومونه ويروى او راښکته يې کړى او د هغوئ کبر ختم کړى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah1_verse_021.mp3', NULL, 1761758886, 1761758886),
(40801, 'Psalms 64:1', 'Psalms', 64, 1, 'واوره زما اواز خدایه واوره شکایت زما خپلو دښمنانو نه وېرېږم زه وساته ژوندون زما!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_001.mp3', NULL, 1761758886, 1761758886),
(40802, 'Psalms 64:2', 'Psalms', 64, 2, 'وساته ما د دسیسو د بدکارانو څخه هم د شریرانو د ډلو څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_002.mp3', NULL, 1761758886, 1761758886),
(40803, 'Psalms 64:3', 'Psalms', 64, 3, 'تېرې کوي دوی خپلې ژبې د تورو په شان دوی په ترخو خبرو لکه د غشو په شان نښه ولي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_003.mp3', NULL, 1761758886, 1761758886),
(40804, 'Psalms 64:4', 'Psalms', 64, 4, 'په کمینونو کې دوی ولي بې‌ګناه انسانان بې له کوم ترسه ناڅاپه په هغوی باندې ګوزار کوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_004.mp3', NULL, 1761758886, 1761758886),
(40805, 'Psalms 64:5', 'Psalms', 64, 5, 'هغوی یو بل تشویقوي په خپلو بدو دسیسو باندې دوی جوړوي داسې پلان چې په کوم ځای کې دوی دامونه کېږدي هغوی وایي چې څوک مونږ نه شي لیدلی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_005.mp3', NULL, 1761758886, 1761758886),
(40806, 'Psalms 64:6', 'Psalms', 64, 6, 'جوړوي بد پلانونه او دوی وایي: «څومره ښه پلان مو دی جوړ کړی» څه مرموز دی د انسان زړه او دماغ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_006.mp3', NULL, 1761758886, 1761758886),
(40807, 'Psalms 64:7', 'Psalms', 64, 7, 'خو خدای به وولي هغوی په خپلو غشو او ناڅاپه به هغوی شي زخمیان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_007.mp3', NULL, 1761758886, 1761758886),
(40808, 'Psalms 64:8', 'Psalms', 64, 8, 'خپلې خبرې به نابود کړي هغوی هرڅوک چې ویني هغوی کړي اشارې به په ملنډو ورته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_008.mp3', NULL, 1761758886, 1761758886),
(40809, 'Psalms 64:9', 'Psalms', 64, 9, 'انسانان به ټول وېریږي بیانوي به دوی د خدای کارونه او کړي سوچونه په هغې څه چې خدای کړي دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_009.mp3', NULL, 1761758886, 1761758886),
(40810, 'Psalms 64:10', 'Psalms', 64, 10, 'څښتن چې وکړل کوم کارونه نېکان دې کاندي خوشحالي په هغو پناه دې یوسي ده ته ټول نېکان خلک دې صفتونه کوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms64_verse_010.mp3', NULL, 1761758886, 1761758886),
(40811, 'Ezra 7:1', 'Ezra', 7, 1, 'وروسته له ډېرو کلونو څخه کله چې ارتخششتا د فارس پاچا ؤ، د عزرا په نوم یو سړی ؤ چې شجره یې تر لوی کاهن هارون پورې رسېدله. د هغه شجره په لاندې ډول وه: عزرا د سرایا زوې ؤ، سرایا د عزریا زوی ؤ، عزریا د حلقیا زوی ؤ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_001.mp3', NULL, 1761758886, 1761758886),
(40812, 'Ezra 7:2', 'Ezra', 7, 2, 'حلقیا د شلوم زوی ؤ، شلوم د صادوق زوی ؤ، صادوق د اخیطوب زوی ؤ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_002.mp3', NULL, 1761758886, 1761758886),
(40813, 'Ezra 7:3', 'Ezra', 7, 3, 'اخیطوب د امریا زوی ؤ، امریا د عزریا زوی ؤ، عزریا د مرایوت زوی ؤ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_003.mp3', NULL, 1761758886, 1761758886),
(40814, 'Ezra 7:4', 'Ezra', 7, 4, 'مرایوت د زرحیا زوی ؤ، زرحیا د عزي زوی ؤ، عزي د بقي زوی ؤ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_004.mp3', NULL, 1761758886, 1761758886),
(40815, 'Ezra 7:5', 'Ezra', 7, 5, 'بقي د ابیشوع زوی ؤ، ابیشوع د فینحاس زوی ؤ، فینحاس د العازار زوی ؤ او العازار د لوی کاهن هارون زوی ؤ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_005.mp3', NULL, 1761758886, 1761758886),
(40816, 'Ezra 7:10', 'Ezra', 7, 10, 'دا مرسته ځکه ورسره وشوه چې عزرا خپل ژوند د څښتن د شریعت زده کړې ته، په هغه باندې عمل کولو او د اسراییلو خلکو ته د شریعت د حکمونو او قوانینو ورزده کولو ته وقف کړی ؤ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_010.mp3', NULL, 1761758886, 1761758886),
(40817, 'Ezra 7:11', 'Ezra', 7, 11, 'ارتخششتا پاچا دا لاندېنی لیک عزرا ته چې کاهن او دیني عالم ؤ، ورکړ. ځکه چې هغه په هغو قوانینو او حکمونو باندې ښه پوهېده چې څښتن اسراییلو ته ورکړي وو:', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_011.mp3', NULL, 1761758886, 1761758886),
(40818, 'Ezra 7:12', 'Ezra', 7, 12, '«د ارتخششتا، د پاچاهانو پاچا له خوا عزرا کاهن ته چې د اسمانونو د خدای د شریعت عالم دی، سلامونه:', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_012.mp3', NULL, 1761758886, 1761758886),
(40819, 'Ezra 7:13', 'Ezra', 7, 13, 'زه په دې توګه امر کوم چې د اسراییلو هغو ټولو خلکو، د هغوی کاهنانو او لاویانو ته چې زما په ټوله امپراتورۍ کې دي او غواړي چې ستا سره اورشلیم ته لاړ شي، اجازه ورکړل شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_013.mp3', NULL, 1761758886, 1761758886),
(40820, 'Ezra 7:14', 'Ezra', 7, 14, 'ما د خپلو اووه مشاورانو سره یوځای پرېکړه وکړه چې تا عزرا ولېږم چې په اورشلیم او یهودا کې حالات وڅېړې او وګورې چې ستا د خدای شریعت چې تاته سپارل شوی دی، څنګه ورڅخه اطاعت کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_014.mp3', NULL, 1761758886, 1761758886),
(40821, 'Ezra 7:15', 'Ezra', 7, 15, 'ته باید د سرو او سپینو زرو هغه نذرانې د ځان سره یوسې چې زه او زما مشاوران غواړو هغه د اسراییلو خدای ته چې کور یې په اورشلیم کې دی، ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_015.mp3', NULL, 1761758886, 1761758886),
(40822, 'Ezra 7:16', 'Ezra', 7, 16, 'ته باید هغه سپین او سره زر چې د بابل د ټولې سیمې څخه یې راټولوې او هغه نذرانې چې د اسراییلو خلک او کاهنان یې په خپله خوښه اورشلیم کې د خپل خدای کور ته ورکوي، هم یوسې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_016.mp3', NULL, 1761758886, 1761758886),
(40823, 'Ezra 7:17', 'Ezra', 7, 17, 'ته باید دا پیسې په ډېر پام سره ولګوې او په هغو باندې غویان، پسونه، وري، غلې دانې او شراب واخلې او هغه په اورشلیم کې ستاسو د خدای د کور د قربانۍ په ځای باندې قرباني کړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_017.mp3', NULL, 1761758886, 1761758886),
(40824, 'Ezra 7:18', 'Ezra', 7, 18, 'هرڅه چې تاته او ستا ملګرو ته ښه ښکاري د هغو دپاره د پاتې سپینو او سرو زرو څخه د خپل خدای د رضا سره سم ولګوئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_018.mp3', NULL, 1761758886, 1761758886),
(40825, 'Ezra 7:19', 'Ezra', 7, 19, 'هغه لوښي چې تاته ستا د خدای د کور په کارونو کې د کارولو دپاره درکړل شوي دي، هغه ټول د اورشلیم خدای ته وړاندې کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_019.mp3', NULL, 1761758886, 1761758886),
(40826, 'Ezra 7:20', 'Ezra', 7, 20, 'ستا د خدای د کور دپاره هر شي ته چې اړتیا وي، ته کولای شې چې د شاهي خزانې څخه یې واخلې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_020.mp3', NULL, 1761758886, 1761758886),
(40827, 'Ezra 7:21', 'Ezra', 7, 21, 'زه ارتخششتا د فرات د سیند د لوېدیځې خوا سیمې ټولو خزانه دارانو ته امر کوم چې هرڅه چې کاهن او د اسمانونو د خدای د شریعت عالم عزرا یې ستاسو څخه غواړي، هغه ورته زر تیار کړئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_021.mp3', NULL, 1761758886, 1761758886),
(40828, 'Ezra 7:22', 'Ezra', 7, 22, 'هغه ته تر درې زره او څلور سوه کیلو ګرامو پورې سپین زر، لس ټنه غنم، دوه زره لیتره شراب، دوه زره لیتره د زیتونو تېل او هرڅومره مالګې ته چې اړتیا ولري، ورکړئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_022.mp3', NULL, 1761758886, 1761758886),
(40829, 'Ezra 7:23', 'Ezra', 7, 23, 'هرڅه چې د اسمانونو خدای یې د خپل کور دپاره غواړي باید هغه ورته په احتیاط سره تیار کړئ. هغه کار ونه کړئ چې څښتن په ما او په هغو پاچاهانو باندې چې زما څخه وروسته راځي، په قهر شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_023.mp3', NULL, 1761758886, 1761758886),
(40830, 'Ezra 7:24', 'Ezra', 7, 24, 'تاسو ته اجازه نشته چې د کاهنانو، لاویانو، سندرغاړو، ساتونکو، خدمتګارانو او هغو نورو کارګرانو څخه چې د خدای د دې کور پورې تړاو لري باج او مالیه راټوله کړئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_024.mp3', NULL, 1761758886, 1761758886),
(40831, 'Ezra 7:25', 'Ezra', 7, 25, 'ای ښاغلیه عزرا! د هغه حکمت له مخې چې خدای تاته درکړی دی، مدیران او قاضیان وټاکه چې په هغو خلکو باندې حکومت وکړي چې د فرات د سیند په لوېدیځې خوا کې دي او ستاسو د خدای د حکمونو لاندې خپل ژوند تېروي. هغه څوک چې په هغو حکمونو باندې نه پوهیږي باید هغوی ته یې ورزده کړئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_025.mp3', NULL, 1761758886, 1761758886),
(40832, 'Ezra 7:26', 'Ezra', 7, 26, 'که چېرې څوک ستاسو د خدای د قوانینو یا د پاچا د قوانینو څخه سرغړونه وکړي، هغوی ته باید ډېر زر سزا ورکړل شي. یا دې هغوی ووژل شي، یا دې د وطن څخه وشړل شي، یا دې د هغوی شتمني ورڅخه واخیستل شي او یا دې بندي شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_026.mp3', NULL, 1761758886, 1761758886),
(40833, 'Ezra 7:27', 'Ezra', 7, 27, 'عزرا وویل: «زمونږ د نیکونو څښتن خدای ته دې ثنا وي! هغه پاچا دې ته راضي کړ چې په دې ډول په اورشلیم کې د څښتن د کور عزت او درنښت وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_027.mp3', NULL, 1761758886, 1761758886),
(40834, 'Ezra 7:28', 'Ezra', 7, 28, 'څښتن په ما باندې پاچا، د هغه مشاوران او لوړ رتبه درباریان مهربانه کړل. زما څښتن خدای ماته دا توان راکړ ترڅو وکولای شم د اسراییلو د قوم مشران راټول کړم چې زما سره بېرته اورشلیم ته راشي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra7_verse_028.mp3', NULL, 1761758886, 1761758886),
(40835, 'Ezekiel 41:1', 'Ezekiel', 41, 1, 'وروسته بیا هغه سړي زه د عبادت د ځای اصلي کوټې یعنې سپېڅلي ځای ته بوتلم. هغه د دې کوټې د دروازې د دواړو خواوو چوکاټونه اندازه کړل او د هر یو پنډوالی درې متره ؤ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_001.mp3', NULL, 1761758886, 1761758886),
(40836, 'Ezekiel 41:2', 'Ezekiel', 41, 2, 'دروازه پنځه متره پراخه وه او د هغې د دواړو خواو د دېوالونو پراخوالی دوه نیم متره ؤ. هغه همدا کوټه اندازه کړه، د هغې اوږدوالی شل متره او سور یې لس متره ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_002.mp3', NULL, 1761758886, 1761758886),
(40837, 'Ezekiel 41:3', 'Ezekiel', 41, 3, 'بیا هغه دې کوټې ته لاړ چې د ټولو په منځ کې وه. هغه د کوټې د دروازې چوکاټ اندازه کړ چې پنډوالی یې یو متر ؤ. دروازه درې متره پراخه وه او د هغې د دواړو خواوو دېوالونه درې نیم متره پراخ وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_003.mp3', NULL, 1761758886, 1761758886),
(40838, 'Ezekiel 41:4', 'Ezekiel', 41, 4, 'هغه بیا همدا کوټه اندازه کړه چې هغه لس متره مربع وه. دا کوټه د اصلي کوټې شاته وه. بیا هغه ماته وویل: «دا ډېر سپېڅلی ځای دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_004.mp3', NULL, 1761758886, 1761758886),
(40839, 'Ezekiel 41:5', 'Ezekiel', 41, 5, 'هغه سړي د عبادتځای دېوال اندازه کړ او د هغه پنډوالی درې متره ؤ. د دې دېوال دباندې د عبادتځای ګردچاپېره یو شمېر کوچنۍ کوټې وې چې دوه متره یې سور ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_005.mp3', NULL, 1761758886, 1761758886),
(40840, 'Ezekiel 41:6', 'Ezekiel', 41, 6, 'دا کوټې په درې منزلونو کې جوړې شوې وې چې په هر منزل کې یې دېرش کوټې وې. د عبادت د ځای ګردچاپېره په دېوالونو کې څنډې وې چې دا کوټې به یې ټینګولې، ترڅو کوټې په خپله د ودانۍ په دېوال کې نښتې نه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_006.mp3', NULL, 1761758886, 1761758886),
(40841, 'Ezekiel 41:7', 'Ezekiel', 41, 7, 'د عبادتځای شاوخوا کوټې داسې جوړې شوې وې. څنګه چې څوک په کې پورته کېده، هغه پراخه کېدلې. د لاندېني منزل څخه د منځني منزل له لارې تر پاسني منزل پورې یوه زینه ختلې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_007.mp3', NULL, 1761758886, 1761758886),
(40842, 'Ezekiel 41:8', 'Ezekiel', 41, 8, 'ما ولیدل چې د عبادتځای په یو بنیاد باندې ولاړ ؤ. د عبادتځای شاوخوا یوه صفه وه چې درې متره لوړه وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_008.mp3', NULL, 1761758886, 1761758886),
(40843, 'Ezekiel 41:12', 'Ezekiel', 41, 12, 'د عبادت د ځای لوېدیځ خواته یو خالی ځای ؤ. لوېدیځ خواته په اخر سر کې یوه ودانۍ وه چې اوږدوالی یې پنځه څلوېښت متره او سور یې پنځه دېرش متره ؤ. د هغې د ګردچاپېره دېوالونو پنډوالی دوه نیم متره ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_012.mp3', NULL, 1761758886, 1761758886),
(40844, 'Ezekiel 41:13', 'Ezekiel', 41, 13, 'هغه سړي د بهر څخه د عبادت د ځای اصلي ودانۍ اندازه کړه چې د هغې اوږدوالی پنځوس متره ؤ. هغه د عبادت د ځای د ودانۍ د شا د دېوال څخه د خالي ځای په شمول تر لوېدیځې ودانۍ د بهرني دېوال پورې مساحت اندازه کړ چې د هغه اوږدوالی هم پنځوس متره ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_013.mp3', NULL, 1761758886, 1761758886),
(40845, 'Ezekiel 41:14', 'Ezekiel', 41, 14, 'ختیځې خواته د عبادت د ځای د حوېلۍ سور چې په هغې کې د عبادت د ځای مخه هم شامله وه، پنځوس متره ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_014.mp3', NULL, 1761758886, 1761758886),
(40846, 'Ezekiel 41:15', 'Ezekiel', 41, 15, 'هغه د لوېدیځې ودانۍ بهرنی اوږدوالی اندازه کړ چې په هغې کې د دېوالونو د دواړو خواو څنډې هم شاملې وي، هغه هم پنځوس متره ؤ. د عبادت د ځای د ودانۍ تفصیلات د عبادت د ځای د اصلي کوټې دننني دېوالونه، دهلېز،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_015.mp3', NULL, 1761758886, 1761758886),
(40847, 'Ezekiel 41:16', 'Ezekiel', 41, 16, 'د دروازو خولې، وړې کړکۍ‌ګانې او هغه درې څنډې چې د دې کوټو شاوخوا وې، همدارنګه د دروازې د خولې په مخکې دېوالونه د غولي څخه تر وړو کړکیو پورې د تړل شویو کړکۍ‌ګانو په شمول، دا ټول په لرګیو پوښل شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_016.mp3', NULL, 1761758886, 1761758886),
(40848, 'Ezekiel 41:17', 'Ezekiel', 41, 17, 'د دروازې دپاسه دېوال، د عبادت د ځای په دنننه او دباندې او د هغه د شاوخوا په ټولو دېوالونو باندې که دنننه وو او که دباندې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_017.mp3', NULL, 1761758886, 1761758886),
(40849, 'Ezekiel 41:18', 'Ezekiel', 41, 18, 'د اسماني مخلوقاتو او د خرما د ونو نقشونه ویستل شوي وو. مخکې یوه ونه وه، بیا یو اسماني مخلوق ؤ، ونه او اسماني مخلوق په دې ډول ویستل شوي وو. دغو اسماني مخلوقاتو هر یو دوه دوه مخونه درلودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_018.mp3', NULL, 1761758886, 1761758886),
(40850, 'Ezekiel 41:21', 'Ezekiel', 41, 21, 'د اصلي کوټې د دروازې چوکاټونه مربع شکله وو. د ډېر سپېڅلي ځای د دروازې د چوکاټ لرګي هم د دې په شان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_021.mp3', NULL, 1761758886, 1761758886),
(40851, 'Ezekiel 41:22', 'Ezekiel', 41, 22, 'د لرګيو نه جوړ شوی د قربانۍ د ځای لوړوالی یونیم متر او مساحت یې یو متر مربع ؤ. د هغه د کنج پایې، بنیاد او د هغه خواوې ټولې د لرګیو نه جوړې شوې وې. هغه سړي ماته وویل: «دا هغه مېز دی چې د څښتن په حضور کې ایښودل کیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_022.mp3', NULL, 1761758886, 1761758886),
(40852, 'Ezekiel 41:23', 'Ezekiel', 41, 23, 'د عبادت ځای لویي کوټي یعنې سپېڅلي ځای او ډېر سپېڅلي ځای دوه، دوه پرله پسې دروازې درلودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_023.mp3', NULL, 1761758886, 1761758886),
(40853, 'Ezekiel 41:24', 'Ezekiel', 41, 24, 'دې دروازو دوه پلې درلودلې چې هره دروازه به د منځ نه خلاصېدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_024.mp3', NULL, 1761758886, 1761758886),
(40854, 'Ezekiel 41:25', 'Ezekiel', 41, 25, 'د عبادت د ځای د لویي کوټې دروازې هم د دېوالونو په شان د خرما د ونو او اسماني مخلوقاتو په نقشونو باندې ښکلې کړای شوې وې. د دهلېز د دروازې په باندیني ځای باندې د لرګیو چترۍ لګول شوې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_025.mp3', NULL, 1761758886, 1761758886),
(40855, 'Ezekiel 41:26', 'Ezekiel', 41, 26, 'د دې کوټې په اړخونو کې وړې کړکۍ‌ګانې وې او دېوالونه یې د خرما د ونو په نقشونو باندې ښکلي کړای شوي وو. د عبادت د ځای نورو کوټو هم چترۍ‌ګانې درلودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel41_verse_026.mp3', NULL, 1761758886, 1761758886),
(40856, 'Job 28:1', 'Job', 28, 1, '”بې‌شکه چې د سپينو زرو يو کان وى، او د سرو زرو د صفا کولو دپاره يو ځائ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_001.mp3', NULL, 1761758886, 1761758886),
(40857, 'Job 28:2', 'Job', 28, 2, 'اوسپنه د زمکې نه راويستلے شى، او د کاڼو نه ويلې شوې تانبه راوځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_002.mp3', NULL, 1761758886, 1761758886),
(40858, 'Job 28:3', 'Job', 28, 3, 'انسان په تيارۀ کښې رڼا ځلوى، او د دُنيا آخرى حد معلوموى، او د زمکې لاندې په تيارۀ کښې قيمتى کاڼى لټوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_003.mp3', NULL, 1761758886, 1761758886),
(40859, 'Job 28:4', 'Job', 28, 4, 'هغوئ د انسان د اوسېدو نه لرې په زمکه کښې سورنګونه جوړوى، هغوئ په کان کښې په پړو باندې کوزيږى او خېژى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_004.mp3', NULL, 1761758886, 1761758886),
(40860, 'Job 28:5', 'Job', 28, 5, 'په دې زمکه پاس خوراک لوئيږى خو دا زمکه لاندې داسې ده لکه د اور.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_005.mp3', NULL, 1761758886, 1761758886),
(40861, 'Job 28:6', 'Job', 28, 6, 'د دې زمکې په کاڼو کښې نيلم شته، او د دې په خاوره کښې سرۀ زر پراتۀ دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_006.mp3', NULL, 1761758886, 1761758886),
(40862, 'Job 28:7', 'Job', 28, 7, 'د هغه خزانې لار يو ښکارى مارغۀ ته هم نۀ ده معلومه، او نۀ باز هغه ليدلې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_007.mp3', NULL, 1761758886, 1761758886),
(40863, 'Job 28:8', 'Job', 28, 8, 'ځنګلى ځناورو په هغې باندې قدم نۀ دے اېښے، او زمرے په هغې باندې تېر شوے نۀ دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_008.mp3', NULL, 1761758886, 1761758886),
(40864, 'Job 28:9', 'Job', 28, 9, 'بنى آدم په سختو کاڼو کښې کار کوى، او د غرونو بېخونه اړَوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_009.mp3', NULL, 1761758886, 1761758886),
(40865, 'Job 28:10', 'Job', 28, 10, 'هغوئ په کاڼو کښې سورنګونه جوړوى، او هغوئ قيمتى کاڼى پېدا کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_010.mp3', NULL, 1761758886, 1761758886),
(40866, 'Job 28:11', 'Job', 28, 11, 'هغوئ د دريابونو بېخونه لټوى، او هغوئ پټ څيزونه رڼا ته راوباسى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_011.mp3', NULL, 1761758886, 1761758886),
(40867, 'Job 28:12', 'Job', 28, 12, 'خو هغوئ ته پته نشته چې حِکمت به چرته ملاويږى؟ او د پوهې ځائ چرته دے؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_012.mp3', NULL, 1761758886, 1761758886),
(40868, 'Job 28:13', 'Job', 28, 13, 'بنى آدم د دې د قيمت نه خبر نۀ دے، او دا په دې دُنيا کښې نۀ ملاويږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_013.mp3', NULL, 1761758886, 1761758886),
(40869, 'Job 28:14', 'Job', 28, 14, 'سمندر وائى چې دا په ما کښې نشته، او درياب وائى چې دا په ما کښې نشته.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_014.mp3', NULL, 1761758886, 1761758886),
(40870, 'Job 28:15', 'Job', 28, 15, 'نۀ دا په سپينو زرو اخستلے شى، او نۀ دا په سرو زرو اخستلے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_015.mp3', NULL, 1761758886, 1761758886),
(40871, 'Job 28:16', 'Job', 28, 16, 'د اوفير سرۀ زر د دې قيمت نۀ شى پوره کولے، نۀ يې اونيکس کاڼى او نۀ يې نيلم کاڼى پوره کولے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_016.mp3', NULL, 1761758886, 1761758886),
(40872, 'Job 28:17', 'Job', 28, 17, 'سرۀ زر او قيمتى کاڼى د حِکمت برابر نۀ شى کېدے، او نۀ دا د سوچه سرو زرو په کالو باندې بدلولے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_017.mp3', NULL, 1761758886, 1761758886),
(40873, 'Job 28:18', 'Job', 28, 18, 'مرجان او بلور غمى هيڅ هم نۀ دى، د حِکمت قيمت د ملغلرو نه اوچت دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_018.mp3', NULL, 1761758886, 1761758886),
(40874, 'Job 28:19', 'Job', 28, 19, 'د ايتهوپيا طوپاز د دې برابر نۀ دے، او نۀ سوچه سرۀ زر د دې قيمت پوره کولے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_019.mp3', NULL, 1761758886, 1761758886),
(40875, 'Job 28:20', 'Job', 28, 20, 'نو بيا حِکمت د کوم ځائ نه راځى؟ او د پوهې مقام چرته دے؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_020.mp3', NULL, 1761758886, 1761758886),
(40876, 'Job 28:21', 'Job', 28, 21, 'دا د ټول مخلوق د سترګو نه پناه دے، او د هوا د مارغانو نه پټ دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_021.mp3', NULL, 1761758886, 1761758886),
(40877, 'Job 28:22', 'Job', 28, 22, 'په عالمِ ارواح کښې صرف د دې افواه اورېدلے شوې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_022.mp3', NULL, 1761758886, 1761758886),
(40878, 'Job 28:23', 'Job', 28, 23, 'صرف خُدائ پاک د حِکمت په طريقه پوهه دے، او هغۀ ته د دې د مقام پته ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_023.mp3', NULL, 1761758886, 1761758886),
(40879, 'Job 28:24', 'Job', 28, 24, 'ځکه چې هغه ټولې دُنيا ته ګورى، او هغه د آسمانونو لاندې هر يو څيز وينى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_024.mp3', NULL, 1761758886, 1761758886),
(40880, 'Job 28:25', 'Job', 28, 25, 'کله چې هغۀ هوا ته طاقت ورکړو، او په وريځو کښې يې باران کېښودو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_025.mp3', NULL, 1761758886, 1761758886),
(40881, 'Job 28:26', 'Job', 28, 26, 'کله چې هغۀ د باران دپاره اصُول مقرر کړل، او د تندر دپاره يې يوه لاره مقرره کړه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_026.mp3', NULL, 1761758886, 1761758886),
(40882, 'Job 28:27', 'Job', 28, 27, 'بيا هغۀ حِکمت وليدو او د دې اندازه يې واخستله، هغۀ دا تيار کړو او ښۀ يې وکتلو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_027.mp3', NULL, 1761758886, 1761758886),
(40883, 'Job 28:28', 'Job', 28, 28, 'او هغۀ بنيادمو ته وفرمائيل، چې د مالِک خُدائ نه يره کښې حِکمت دے، او بدعملى پرېښودل عقلمندى ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job28_verse_028.mp3', NULL, 1761758886, 1761758886),
(40884, 'Exodus 5:1', 'Exodus', 5, 1, 'بیا موسی او هارون فرعون ته ورغلل او ورته ویې ویل: «د اسراییلو څښتن خدای وایي: ‹زما قوم پرېږده چې دښتې ته لاړ شي او هلته زما د درناوي په خاطر اختر ولمانځي.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_001.mp3', NULL, 1761758886, 1761758886),
(40885, 'Exodus 5:2', 'Exodus', 5, 2, 'فرعون وویل: «څښتن څوک دی؟ زه ولې د هغه خبرو ته غوږ ونیسم او اسراییلیان پرېږدم چې لاړ شي؟ زه څښتن نه پېژنم او نه به اسراییلو ته د تګ اجازه ورکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_002.mp3', NULL, 1761758886, 1761758886),
(40886, 'Exodus 5:3', 'Exodus', 5, 3, 'هغوی په ځواب کې وویل: «د عبرانیانو خدای مونږ ته راښکاره شوی دی. مونږ پرېږده چې د درېو ورځو دپاره په دښته کې سفر وکړو، ترڅو خپل څښتن خدای ته قرباني وړاندې کړو. که نه، نو هغه به مونږ د ناروغیو او جګړې په وسیله ووژني.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_003.mp3', NULL, 1761758886, 1761758886),
(40887, 'Exodus 5:4', 'Exodus', 5, 4, 'فرعون موسی او هارون ته وویل: «تاسو ولې خلک له کاره وباسئ؟ هر یو بېرته په خپل کار پسې لاړ شئ!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_004.mp3', NULL, 1761758886, 1761758886),
(40888, 'Exodus 5:5', 'Exodus', 5, 5, 'ستاسو شمېر له مصریانو څخه زیات شوی دی او اوس غواړئ چې کار بس کړئ!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_005.mp3', NULL, 1761758886, 1761758886),
(40889, 'Exodus 5:6', 'Exodus', 5, 6, 'په هماغه ورځ فرعون د غلامانو په مصري مسوولانو او د اسراییلي کارګرانو په مشرانو امر وکړ:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_006.mp3', NULL, 1761758886, 1761758886),
(40890, 'Exodus 5:7', 'Exodus', 5, 7, '«نور خلکو ته د خښتو جوړولو دپاره بوس مه ورکوئ. هغوی ته ووایئ چې لاړ شي او په خپله یې د ځانونو دپاره پیدا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_007.mp3', NULL, 1761758886, 1761758886),
(40891, 'Exodus 5:8', 'Exodus', 5, 8, 'خو هغوی باید دومره خښتې جوړې کړي څومره یې چې پخوا جوړولې. هغوی تنبلان دي، ځکه ماته زارۍ کوي چې هغوی پرېږدم چې لاړ شي او خپل خدای ته قرباني وړاندې کړي!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_008.mp3', NULL, 1761758886, 1761758886),
(40892, 'Exodus 5:9', 'Exodus', 5, 9, 'په هغوی باندې سخت کار وکړئ او بوخت یې وساتئ چې د داسې دروغو اورېدلو دپاره وخت ونه لري.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_009.mp3', NULL, 1761758886, 1761758886),
(40893, 'Exodus 5:10', 'Exodus', 5, 10, 'نو د غلامانو مسوولان او د کارګرانو مشران راغلل او ویې ویل: «فرعون وایي: زه به نور تاسو ته بوس درنه کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_010.mp3', NULL, 1761758886, 1761758886),
(40894, 'Exodus 5:11', 'Exodus', 5, 11, 'لاړ شئ او هر چېرته چې کولای شئ د ځانونو دپاره بوس پیدا کړئ، خو بیا به همدومره خښتې جوړوئ څومره چې مو مخکې جوړولې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_011.mp3', NULL, 1761758886, 1761758886),
(40895, 'Exodus 5:12', 'Exodus', 5, 12, 'نو خلک په ټول مصر کې وګرځېدل، ترڅو د ځانونو دپاره بوس پیدا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_012.mp3', NULL, 1761758886, 1761758886),
(40896, 'Exodus 5:13', 'Exodus', 5, 13, 'د غلامانو مسوولانو به په هغوی فشار اچاوه او هغوی ته به یې ویل: «تاسو باید هره ورځ دومره خښتې جوړې کړئ څومره چې تاسو هغه وخت جوړولې چې بوس درته درکول کېدل.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_013.mp3', NULL, 1761758886, 1761758886),
(40897, 'Exodus 5:14', 'Exodus', 5, 14, 'د غلامانو مصري مسوولانو به هغه اسراییلي مشران وهل چې په دوی باندې یې مقرر کړي وو او ورته ویل به یې: «تاسو نن سبا دا غلامان ولې نه مجبوروئ چې دومره خښتې جوړې کړي څومره چې هغوی مخکې جوړولې؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_014.mp3', NULL, 1761758886, 1761758886),
(40898, 'Exodus 5:15', 'Exodus', 5, 15, 'په اخر کې د کارګرانو مشران فرعون ته ورغلل او ورته ویې ویل: «تاسو ولې زمونږ سره داسې چلند کوئ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_015.mp3', NULL, 1761758886, 1761758886),
(40899, 'Exodus 5:16', 'Exodus', 5, 16, 'مونږ ته هېڅوک بوس نه راوړي، خو بیاهم امر راته کیږي چې هماغومره خښتې جوړې کړو. هغوی مونږ وهي، حال دا چې ستاسو خپل خلک ملامت دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_016.mp3', NULL, 1761758886, 1761758886),
(40900, 'Exodus 5:17', 'Exodus', 5, 17, 'فرعون په ځواب کې وویل: «تاسو تنبلان یئ او نه غواړئ چې کار وکړئ. په دې خاطر ماته وایئ چې تاسو پرېږدم چې لاړ شئ او څښتن ته قرباني وړاندې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_017.mp3', NULL, 1761758886, 1761758886),
(40901, 'Exodus 5:18', 'Exodus', 5, 18, 'اوس خپل کار پسې لاړ شئ! تاسو ته به بوس نه درکول کیږي، خو بیاهم په هماغه اندازه خښتې جوړې کړئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_018.mp3', NULL, 1761758886, 1761758886),
(40902, 'Exodus 5:19', 'Exodus', 5, 19, 'د کارګرانو مشران پوه شول چې د هغوی حال نور هم خراب شو کله چې فرعون په هغوی امر وکړ چې تاسو به هغومره خښتې جوړوئ لکه مخکې به چې تاسو جوړولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_019.mp3', NULL, 1761758886, 1761758886),
(40903, 'Exodus 5:20', 'Exodus', 5, 20, 'څنګه چې هغوی د فرعون له دربار څخه ووتل، د موسی او هارون لیدلو ته چې ورته په انتظار وو، لاړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_020.mp3', NULL, 1761758886, 1761758886),
(40904, 'Exodus 5:21', 'Exodus', 5, 21, 'هغوی موسی او هارون ته وویل: «تاسو چې څه کړي دي هغه څښتن لیدلي دي او تاسو دواړو ته به سزا درکړي، ځکه چې ستاسو د لاسه فرعون او د هغه درباریان زمونږ څخه کرکه کوي. تاسو هغوی ته بهانه په لاس ورکړه چې مونږ ووژني.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_021.mp3', NULL, 1761758886, 1761758886),
(40905, 'Exodus 5:22', 'Exodus', 5, 22, 'موسی بېرته څښتن ته ورغی او ویې ویل: «ای څښتنه، ولې دې خپل قوم د بدبختیو سره مخامخ کړی دی؟ ایا زه دې د همدې دپاره رالېږلی یم؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_022.mp3', NULL, 1761758886, 1761758886),
(40906, 'Exodus 5:23', 'Exodus', 5, 23, 'له هغه وخت څخه چې تا ماته وویل چې د فرعون سره خبرې وکړه، هغه ورباندې ظلم کوي او تا د هغوی سره هېڅ مرسته ونه کړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus5_verse_023.mp3', NULL, 1761758886, 1761758886),
(40907, 'Psalms 87:1', 'Psalms', 87, 1, 'څښتن خپل ښار ودان کړ چې یې بنیاد دی ایښی په سپېڅلو تپو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_001.mp3', NULL, 1761758886, 1761758886),
(40908, 'Psalms 87:2', 'Psalms', 87, 2, 'د اسراییلو په ټولو ښارونو کې د صهیون ښار څښتن ته ګران دی له هره ځایه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_002.mp3', NULL, 1761758886, 1761758886),
(40909, 'Psalms 87:3', 'Psalms', 87, 3, 'ای د خدای ښاره خبرې کیږي ستا د جلال په هکله:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_003.mp3', NULL, 1761758886, 1761758886),
(40910, 'Psalms 87:4', 'Psalms', 87, 4, '«مصریان او بابلیان به وشمېرم هغو قومونو کې چې پېژني ما او دغه راز د فلسطین، صور او ایتوپیا خلک دي دوی ټول د اورشلیم ښاریان»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_004.mp3', NULL, 1761758886, 1761758886),
(40911, 'Psalms 87:5', 'Psalms', 87, 5, 'د صهیون په هکله داسې به ویل کیږي: «هغوی ټول به حق د هغه ښار د تابعیت ولري خدای تعالی به ټینګ وساتي دا ښار»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_005.mp3', NULL, 1761758886, 1761758886),
(40912, 'Psalms 87:6', 'Psalms', 87, 6, 'څښتن به ثبت کړي د قومونو لست هغوی ټول به کړي حساب د صهیون په اوسېدونکو کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_006.mp3', NULL, 1761758886, 1761758886),
(40913, 'Psalms 87:7', 'Psalms', 87, 7, 'سندرغاړي او اتڼ کوونکي به دا وایي: «دی صهیون زما اصلي ځای»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms87_verse_007.mp3', NULL, 1761758886, 1761758886),
(40914, 'Ezekiel 23:1', 'Ezekiel', 23, 1, 'څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_001.mp3', NULL, 1761758886, 1761758886),
(40915, 'Ezekiel 23:2', 'Ezekiel', 23, 2, '«ای فاني انسانه، یوه مور وه چې دوه لورګانې یې درلودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_002.mp3', NULL, 1761758886, 1761758886),
(40916, 'Ezekiel 23:3', 'Ezekiel', 23, 3, 'کله چې هغوی ځوانې وې او په مصر کې اوسېدلې، هغوی خلک پرېښودل چې د دوی د سینو سره لوبې وکړي، په دې ډول یې خپل پېغلتوب له لاسه ورکړ او بدلمنې شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_003.mp3', NULL, 1761758886, 1761758886),
(40917, 'Ezekiel 23:4', 'Ezekiel', 23, 4, 'د مشرې نوم یې اهوله وه چې د سامرې معنی ورکوي او د کشرې نوم یې اهولیبه وه چې د اورشلیم معنی ورکوي. ما د هغو دواړو سره واده وکړ او د هغوی نه مې زامن او لورګانې پیدا شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_004.mp3', NULL, 1761758886, 1761758886),
(40918, 'Ezekiel 23:5', 'Ezekiel', 23, 5, 'که څه هم اهوله زما ښځه وه، خو هغې خپل بدلمنتوب کاوه او شوق یې درلود چې د خپلو عاشقانو یعنې آشوري جنګیالیانو سره شهواني اړیکې ولري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_005.mp3', NULL, 1761758886, 1761758886),
(40919, 'Ezekiel 23:6', 'Ezekiel', 23, 6, 'هغوی عسکر وو او بانجاني کالي یې اغوستي وو، والیان او لوړ‌رتبه مامورین وو، دا ټول ښکلي ځوانان او اس سپاره وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_006.mp3', NULL, 1761758886, 1761758886),
(40920, 'Ezekiel 23:7', 'Ezekiel', 23, 7, 'هغې د آشوريانو سره بدلمني کوله چې ټول یې منصبداران وو او د هغې شهوت پرستي د دې سبب شوه چې خپل ځان د آشوریانو بتانو ته په عبادت کولو سره ناپاکه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_007.mp3', NULL, 1761758886, 1761758886),
(40921, 'Ezekiel 23:8', 'Ezekiel', 23, 8, 'هغې چې کوم بدلمنتوب په مصر کې پیل کړی ؤ، د هغې نه یې لاس وانخیست. هلته یې خپل پېغلتوب له لاسه ورکړی ؤ. د ځوانۍ د وخت نه به خلکو د هغې د سینو سره لوبې کولې او د هغې سره یې شهواني اړیکې لرلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_008.mp3', NULL, 1761758886, 1761758886),
(40922, 'Ezekiel 23:9', 'Ezekiel', 23, 9, 'نو هغه مې خپل آشوري عاشقانو ته چې د هغوی سره یې زیاتې شهواني اړیکې غوښتلې، ورتسلیمه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_009.mp3', NULL, 1761758886, 1761758886),
(40923, 'Ezekiel 23:10', 'Ezekiel', 23, 10, 'هغوی هغه لوڅه کړه، د هغې زامن او لورګانې یې ونیولې او هغه یې په توره باندې ووژله. په هرځای کې به ښځو د هغې د سرنوشت او سزا په هکله خبرې کولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_010.mp3', NULL, 1761758886, 1761758886),
(40924, 'Ezekiel 23:11', 'Ezekiel', 23, 11, 'که څه هم د هغې خور اهولیبه دا هرڅه ولیدل، خو بیاهم هغه په خپل شهوت او بدلمنتوب کې د خپلې خور اهولې نه هم زیاته فاسده شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_011.mp3', NULL, 1761758886, 1761758886),
(40925, 'Ezekiel 23:12', 'Ezekiel', 23, 12, 'هغې هم د آشوریانو په هغو والیانو، لوړ‌رتبه مامورینو او عسکرو چې ښکلي کالي یې اغوستي وو او په اسونو سپاره وو، غوښتل چې د هغوی سره شهواني اړیکې ولري. دا ټول زړه وړونکي ځوانان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_012.mp3', NULL, 1761758886, 1761758886),
(40926, 'Ezekiel 23:13', 'Ezekiel', 23, 13, 'ما ولیدل چې هغه بیخي بد‌اخلاقه شوه او دوهمه خور یې هم د اولنۍ خور لاره غوره کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_013.mp3', NULL, 1761758886, 1761758886),
(40927, 'Ezekiel 23:16', 'Ezekiel', 23, 16, 'څنګه چې هغې دا ولیدل، نو هغې غوښتل چې د هغوی سره شهواني اړیکې ولري او هغوی پسې یې قاصدان بابل ته ولېږل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_016.mp3', NULL, 1761758886, 1761758886),
(40928, 'Ezekiel 23:17', 'Ezekiel', 23, 17, 'بابلیان راغلل او د هغې سره یې زنا وکړه. هغه یې په خپل شهوت ناپاکه کړه او وروسته هغه ورڅخه بېزاره شوه او د هغوی نه یې مخ واړاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_017.mp3', NULL, 1761758886, 1761758886),
(40929, 'Ezekiel 23:18', 'Ezekiel', 23, 18, 'هغې په ښکاره ځان لوڅاوه او بدلمنتوب یې کاوه. نو زه د هغې نه دومره بېزاره شوم چې خپل مخ مې ترې واړاوه، لکه څنګه چې د هغې د خور نه بېزاره شوی وم او خپل مخ مې ترې اړولی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_018.mp3', NULL, 1761758886, 1761758886),
(40930, 'Ezekiel 23:19', 'Ezekiel', 23, 19, 'هغه د بل هر وخت نه هم زیاته بدلمنه شوه او داسې بدلمنتوب یې کاوه، لکه څنګه چې هغې د خپلې ځوانۍ د دوران په ياد په مصر کې کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_019.mp3', NULL, 1761758886, 1761758886),
(40931, 'Ezekiel 23:20', 'Ezekiel', 23, 20, 'هغې د هغو شهوت پرسته خلکو هوس کاوه چې د هغوی تناسلي الې د خره او انزال یې د اس په شان زیات ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_020.mp3', NULL, 1761758886, 1761758886),
(40932, 'Ezekiel 23:21', 'Ezekiel', 23, 21, 'نو ای اهولیبې، تا غوښتل چې خپله هغه بد‌اخلاقي تکرار کړې چې په پېغلتوب کې دې په مصر کې کاوه یعنې چېرته چې سړیو ستا د سینو سره لوبې کولې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_021.mp3', NULL, 1761758886, 1761758886),
(40933, 'Ezekiel 23:22', 'Ezekiel', 23, 22, '«نو ای اهولیبې، زه څښتن تعالی تاته داسې وایم: ‹ګوره، ستا په وړاندې به هغه عاشقان راپورته کړم چې ورڅخه بېزاره شوې یې او مخ دې ورڅخه اړولی دی. هغوی به د هرې خوا نه په تا باندې راولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_022.mp3', NULL, 1761758886, 1761758886),
(40934, 'Ezekiel 23:23', 'Ezekiel', 23, 23, 'زه به بابلیان، کلدانیان او د فقود، شوع او قوع سړي او ورسره ټول آشوریان راولم. دا به ټول ښکلي ځوانان وي، دا به والیان، لوړ‌رتبه مامورین او منصبداران وي، هغوی به ټول په اسونو سپاره وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_023.mp3', NULL, 1761758886, 1761758886),
(40935, 'Ezekiel 23:24', 'Ezekiel', 23, 24, 'هغوی به د یو لوی لښکر، جنګي او د سامان وړلو ګاډیو سره د شمال له خوا په تا باندې حمله وکړي. هغوی به تا کلابند کړي او د وړو او لویو سپرونو او د زغرو د خولیو په وسیله به د خپل ځان ساتنه وکړي. زه به تا هغوی ته په لاس ورکړم او تاته به د خپل قانون له مخې سزا درکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_024.mp3', NULL, 1761758886, 1761758886),
(40936, 'Ezekiel 23:25', 'Ezekiel', 23, 25, 'په دې خاطر چې زما غیرت راپارېدلی دی، نو زه به هغوی پرېږدم چې ستا سره د ډېر قهر نه کار واخلي. هغوی به ستا پوزه او غوږونه پرې کړي او ستا اولادونه به ووژني. هو، هغوی به ستا زامن او لورګانې بوځي او هغوی به ژوندي وسوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_025.mp3', NULL, 1761758886, 1761758886),
(40937, 'Ezekiel 23:26', 'Ezekiel', 23, 26, 'هغوی به ستا نه کالي وباسي او ستا ښکلي زېورات به درڅخه واخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_026.mp3', NULL, 1761758886, 1761758886),
(40938, 'Ezekiel 23:27', 'Ezekiel', 23, 27, 'نو زه به ستا شهوت پرستي او بدلمنتوب چې د مصر نه دې له ځان سره راوړی دی، پای ته ورسوم. ته به نور بتانو ته نه ګورې او نه به د مصر په هکله فکر کوې.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_027.mp3', NULL, 1761758886, 1761758886),
(40939, 'Ezekiel 23:28', 'Ezekiel', 23, 28, 'زه څښتن تعالی داسې وایم: ‹زه به تا هغو خلکو ته په لاس ورکړم چې ورڅخه کرکه کوې، ورڅخه بېزاره شوې او د هغوی نه دې مخ واړاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_028.mp3', NULL, 1761758886, 1761758886),
(40940, 'Ezekiel 23:29', 'Ezekiel', 23, 29, 'په دې خاطر چې هغوی ستا نه کرکه کوي، نو هغوی به ستا نه هغه ټول شیان واخلي چې د هغو دپاره دې زحمت ویستلی دی او هغوی به د یوې بدلمنې په شان تا لوڅه پرېږدي. دا هرڅه ستا شهوت او ستا بدلمنتوب', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_029.mp3', NULL, 1761758886, 1761758886),
(40941, 'Ezekiel 23:30', 'Ezekiel', 23, 30, 'په تا باندې راوستلي دي. ته د ټولو قومونو دپاره بدلمنه یې او د هغوی په بتانو باندې دې خپل ځان ناپاکه کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_030.mp3', NULL, 1761758886, 1761758886),
(40942, 'Ezekiel 23:31', 'Ezekiel', 23, 31, 'ته د خپلې خور په لاره باندې روانه شوې، نو زه به د سزا هماغه پیاله تاته درکړم چې ویې څښې.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_031.mp3', NULL, 1761758886, 1761758886),
(40943, 'Ezekiel 23:32', 'Ezekiel', 23, 32, '«څښتن تعالی داسې وایي: ‹ته به وڅښې د خپلې خور له پیالې هغه ده غټه او ژوره هرڅوک به تا پسې کوي خندا او وهي ملنډې به په تا باندې ځکه چې ډکه ده هغه پیاله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_032.mp3', NULL, 1761758886, 1761758886),
(40944, 'Ezekiel 23:33', 'Ezekiel', 23, 33, 'هغه به تا کاندي غمجن او نشه د وحشت او نابودۍ هغه پیاله ستا د خور سامرې پیاله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_033.mp3', NULL, 1761758886, 1761758886),
(40945, 'Ezekiel 23:34', 'Ezekiel', 23, 34, 'هغه به وڅښې او خالي به یې کړې وبه ژوې د هغې ماتې ټوټې او پرې به کړې خپله سینه› ما څښتن تعالی داسې ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_034.mp3', NULL, 1761758886, 1761758886),
(40946, 'Ezekiel 23:35', 'Ezekiel', 23, 35, 'نو څښتن تعالی داسې وایي: ‹په دې خاطر چې تا زه هېر کړی یم او ماته دې شا اړولې ده، نو ته به د خپلې شهوت پرستۍ او خپل بدلمنتوب په سبب کړېږې.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_035.mp3', NULL, 1761758886, 1761758886),
(40947, 'Ezekiel 23:36', 'Ezekiel', 23, 36, 'څښتن ماته وویل: «ای فاني انسانه، اهوله او اهولیبه محاکمه کړه. هغوی د هغو کرکې وړ کارونو په سبب چې کړي یې دي، ملامته کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_036.mp3', NULL, 1761758886, 1761758886),
(40948, 'Ezekiel 23:37', 'Ezekiel', 23, 37, 'هغوی زنا کړې ده او لاسونه یې د خلکو په وینو باندې سره دي. هغوی د بتانو په عبادت کولو سره زما په وړاندې زنا کړې ده. هغه زامن یې قتل کړي دي چې ماته یې زېږولي وو او هغوی یې د خوړو په توګه بتانو ته قرباني کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_037.mp3', NULL, 1761758886, 1761758886),
(40949, 'Ezekiel 23:38', 'Ezekiel', 23, 38, 'هغوی نور کارونه هم کړي دي. په هماغه وخت کې هغوی زما د عبادت ځای ناپاکه کړ او د سبت د ورځې بې‌عزتي یې وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_038.mp3', NULL, 1761758886, 1761758886),
(40950, 'Ezekiel 23:39', 'Ezekiel', 23, 39, 'په هماغه ورځ چې هغوی زما اولادونه خپلو بتانو ته د قربانۍ دپاره ووژل، هغوی زما عبادتځای ته راغلل او د هغه سپکاوی یې وکړ. دا هغه څه دي چې هغوی زما په کور کې وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_039.mp3', NULL, 1761758886, 1761758886),
(40951, 'Ezekiel 23:40', 'Ezekiel', 23, 40, 'حتی هغوی استازي ولېږل چې د لېرې لېرې ځایونو نه سړي راوبولي او کله چې هغوی راغلل، دواړو خویندو خپل ځانونه ووینځل، سترګې یې تورې کړلې او ګاڼې یې واچولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_040.mp3', NULL, 1761758886, 1761758886),
(40952, 'Ezekiel 23:41', 'Ezekiel', 23, 41, 'هغوی په ښایسته کوچونو باندې کښېناستلې او د کوچونو په مخکې یو مېز تیار شوی ؤ چې په مېز باندې خوشبویي او د زیتونو تېل چې ما ورته ورکړي وو، ایښي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_041.mp3', NULL, 1761758886, 1761758886),
(40953, 'Ezekiel 23:42', 'Ezekiel', 23, 42, 'د هغوی شاوخوا نه د عیاشو خلکو د ډلې اواز اورېدل کېده، دا د هغو سړیو ډله وه چې د دښتې نه یې راوستلي وو. هغوی ښځو ته بنګړي په لاس کړل او ښکلي تاجونه یې ورته په سرونو باندې کېښودل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_042.mp3', NULL, 1761758886, 1761758886),
(40954, 'Ezekiel 23:43', 'Ezekiel', 23, 43, 'نو ما د خپل ځان سره وویل سره له دې چې هغه ښځې د زنا کولو نه ستړې شوې دي، خو بیاهم هغه سړي ورڅخه د بدلمنې په توګه کار اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_043.mp3', NULL, 1761758886, 1761758886),
(40955, 'Ezekiel 23:44', 'Ezekiel', 23, 44, 'هغوی دې دوه بدلمنو یعنې اهوله او اهولیبه ته ورغلل چې شهوت پرسته ښځې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_044.mp3', NULL, 1761758886, 1761758886),
(40956, 'Ezekiel 23:45', 'Ezekiel', 23, 45, 'خو نېک خلک به هغوی د زناکارۍ او قتلونو له امله محکوم کړي، ځکه چې هغوی زنا کوي او لاسونه یې په وینو باندې سره دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_045.mp3', NULL, 1761758886, 1761758886),
(40957, 'Ezekiel 23:46', 'Ezekiel', 23, 46, 'نو څښتن تعالی داسې وایي: یو لښکر راولئ چې هغوی سخت ووېروي او لوټ یې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_046.mp3', NULL, 1761758886, 1761758886),
(40958, 'Ezekiel 23:47', 'Ezekiel', 23, 47, 'هغه ډله به هغوی سنګسار کړي او په خپلو تورو باندې به د هغوی بدنونه ټوټې ټوټې کړي. د هغوی زامن او لورګانې به ووژني او کورونه به یې وسوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_047.mp3', NULL, 1761758886, 1761758886),
(40959, 'Ezekiel 23:48', 'Ezekiel', 23, 48, 'نو زه به ټول وطن کې شهوت پرستي پای ته ورسوم او دا به ټولو ښځو ته یو خبرداری وي چې د هغوی په شان شهوت پرستي ونه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_048.mp3', NULL, 1761758886, 1761758886),
(40960, 'Ezekiel 23:49', 'Ezekiel', 23, 49, 'ای دواړو خویندو، زه به تاسو ته ستاسو د شهوت پرستۍ او بتانو ته د عبادت کولو د ګناه په خاطر سزا درکړم. بیا به تاسو پوه شئ چې زه څښتن تعالی یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel23_verse_049.mp3', NULL, 1761758886, 1761758886),
(40961, 'Numbers 3:1', 'Numbers', 3, 1, 'دا د موسی او هارون د کورنۍ د هغه وخت کیسه ده کله چې څښتن د موسی سره د سینا په غره کې خبرې وکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_001.mp3', NULL, 1761758886, 1761758886),
(40962, 'Numbers 3:2', 'Numbers', 3, 2, 'هارون څلور زامن درلودل: ناداب چې مشر ؤ، ابیهو، العازار او ایتامار.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_002.mp3', NULL, 1761758886, 1761758886),
(40963, 'Numbers 3:3', 'Numbers', 3, 3, 'هغوی مسح کړای شول او د کاهنانو په توګه وټاکل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_003.mp3', NULL, 1761758886, 1761758886),
(40964, 'Numbers 3:4', 'Numbers', 3, 4, 'خو ناداب او ابیهو د څښتن په حضور کې په داسې وخت کې مړه شول کله چې هغوی د سینا په دښته کې څښتن ته ناپاکه اور وړاندې کاوه. هغوی اولادونه نه درلودل، نو العازار او ایتامار د هارون د ژوندانه په دوران کې د کاهنانو په توګه خدمت وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_004.mp3', NULL, 1761758886, 1761758886),
(40965, 'Numbers 3:5', 'Numbers', 3, 5, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_005.mp3', NULL, 1761758886, 1761758886),
(40966, 'Numbers 3:6', 'Numbers', 3, 6, '«د لاویانو قبیله راوله او د هارون کاهن د خدمتګارانو په توګه یې وټاکه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_006.mp3', NULL, 1761758886, 1761758886),
(40967, 'Numbers 3:7', 'Numbers', 3, 7, 'دوی به په سپېڅلې خېمه کې کار کوي او د هارون او ټول قوم دپاره به دندې سرته رسوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_007.mp3', NULL, 1761758886, 1761758886),
(40968, 'Numbers 3:8', 'Numbers', 3, 8, 'هغوی به د سپېڅلې خېمې د ټول سامان مسوولیت په غاړه واخلي او د نورو اسراییلیانو دپاره به کار کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_008.mp3', NULL, 1761758886, 1761758886),
(40969, 'Numbers 3:9', 'Numbers', 3, 9, 'د لاویانو مسوولیت دا دی چې د هارون او د هغه د زامنو خدمت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_009.mp3', NULL, 1761758886, 1761758886),
(40970, 'Numbers 3:10', 'Numbers', 3, 10, 'هارون او د هغه زامن د کاهنانو په توګه د خدمت دپاره وټاکه. که بل هرڅوک سپېڅلي ځای ته ورنژدې شي، باید ووژل شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_010.mp3', NULL, 1761758886, 1761758886),
(40971, 'Numbers 3:11', 'Numbers', 3, 11, 'بیا څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_011.mp3', NULL, 1761758886, 1761758886),
(40972, 'Numbers 3:14', 'Numbers', 3, 14, 'څښتن موسی ته د سینا په دښته کې وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_014.mp3', NULL, 1761758886, 1761758886),
(40973, 'Numbers 3:15', 'Numbers', 3, 15, '«لاویان کورنۍ په کورنۍ او طایفه په طایفه وشمېره. هر نارینه چې عمر یې یوه میاشت یا زیات وي وشمېره.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_015.mp3', NULL, 1761758886, 1761758886),
(40974, 'Numbers 3:16', 'Numbers', 3, 16, 'نو څنګه چې څښتن ورته امر کړی ؤ، موسی هغوی وشمېرل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_016.mp3', NULL, 1761758886, 1761758886),
(40975, 'Numbers 3:21', 'Numbers', 3, 21, 'لبنیان او شمعیان د جرشونیانو طایفې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_021.mp3', NULL, 1761758886, 1761758886),
(40976, 'Numbers 3:22', 'Numbers', 3, 22, 'د هغو نارینه جرشونیانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او وشمېرل شول، ۷۵۰۰ تنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_022.mp3', NULL, 1761758886, 1761758886),
(40977, 'Numbers 3:23', 'Numbers', 3, 23, 'دغو طایفو د سپېڅلې خېمې شاته یعنې لوېدیځ خواته خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_023.mp3', NULL, 1761758886, 1761758886),
(40978, 'Numbers 3:24', 'Numbers', 3, 24, 'د جرشونیانو د کورنیو مشر د لایل زوی الیاساف ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_024.mp3', NULL, 1761758886, 1761758886),
(40979, 'Numbers 3:25', 'Numbers', 3, 25, 'په سپېڅلې خېمه کې جرشونیان د دغو شیانو د ساتنې مسوولان وو: د خېمې، د هغې د پوښونو، د خېمې د دروازې د پردې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_025.mp3', NULL, 1761758886, 1761758886),
(40980, 'Numbers 3:26', 'Numbers', 3, 26, 'د حوېلۍ د پردو، د هغې حوېلۍ د دروازې د پردې چې د سپېڅلې خېمې او قربانۍ د ځای ګردچاپېره ده او د هغو د رسۍ ګانو. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_026.mp3', NULL, 1761758886, 1761758886),
(40981, 'Numbers 3:27', 'Numbers', 3, 27, 'عمرامیان، یصهاریان، حبرونیان او عزییلیان د قهاتیانو طایفې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_027.mp3', NULL, 1761758886, 1761758886),
(40982, 'Numbers 3:28', 'Numbers', 3, 28, 'د هغو نارینه قهاتیانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ ۸۶۰۰ تنه وو. قهاتیانو د سپېڅلي ځای د ساتنې مسوولیت په غاړه درلود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_028.mp3', NULL, 1761758886, 1761758886),
(40983, 'Numbers 3:29', 'Numbers', 3, 29, 'دغو طایفو د سپېڅلې خېمې جنوب خواته خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_029.mp3', NULL, 1761758886, 1761758886),
(40984, 'Numbers 3:30', 'Numbers', 3, 30, 'د قهاتیانو د طایفو د کورنیو مشر د عزییل زوی الیصافان ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_030.mp3', NULL, 1761758886, 1761758886),
(40985, 'Numbers 3:31', 'Numbers', 3, 31, 'د دغو شیانو مسوولیت د هغوی په غاړه ؤ: د لوظ صندوق، مېز، څراغدان، د قربانۍ د ځایونو، هغه لوښي چې کاهنانو په سپېڅلي ځای کې ورڅخه کار اخیست او د ډېر سپېڅلي ځای د دروازې پرده. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_031.mp3', NULL, 1761758886, 1761758886),
(40986, 'Numbers 3:32', 'Numbers', 3, 32, 'د لاویانو د مشرانو رییس د هارون کاهن زوی العازار ؤ. هغه په هغو خلکو باندې مقرر شوی ؤ چې د سپېڅلي ځای د ساتنې مسوولان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_032.mp3', NULL, 1761758886, 1761758886),
(40987, 'Numbers 3:33', 'Numbers', 3, 33, 'محلیان او موشیان د مراریانو طایفې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_033.mp3', NULL, 1761758886, 1761758886),
(40988, 'Numbers 3:34', 'Numbers', 3, 34, 'د هغو نارینه مراریانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او وشمېرل شول، ۶۲۰۰ تنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_034.mp3', NULL, 1761758886, 1761758886),
(40989, 'Numbers 3:35', 'Numbers', 3, 35, 'د مراریانو د طایفو د کورنیو مشر د ابیحایل زوی صوری ییل ؤ. هغوی د سپېڅلې خېمې شمال خواته خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_035.mp3', NULL, 1761758886, 1761758886),
(40990, 'Numbers 3:36', 'Numbers', 3, 36, 'مراریان د دې دپاره ټاکل شوي وو چې د سپېڅلې خېمې په چوکاټونو، د هغې د اړمونو، ستنو، پایو او د هغې د ټول سامان ساتنه وکړي. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_036.mp3', NULL, 1761758886, 1761758886),
(40991, 'Numbers 3:37', 'Numbers', 3, 37, 'همدارنګه هغوی د ستنو، پایو، مېخونو او د هغو رسۍ ګانو مسوولیت په غاړه درلود چې د شاوخوا حوېلۍ دپاره وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_037.mp3', NULL, 1761758886, 1761758886),
(40992, 'Numbers 3:38', 'Numbers', 3, 38, 'موسی او هارون او د هارون زامنو د سپېڅلې خېمې لمرخاته خواته یعنې د سپېڅلې خېمې په مخکې خېمې ودرولې. هغوی د هغو کارونو د سرته رسولو مسوولیت په غاړه درلود چې د اسراییلو د قوم دپاره په سپېڅلي ځای کې تر سره کېدل. بل هرڅوک به چې سپېڅلي ځای ته ورنژدې کېده، هغه به وژل کېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_038.mp3', NULL, 1761758886, 1761758886),
(40993, 'Numbers 3:39', 'Numbers', 3, 39, 'د هغو ټولو نارینه لاویانو شمېر چې عمر یې یوه میاشت یا زیات ؤ او موسی او هارون د څښتن په امر طایفه په طایفه وشمېرل، ټول ۲۲۰۰۰ تنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_039.mp3', NULL, 1761758886, 1761758886),
(40994, 'Numbers 3:40', 'Numbers', 3, 40, 'څښتن موسی ته وویل: «د اسراییلو ټول مشران زامن چې عمر یې یوه میاشت یا زیات وي وشمېره او د هغوی د نومونو یو لست تیار کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_040.mp3', NULL, 1761758886, 1761758886),
(40995, 'Numbers 3:41', 'Numbers', 3, 41, 'د اسراییلو د ټولو مشرانو زامنو په ځای زما دپاره لاویان واخله او د هغوی د ټولو لومړنیو زېږېدلو حیواناتو په ځای زما دپاره د لاویانو حیوانات واخله. زه څښتن یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_041.mp3', NULL, 1761758886, 1761758886),
(40996, 'Numbers 3:42', 'Numbers', 3, 42, 'نو څنګه چې څښتن موسی ته امر کړی ؤ، هغه د اسراییلو ټول مشران زامن وشمېرل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_042.mp3', NULL, 1761758886, 1761758886),
(40997, 'Numbers 3:43', 'Numbers', 3, 43, 'د نارینه مشرانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او د هر یو نوم په لست کې لیکل شوی ؤ، ۲۲۲۷۳ تنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_043.mp3', NULL, 1761758886, 1761758886),
(40998, 'Numbers 3:44', 'Numbers', 3, 44, 'بیا څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_044.mp3', NULL, 1761758886, 1761758886),
(40999, 'Numbers 3:45', 'Numbers', 3, 45, '«اوس د اسراییلو د ټولو مشرانو زامنو په ځای لاویان وقف کړه او د لاویانو حیوانات د هغوی د حیواناتو په ځای وقف کړه. لاویان دې زما شي. زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_045.mp3', NULL, 1761758886, 1761758886),
(41000, 'Numbers 3:46', 'Numbers', 3, 46, 'په دې خاطر چې د اسراییلو مشران زامن د لاویانو په پرتله ۲۷۳ تنه زیات دي، نو ته باید اضافي زامن بېرته په بیه واخلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_046.mp3', NULL, 1761758886, 1761758886),
(41001, 'Numbers 3:47', 'Numbers', 3, 47, 'د هر کس دپاره د سپېڅلي ځای د معیار سره سم پنځه پنځه د سپینو زرو سکې راټولې کړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_047.mp3', NULL, 1761758886, 1761758886),
(41002, 'Numbers 3:48', 'Numbers', 3, 48, 'او هغه هارون او د هغه زامنو ته ورکړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_048.mp3', NULL, 1761758886, 1761758886),
(41003, 'Numbers 3:49', 'Numbers', 3, 49, 'موسی د ۲۷۳ اضافي مشرانو زامنو څخه سپین زر راټول کړل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_049.mp3', NULL, 1761758886, 1761758886),
(41004, 'Numbers 3:50', 'Numbers', 3, 50, 'چې د هغو وزن د سپېڅلي ځای د معیار له مخې ۱۳۶۵ سکې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_050.mp3', NULL, 1761758886, 1761758886),
(41005, 'Numbers 3:51', 'Numbers', 3, 51, 'هغه یې د څښتن د حکم سره سم هارون او د هغه زامنو ته ورکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers3_verse_051.mp3', NULL, 1761758886, 1761758886),
(41006, 'Zechariah 14:1', 'Zechariah', 14, 1, 'ګورئ، د مالِک خُدائ ورځ راروانه ده چې ستاسو مال به بلکل ستاسو په وړاندې لوټ کړے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_001.mp3', NULL, 1761758886, 1761758886),
(41007, 'Zechariah 14:2', 'Zechariah', 14, 2, 'زۀ به ټول قومونه راغونډ کړم چې د يروشلم خلاف جنګ وکړى، ښار به محاصره شى، کورونه به لوټ شى او ښځې به په زور بې‌عزته شى. نيم ښار به جلاوطن شى، خو نور پاتې خلق به د ښار نه بونۀ تلے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_002.mp3', NULL, 1761758886, 1761758886),
(41008, 'Zechariah 14:3', 'Zechariah', 14, 3, 'بيا به مالِک خُدائ لاړ شى او د هغه قومونو خلاف به داسې جنګ وکړى، لکه څنګه چې هغۀ پخوا جنګ کړے وو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_003.mp3', NULL, 1761758886, 1761758886),
(41009, 'Zechariah 14:4', 'Zechariah', 14, 4, 'په هغه ورځ به د هغۀ پښې د زيتُونو په غر د يروشلم مشرق طرف ته ودريږى. او د زيتُونو غر به د مشرق نه تر مغرب پورې په مينځ نيم شى، يوه لويه وادى به جوړه شى، دا غر به نيم د شمال طرف ته او نيم د جنوب طرف ته وښويږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_004.mp3', NULL, 1761758886, 1761758886),
(41010, 'Zechariah 14:5', 'Zechariah', 14, 5, 'بيا به تاسو زما د غرۀ په وادۍ کښې وتښتئ، ځکه دا به تر آضل پورې رسېدلې وى. تاسو به داسې وتښتئ لکه څنګه چې تاسو د يهوداه د بادشاه عُزياه په ورځو کښې د زلزلې نه وتښتېدلئ. بيا مالِک خُدائ زما خُدائ پاک به راشى، او ټولې پاکې فرښتې به هغۀ سره راشى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_005.mp3', NULL, 1761758886, 1761758886),
(41011, 'Zechariah 14:6', 'Zechariah', 14, 6, 'په هغه ورځ به نۀ رڼا او نۀ يخ او نۀ کنګل وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_006.mp3', NULL, 1761758886, 1761758886),
(41012, 'Zechariah 14:7', 'Zechariah', 14, 7, 'دا به يو بې‌مثاله ورځ وى، نۀ به ورځ وى نۀ به شپه وى، مالِک خُدائ ته به د دې پته وى. د ماښام په وخت کښې به هم رڼا وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_007.mp3', NULL, 1761758886, 1761758886),
(41013, 'Zechariah 14:8', 'Zechariah', 14, 8, 'په هغه ورځ به د ژوند اوبۀ د يروشلم نه بهيږى، نيمې به د مشرق سمندر ته او نيمې به د مغرب سمندر ته، په ګرمۍ او يخنۍ کښې بهيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_008.mp3', NULL, 1761758886, 1761758886),
(41014, 'Zechariah 14:9', 'Zechariah', 14, 9, 'مالِک خُدائ به په ټوله زمکه بادشاه وى، په هغه ورځ به صرف يو مالِک خُدائ وى، او صرف د هغۀ نوم به وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_009.mp3', NULL, 1761758886, 1761758886),
(41015, 'Zechariah 14:10', 'Zechariah', 14, 10, 'ټول مُلک، د جبع نه تر رِمون پورې، د يروشلم جنوب طرف ته، به لکه د عرابه د وادۍ په شان شى. خو يروشلم به بيا اوچت شى او په خپل ځائ به ودريږى، د بنيامين د دروازې نه تر د زړې دروازې پورې، د ګوټ دروازې پورې، او د حنن‌ايل د برج نه تر د شاهى انګورو د لنګرو پورې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_010.mp3', NULL, 1761758886, 1761758886),
(41016, 'Zechariah 14:11', 'Zechariah', 14, 11, 'دا به بيا آباد شى، دا به بيا هيڅکله هم تباه نۀ شى. يروشلم به محفوظ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_011.mp3', NULL, 1761758886, 1761758886),
(41017, 'Zechariah 14:12', 'Zechariah', 14, 12, 'دا هغه وبا ده چې مالِک خُدائ به په دې هغه خلق مړۀ کړى چا چې د يروشلم خلاف جنګ کړے وو. د هغوئ غوښې به سخا شى چې لا دوئ په خپلو پښو ولاړ وى، د دوئ سترګې به په خپل ځائ سخا شى، او د دوئ ژبې به د دوئ په خُلو کښې سخا شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_012.mp3', NULL, 1761758886, 1761758886),
(41018, 'Zechariah 14:13', 'Zechariah', 14, 13, 'په هغه ورځ به مالِک خُدائ خلق په لوئ درد اخته کړى. هر سړے به د بل لاس راونيسى، او هغوئ به په يو بل حمله وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_013.mp3', NULL, 1761758886, 1761758886),
(41019, 'Zechariah 14:14', 'Zechariah', 14, 14, 'تر دې چې يهوداه او يروشلم به په خپلو کښې جنګ کوى. د ګېرچاپېره ټولو قومونو دولت به راغونډ کړے شى، چې په کښې به په لوئ مِقدار سرۀ زر او سپين زر او جامې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_014.mp3', NULL, 1761758886, 1761758886),
(41020, 'Zechariah 14:15', 'Zechariah', 14, 15, 'هم دغه شان به په آسونو او قچرو، اوښانو، خرونو او چې څومره ځناور په هغه ځائ کښې دى افت نازل شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_015.mp3', NULL, 1761758886, 1761758886),
(41021, 'Zechariah 14:16', 'Zechariah', 14, 16, 'بيا به د ټولو قومونو پاتې ژوندى کسان چا چې په يروشلم حمله کړې وه کال په کال د بادشاه، مالِک خُدائ ربُ الافواج عبادت ته هلته ځى، او د جونګړو اختر به کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_016.mp3', NULL, 1761758886, 1761758886),
(41022, 'Zechariah 14:17', 'Zechariah', 14, 17, 'خو کۀ هر قوم يروشلم ته د تلو او د بادشاه مالِک خُدائ ربُ الافواج د عبادت نه اِنکار وکړى، نو په هغوئ به باران نۀ کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_017.mp3', NULL, 1761758886, 1761758886),
(41023, 'Zechariah 14:18', 'Zechariah', 14, 18, 'کۀ مِصريان هلته لاړ نۀ شى او خپل ځانونه هلته حاضر نۀ کړى، نو په هغوئ به باران نۀ کيږى. مالِک خُدائ به په هغوئ هغه وبا نازله کړى چې مالِک خُدائ يې په هغه قومونو رالېږى څوک چې د جونګړو اختر لمانځلو له نۀ ځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_018.mp3', NULL, 1761758886, 1761758886),
(41024, 'Zechariah 14:19', 'Zechariah', 14, 19, 'دا به د مِصر او د هغه ټولو قومونو سزا وى چې څوک د جونګړو اختر لمانځلو له نۀ ځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_019.mp3', NULL, 1761758886, 1761758886),
(41025, 'Zechariah 14:20', 'Zechariah', 14, 20, 'په هغه ورځ به د آسونو په ګونګرو باندې هم ليکلى وى ”مالِک خُدائ ته مقدس کړے شوى“ او د پخلى دېګونه د مالِک خُدائ په کور کښې به لکه د هغه مقدسو لوښو په شان وى چې د قربان‌ګاه په وړاندې دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_020.mp3', NULL, 1761758886, 1761758886),
(41026, 'Zechariah 14:21', 'Zechariah', 14, 21, 'هر يو لوښے به په يروشلم او يهوداه کښې مالِک خُدائ ربُ الافواج ته مقدس وى. او هغوئ ټول چې قربانۍ کولو له راغلى دى هغوئ به څۀ لوښى واخلى او په کښې به پخلى کولے شى. او په هغه ورځ به د مالِک خُدائ ربُ الافواج په کور کښې يو کنعانى سوداګر هم پاتې نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah14_verse_021.mp3', NULL, 1761758886, 1761758886),
(41027, 'Ezekiel 14:1', 'Ezekiel', 14, 1, 'د اسراییلو ځینې مشران راغلل چې زما سره د خدای د رضا د معلومولو په هکله مشوره وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_001.mp3', NULL, 1761758886, 1761758886),
(41028, 'Ezekiel 14:2', 'Ezekiel', 14, 2, 'بیا څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_002.mp3', NULL, 1761758886, 1761758886),
(41029, 'Ezekiel 14:3', 'Ezekiel', 14, 3, '«ای فاني انسانه، دې خلکو بتانو ته په خپلو زړونو کې ځای ورکړی دی او بت پرستي د هغوی د ګناه سبب ګرځېدلې ده. ایا هغوی فکر کوي چې زه به ورته مشوره ورکړم؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_003.mp3', NULL, 1761758886, 1761758886),
(41030, 'Ezekiel 14:4', 'Ezekiel', 14, 4, 'زما یعنې څښتن تعالی له خوا هغوی ته ووایه: ‹هر اسراییلی چې د بتانو څخه پیروي کوي او د ګناه په لاره ځي او په هغه وخت کې کله چې هغه د مشورې دپاره پیغمبر ته راځي، نو زه څښتن به خپله هغوی ته ځواب ورکوم، داسې ځواب چې دا بت پرستان د هغه لایق دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_004.mp3', NULL, 1761758886, 1761758886),
(41031, 'Ezekiel 14:5', 'Ezekiel', 14, 5, 'زه به هغوی ته ځواب ورکړم ترڅو وکولای شم د اسراییلو خلک چې د خپلو ټولو بتانو له امله زما څخه لېرې شوي دي، بېرته خپل ځان ته راوګرځوم.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_005.mp3', NULL, 1761758886, 1761758886),
(41032, 'Ezekiel 14:6', 'Ezekiel', 14, 6, 'نو اسراییلیانو ته ووایه چې زه څښتن تعالی داسې وایم: ‹توبه وباسئ او خپل بتان او د کرکې وړ کارونه پرېږدئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_006.mp3', NULL, 1761758886, 1761758886),
(41033, 'Ezekiel 14:7', 'Ezekiel', 14, 7, 'فرض کړئ یو اسراییلی یا کوم پردی سړی چې په اسراییلو کې اوسیږي او خپل ځان زما نه بېلوي، هغه په خپل زړه کې بتانو ته ځای ورکوي او هغه دا بتان د خپلو سترګو په وړاندې ږدي او هغه د ګناه خواته ځي. کله چې هغه د مشورې دپاره پیغمبر ته راځي، نو زه څښتن به په خپله هغه ته ځواب ورکړم!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_007.mp3', NULL, 1761758886, 1761758886),
(41034, 'Ezekiel 14:8', 'Ezekiel', 14, 8, 'زه به د هغه په ضد شم. هغه به د نورو دپاره د عبرت سبب وګرځوم. زه به یې د خپل قوم نه وباسم، بیا به تاسو په دې پوه شئ چې زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_008.mp3', NULL, 1761758886, 1761758886),
(41035, 'Ezekiel 14:9', 'Ezekiel', 14, 9, 'که چېرې یو پیغمبر وغولیږي او غلط ځواب ورکړي، نو دلیل به یې دا وي چې هغه ما یعنې څښتن غولولی دی. زه به هغه پیغمبر ته سزا ورکړم او د خپل قوم اسراییلو نه به یې بیخي لېرې کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_009.mp3', NULL, 1761758886, 1761758886),
(41036, 'Ezekiel 14:10', 'Ezekiel', 14, 10, 'هغه پیغمبر او هغه څوک چې د هغه نه مشوره اخلي، دواړو ته به یوشان سزا ورکول کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_010.mp3', NULL, 1761758886, 1761758886),
(41037, 'Ezekiel 14:11', 'Ezekiel', 14, 11, 'دا کار د دې دپاره کوم چې نور اسراییلیان زما څخه بې‌لارې نه شي او خپل ځانونه نور په ګناهونو باندې ناپاکه نه کړي. نو هغوی به زما قوم وي او زه به د هغوی خدای یم. څښتن تعالی داسې وویل.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_011.mp3', NULL, 1761758886, 1761758886),
(41038, 'Ezekiel 14:12', 'Ezekiel', 14, 12, 'څښتن زما سره خبرې وکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_012.mp3', NULL, 1761758886, 1761758886),
(41039, 'Ezekiel 14:13', 'Ezekiel', 14, 13, 'هغه وویل: «ای فاني انسانه، کله چې د یو هېواد خلک ګناه او زما سره بې‌وفایي وکړي، نو زه به د هغوی په وړاندې لاس پورته کړم او خواړه به ورباندې بند کړم. زه به ورباندې قحطي راولم او خلک او حیوانات به یې ووژنم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_013.mp3', NULL, 1761758886, 1761758886),
(41040, 'Ezekiel 14:14', 'Ezekiel', 14, 14, 'که هغه درې کسان یعنې نوح، دانیال او ایوب هم هلته اوسي، نو زه به هغوی د خپلې رښتینولۍ له امله وژغورم، خو یوازې هغوی به زه ژغورم. څښتن تعالی داسې وویل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_014.mp3', NULL, 1761758886, 1761758886),
(41041, 'Ezekiel 14:15', 'Ezekiel', 14, 15, 'یا فرض کړئ زه هغه هېواد ته ځنګلي حیوانات ورولېږم چې خلک وخوري او هغه هېواد دومره خطرناکه کړي چې هېڅوک په هغه لاره تېرېدلی نه شي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_015.mp3', NULL, 1761758886, 1761758886),
(41042, 'Ezekiel 14:16', 'Ezekiel', 14, 16, 'حتی که هغه درې کسان هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به هم ونه شي کولای چې خپل زامن او لورګانې وژغوري. یوازې هغوی به وژغورل شي او هغه هېواد به وران او ویجاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_016.mp3', NULL, 1761758886, 1761758886),
(41043, 'Ezekiel 14:17', 'Ezekiel', 14, 17, 'یا فرض کړئ زه په هغه وطن باندې جنګ راولم او د دښمن لښکرې ورولېږم چې انسانان او حیوانات ټول له منځه یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_017.mp3', NULL, 1761758886, 1761758886),
(41044, 'Ezekiel 14:18', 'Ezekiel', 14, 18, 'که هغه درې کسان هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به ونه شي کولای چې خپل زامن او لورګانې وژغوري. یوازې هغوی به وژغورل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_018.mp3', NULL, 1761758886, 1761758886),
(41045, 'Ezekiel 14:19', 'Ezekiel', 14, 19, 'یا فرض کړئ زه په هغه هېواد باندې وبا راولم او د قهر له لاسه د ډېرو انسانانو او حیواناتو ژوند واخلم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_019.mp3', NULL, 1761758886, 1761758886),
(41046, 'Ezekiel 14:20', 'Ezekiel', 14, 20, 'که نوح، دانیال او ایوب هم هلته اوسي، نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې هغوی به نه شي کولای چې خپل زوی او لور وژغوري. د هغوی رښتینولي به یوازې د هغوی ژوند وژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_020.mp3', NULL, 1761758886, 1761758886),
(41047, 'Ezekiel 14:21', 'Ezekiel', 14, 21, 'څښتن تعالی داسې وایي: ‹دا به څومره بده وي چې زه په اورشلیم باندې څلور ډېرې سختې سزاګانې یعنې جنګ، قحطي، ځنګلي حیوانات او وبا ورولېږم چې انسانان او حیوانات ټول ووژني.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_021.mp3', NULL, 1761758886, 1761758886),
(41048, 'Ezekiel 14:22', 'Ezekiel', 14, 22, 'ګورئ، ځینې سړي او ښځې به په اورشلیم کې ژوندي پاتې شي او هغوی به د هغه ځای څخه دباندې وویستل شي. کله چې هغوی په بابل کې ستاسو خواته راشي، نو وبه وینئ چې هغوی څومره بدعمله خلک دي او په دې به قانع شئ، ځکه کومه سزا چې ما اورشلیم ته ورکړې ده، هغه عادلانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_022.mp3', NULL, 1761758886, 1761758886),
(41049, 'Ezekiel 14:23', 'Ezekiel', 14, 23, 'هو، تاسو به په دې قانع شئ، څه چې ما څښتن تعالی کړي دي، زه په حقه یم. څښتن تعالی داسې ویلي دي.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel14_verse_023.mp3', NULL, 1761758886, 1761758886),
(41050, 'Isaiah 18:1', 'Isaiah', 18, 1, 'افسوس د ایتوپیا په حال چې په سیندونو کې یې د کشتۍ ګانو د بادبان اواز اورېدل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_001.mp3', NULL, 1761758886, 1761758886),
(41051, 'Isaiah 18:2', 'Isaiah', 18, 2, 'هغه وطن خپل استازي د بحیرې له لارې په داسې کشتۍ ګانو کې لېږي چې د لوخو څخه جوړې شوې دي. ای چالاکو استازو، دا پیغام هغه قوم ته یوسئ چې قوي او جنګیالی دی، هغه چې لوړ قدونه او ښویه پوستکي لري او د ټولې نړۍ خلک ورڅخه وېریږي، د هغه وطن څخه چې په سیندونو باندې وېشل شوی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_002.mp3', NULL, 1761758886, 1761758886),
(41052, 'Isaiah 18:3', 'Isaiah', 18, 3, 'ای د ټولې نړۍ خلکو واورئ! کله چې بیرغ د نښې په توګه د غرونو په سرونو درول کیږي، وګورئ! د سورني هغه اواز ته چې د جګړې دپاره غږول کیږي، غوږ ونیسئ!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_003.mp3', NULL, 1761758886, 1761758886),
(41053, 'Isaiah 18:4', 'Isaiah', 18, 4, 'ځکه چې څښتن ماته داسې وویل: «زه به د خپل استوګنځي څخه داسې په ارامۍ سره لاندې ګورم لکه څنګه چې پرخه د لو په وخت کې وریږي او لکه لمر چې د ورځې په ګرمۍ کې ځلیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_004.mp3', NULL, 1761758886, 1761758886),
(41054, 'Isaiah 18:5', 'Isaiah', 18, 5, 'مخکې له دې چې انګور راټول شي، کله چې د ګل پاڼې راوغورځیږي او انګور پاخه شي، څښتن به د انګورو له تاکونو څخه نودې په چاقو او څانګې به یې په اره باندې پرې کړي او لېرې وغورځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_005.mp3', NULL, 1761758886, 1761758886),
(41055, 'Isaiah 18:6', 'Isaiah', 18, 6, 'هغه به ټول د غرونو ښکاري مرغانو او وحشي حیواناتو ته پراته وي. په اوړي کې به هغه د مرغانو خوراک وي او په ژمي کې به د حیواناتو خوراک وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_006.mp3', NULL, 1761758886, 1761758886),
(41056, 'Isaiah 18:7', 'Isaiah', 18, 7, 'په هغه وخت کې به هغه قوي او جنګیالی قوم چې لوړ قدونه او ښویه پوستکي لري او د ټولې نړۍ خلک ورڅخه وېریږي، د هغه وطن څخه چې په سیندونو باندې وېشل شوی دی، د صهیون غره ته راشي، هغه ځای ته چې د مطلق قادر څښتن نوم په کې یادیږي او هغه ته به نذرانې او سوغاتونه راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah18_verse_007.mp3', NULL, 1761758886, 1761758886),
(41057, 'Ezekiel 2:1', 'Ezekiel', 2, 1, 'هغه ماته وویل: «ای فاني انسانه، پاڅېږه او په خپلو پښو ودرېږه. زه غواړم ستا سره خبرې وکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_001.mp3', NULL, 1761758886, 1761758886),
(41058, 'Ezekiel 2:2', 'Ezekiel', 2, 2, 'کله چې هغه زما سره خبرې کولې، نو د خدای روح په ما باندې نازل شو او زه یې په پښو ودرولم او ما د هغه خبرې واورېدلې چې داسې یې ماته ویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_002.mp3', NULL, 1761758886, 1761758886),
(41059, 'Ezekiel 2:3', 'Ezekiel', 2, 3, '«ای فاني انسانه، زه تا د اسراییلو قوم ته لېږم، یعنې هغه سرکښه قوم ته چې زما په وړاندې یې سرکښي کړې ده. هغوی او د هغوی نیکونه تر نن ورځې پورې زما په وړاندې سرکښي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_003.mp3', NULL, 1761758886, 1761758886),
(41060, 'Ezekiel 2:4', 'Ezekiel', 2, 4, 'اوسني خلک هم سرزوري دي او زما درناوی نه کوي، نو زه څښتن تعالی تا هغوی ته لېږم چې زما پیغام هغوی ته ورسوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_004.mp3', NULL, 1761758886, 1761758886),
(41061, 'Ezekiel 2:5', 'Ezekiel', 2, 5, 'که دا خلک غوږ نیسي یا نه نیسي، دا سرکښه قوم به پوه شي چې د هغوی په منځ کې یو پیغمبر ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_005.mp3', NULL, 1761758886, 1761758886),
(41062, 'Ezekiel 2:6', 'Ezekiel', 2, 6, 'خو ای فاني انسانه، د هغه قوم او د هغو د خبرو څخه مه وېرېږه، که د هغوی خبرې لکه د اغزن بوټي او د لړم د نېش په شان هم وي بیاهم مه وېرېږه، ځکه چې هغوی یو سرکښه قوم دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_006.mp3', NULL, 1761758886, 1761758886),
(41063, 'Ezekiel 2:7', 'Ezekiel', 2, 7, 'هرڅه چې زه درته وایم هغوی ته یې ووایه، که هغوی ورته غوږ ونیسي او یا یې ونه نیسي. ځکه چې هغوی یو سرکښه قوم دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_007.mp3', NULL, 1761758886, 1761758886),
(41064, 'Ezekiel 2:8', 'Ezekiel', 2, 8, 'خو ای فاني انسانه، څه چې زه درته وایم، نو غوږ ورته ونیسه. د هغه سرکښه قوم په شان نه شې. خوله دې خلاصه کړه او څه چې تاته درکوم، هغه وخوره.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_008.mp3', NULL, 1761758886, 1761758886),
(41065, 'Ezekiel 2:9', 'Ezekiel', 2, 9, 'په همدې شېبه مې ولیدل چې یو لاس زما خواته را‌اوږد شو او په هغه کې یو طومار ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_009.mp3', NULL, 1761758886, 1761758886),
(41066, 'Ezekiel 2:10', 'Ezekiel', 2, 10, 'هغه طومار زما په مخکې پرانیست او د هغه په دواړو مخونو کې د ویر او افسوس کیسې لیکل شوې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel2_verse_010.mp3', NULL, 1761758886, 1761758886),
(41067, 'Exodus 13:1', 'Exodus', 13, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_001.mp3', NULL, 1761758886, 1761758886),
(41068, 'Exodus 13:2', 'Exodus', 13, 2, '«د اسراییلیانو ټول لومړني زېږېدل شوي زامن او هر لومړنی زېږېدلی نر حیوان ماته وقف کړه. هغه زما دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_002.mp3', NULL, 1761758886, 1761758886),
(41069, 'Exodus 13:3', 'Exodus', 13, 3, 'موسی قوم ته وویل: «دا ورځ په یاد ساتئ، یعنې هغه ورځ چې تاسو له مصر څخه چې په کې غلامان وئ، ووتلئ. دا هغه ورځ ده چې څښتن په خپل لوی قدرت سره تاسو له مصر څخه راوویستلئ. تاسو خمیره ډوډۍ مه خورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_003.mp3', NULL, 1761758886, 1761758886),
(41070, 'Exodus 13:4', 'Exodus', 13, 4, 'نن تاسو په لومړۍ میاشت چې د ابیب میاشت ده د مصر څخه روان یئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_004.mp3', NULL, 1761758886, 1761758886),
(41071, 'Exodus 13:5', 'Exodus', 13, 5, 'کله چې څښتن تاسو د کنعانیانو، حیتیانو، اموریانو، حویانو او یبوسیانو غني او حاصلخېزې ځمکې ته چې د هغې وعده یې ستاسو د نیکونو سره کړې ده راولي، تاسو باید دا اختر د هر کال په لومړۍ میاشت ولمانځئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_005.mp3', NULL, 1761758886, 1761758886),
(41072, 'Exodus 13:6', 'Exodus', 13, 6, 'اووه ورځې فطیره ډوډۍ وخورئ او په اوومه ورځ د څښتن د درناوي دپاره جشن ونیسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_006.mp3', NULL, 1761758886, 1761758886),
(41073, 'Exodus 13:7', 'Exodus', 13, 7, 'اووه ورځې باید فطیره ډوډۍ وخورئ، ستاسو د هېواد په هېڅ ځای کې دې خمیره نه وي او نه دې خمیره ډوډۍ وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_007.mp3', NULL, 1761758886, 1761758886),
(41074, 'Exodus 13:8', 'Exodus', 13, 8, 'د اختر په پیل کې خپلو زامنو ته داسې ووایئ چې مونږ دا هرڅه د هغه څه له امله کوو چې څښتن زمونږ دپاره د مصر څخه د راوتلو په وخت کې وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_008.mp3', NULL, 1761758886, 1761758886),
(41075, 'Exodus 13:9', 'Exodus', 13, 9, 'دا مراسم به لکه د یوې نښې په شان چې تاسو یې په خپل لاس یا تندي باندې تړئ، یو یادګار وي. دا به تاسو ته په لوړ اواز د څښتن د شریعت دوامداره ویل در په یادوي، ځکه چې څښتن په خپل لوی قدرت تاسو د مصر څخه راوویستلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_009.mp3', NULL, 1761758886, 1761758886),
(41076, 'Exodus 13:10', 'Exodus', 13, 10, 'تاسو باید دا اختر د هر کال په ټاکل شوي وخت کې ولمانځئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_010.mp3', NULL, 1761758886, 1761758886),
(41077, 'Exodus 13:11', 'Exodus', 13, 11, 'څښتن به تاسو د هغې وعدې سره سم چې تاسو او ستاسو د نیکونو سره یې کړې ده، د کنعانیانو وطن ته راولي. کله چې هغه وطن تاسو ته درکړي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_011.mp3', NULL, 1761758886, 1761758886),
(41078, 'Exodus 13:12', 'Exodus', 13, 12, 'باید ټول لومړني زېږېدل شوي نارینه څښتن ته وقف کړئ. هر لومړنی زېږېدلی نر حیوان د څښتن دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_012.mp3', NULL, 1761758886, 1761758886),
(41079, 'Exodus 13:13', 'Exodus', 13, 13, 'تاسو باید هر نر خر بېرته په بیه واخلئ او د هغه په ځای یو وری قرباني کړئ. که چېرې تاسو نه غواړئ چې هغه خر بېرته په بیه واخلئ، نو د هغه ورمېږ مات کړئ. تاسو باید خپل ټول مشران زامن بېرته په بیه واخلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_013.mp3', NULL, 1761758886, 1761758886),
(41080, 'Exodus 13:14', 'Exodus', 13, 14, 'کله چې په راتلونکې کې ستاسو څخه خپل زامن پوښتنه وکړي چې دا مراسم څه معنی لري؟ تاسو به هغوی ته په ځواب کې ووایئ چې څښتن په خپل لوی قدرت سره له مصر څخه چې مونږ په کې غلامان وو، راوویستلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_014.mp3', NULL, 1761758886, 1761758886),
(41081, 'Exodus 13:15', 'Exodus', 13, 15, 'هغه وخت چې د فرعون زړه سخت ؤ او مونږ یې نه پرېښودلو چې د مصر څخه لاړ شو، نو څښتن په مصر کې هر لومړنی زېږېدلی نر حیوان او انسان وواژه. ځکه مونږ څښتن ته هر لومړنی زېږېدلی نر حیوان قرباني کوو او خپل ټول لومړني زامن بېرته په بیه اخلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_015.mp3', NULL, 1761758886, 1761758886),
(41082, 'Exodus 13:16', 'Exodus', 13, 16, 'دا مراسم به لکه د یوې نښې په شان چې مونږ یې په خپلو لاسونو یا خپلو تندیو باندې وتړو، یو یادګار وي. دا به مونږ ته دا خبره را په یادوي چې څښتن په خپل قدرت مونږ له مصر څخه راوویستلو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_016.mp3', NULL, 1761758886, 1761758886),
(41083, 'Exodus 13:17', 'Exodus', 13, 17, 'کله چې فرعون د اسراییلو قوم پرېښود چې لاړ شي، که څه هم هغه لاره لنډه وه، خو خدای هغوی پرېنښودل چې د فلسطین په لارې باندې لاړ شي، ځکه چې خدای وویل: «که چېرې هغوی د جګړې سره مخامخ شي، کېدای شي چې خپله پرېکړه بدله کړي او بېرته مصر ته راستانه شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_017.mp3', NULL, 1761758886, 1761758886),
(41084, 'Exodus 13:18', 'Exodus', 13, 18, 'د هغې په ځای یې هغوی د دښتې په لاره چې کږه وږه لار وه، د سرې بحیرې خواته بوتلل. اسراییلیان د جګړې دپاره په وسلو سمبال وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_018.mp3', NULL, 1761758886, 1761758886),
(41085, 'Exodus 13:19', 'Exodus', 13, 19, 'موسی د یوسف هډوکي د ځان سره یووړل، ځکه چې یوسف اسراییلیانو ته قسم ورکړی ؤ. هغه ویلي وو: «خدای به په رښتیا سره ستاسو مرستې ته راشي، بیا تاسو زما هډوکي د دې ځای څخه یوسئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_019.mp3', NULL, 1761758886, 1761758886),
(41086, 'Exodus 13:20', 'Exodus', 13, 20, 'اسراییلیان د سوکوت څخه لاړل او په ایتام کې یې د دښتې په یوه ګوښه کې خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_020.mp3', NULL, 1761758886, 1761758886),
(41087, 'Exodus 13:21', 'Exodus', 13, 21, 'د ورځې له خوا به څښتن په داسې ورېځ کې چې د ستنې په شان وه، د هغوی په مخکې روان ؤ چې هغوی ته لاره وروښایي او د شپې له خوا به په داسې اور کې چې د ستنې په شان ؤ روان ؤ، ترڅو هغوی ته رڼا وکړي. نو هغوی کولای شول چې شپه او ورځ سفر وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_021.mp3', NULL, 1761758886, 1761758886),
(41088, 'Exodus 13:22', 'Exodus', 13, 22, 'هغه ورېځ به په ورځ کې او هغه اور به په شپه کې د هغوی د مخې څخه نه لېرې کېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus13_verse_022.mp3', NULL, 1761758886, 1761758886),
(41089, 'Judges 5:1', 'Judges', 5, 1, 'په هغه ورځ دبورې او د ابینوعم زوی باراق دا سندره وویله:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_001.mp3', NULL, 1761758886, 1761758886),
(41090, 'Judges 5:2', 'Judges', 5, 2, 'وکړئ ستاینه د څښتن چې مشري د اسراییلو رهبران کړي او په خوښۍ سره کړي خلک پیروي د هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_002.mp3', NULL, 1761758886, 1761758886),
(41091, 'Judges 5:3', 'Judges', 5, 3, 'تاسې واورئ پاچاهانو وکړئ پام ای حاکمانو غږومه به زه ساز او وایم به سندره د اسراییلو څښتن خدای ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_003.mp3', NULL, 1761758886, 1761758886),
(41092, 'Judges 5:4', 'Judges', 5, 4, 'کله لاړې د سعیر نه چې څښتنه چې راووتې له سیمې د ادومه ځمکه شوله په لړزه باران راغی د اسمان نه هو، شولې د ورېځو نه راتوی اوبه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_004.mp3', NULL, 1761758886, 1761758886),
(41093, 'Judges 5:5', 'Judges', 5, 5, 'د سینا د څښتن مخکې په لړزه شول غرونه د څښتن د اسراییلو خدای په مخکې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_005.mp3', NULL, 1761758886, 1761758886),
(41094, 'Judges 5:6', 'Judges', 5, 6, 'د عنات د زوی شمجر په زمانه کې د یاعیل په زمانه کې کاروانو ته خطرناک وو سرکونه مسافر په کږو لارو باندې تلل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_006.mp3', NULL, 1761758886, 1761758886),
(41095, 'Judges 5:7', 'Judges', 5, 7, 'ای دبورې، د اسراییلو کلي وران پاتې شول ستا تر راتګه پورې تش پاتې شول ته راغلې اسراییلو ته د یوې مور په شان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_007.mp3', NULL, 1761758886, 1761758886),
(41096, 'Judges 5:8', 'Judges', 5, 8, 'کله چې غوره کړل اسراييلیانو نوي خدایان بیا په دې خاوره باندې جنګ راغی د څلوېښت زرو اسراییلو منځ کې یوه نېزه او یا یو سپر هم نه ؤ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_008.mp3', NULL, 1761758886, 1761758886),
(41097, 'Judges 5:9', 'Judges', 5, 9, 'د اسراییل د قوماندانانو طرفدار یمه زه د هغو خلکو په خوا چې حاضر شوي دي په خپله خوښه وکړئ ستاینه د څښتن', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_009.mp3', NULL, 1761758886, 1761758886),
(41098, 'Judges 5:10', 'Judges', 5, 10, 'واورئ ای خلکو چې سپرېږئ په ښو خرو باندې او کښېنئ په کتو باندې او هغو خلکو چې پیاده ګرځئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_010.mp3', NULL, 1761758886, 1761758886),
(41099, 'Judges 5:11', 'Judges', 5, 11, 'د سندرغاړو اوازونه ګودرو کې واورئ بیانوي چې د څښتن فتحې د اسراییلو د قوم فتحې بیا د څښتن قوم روان شو ښکته د ښار د دروازو په طرف', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_011.mp3', NULL, 1761758886, 1761758886),
(41100, 'Judges 5:12', 'Judges', 5, 12, 'شه راویښه، شه راویښه، دبورې شه راویښه په سندره کړه لاس پورې ای باراقه، ای ته زوی د ابینوعمه پاڅه بوځه اسیران درسره خپل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_012.mp3', NULL, 1761758886, 1761758886),
(41101, 'Judges 5:13', 'Judges', 5, 13, 'بیا چې کوم خلک وو پاتې شوي شول راښکته هغوی خپلو مشرانو ته د څښتن قوم ماته راغی چې جګړې ته ؤ تیار', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_013.mp3', NULL, 1761758886, 1761758886),
(41102, 'Judges 5:14', 'Judges', 5, 14, 'لاندې درې ته راغلل له افرایمه هغوی د بنیامین او د هغوی د خلکو پسې قوماندانان شولو راښکته د ماخیره څخه منصبداران له زبولونه راغلل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_014.mp3', NULL, 1761758886, 1761758886),
(41103, 'Judges 5:15', 'Judges', 5, 15, 'د دبورې سره مشران د یساکار راغلل هو، یساکار او هم باراق راغی دوی شول په منډه په دره کې د باراق پسې خو د روبین په قبیله کې شو پیدا نفاق پرېکړه ونه شوه کړای هغوی چې راشي که نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_015.mp3', NULL, 1761758886, 1761758886),
(41104, 'Judges 5:16', 'Judges', 5, 16, 'خپلو پسونو سره ولې تاسو پاتې شولئ؟ چې غوږ ونیسئ شپنو ته چې رمو ته اوازونه کاندي؟ هو، د روبین په قبیله کې شو پیدا نفاق پرېکړه یې ونه شوه کړای هغوی چې راشي که نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_016.mp3', NULL, 1761758886, 1761758886),
(41105, 'Judges 5:17', 'Judges', 5, 17, 'قبیله د جاد شوه پاتې د اردن د سیند ختیځ کې او قبیله د دان شوه پاتې کشتۍ ګانو سره قبیله د اشیر پاتې شوه د بحیرې په غاړه بندرونو ته نژدې شول ساکن هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_017.mp3', NULL, 1761758886, 1761758886),
(41106, 'Judges 5:18', 'Judges', 5, 18, 'خو د زبولون او نفتالي خلکو خطر کې واچاوه خپل ژوند د جنګ میدان کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_018.mp3', NULL, 1761758886, 1761758886),
(41107, 'Judges 5:19', 'Judges', 5, 19, 'پاچاهان راغلل، په تعنک کې د مجدو د ویالې څنګ کې هغوی وکړه جګړه د کنعان شاهانو وکړه جګړه خو یونوړل هغوی سپین زر', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_019.mp3', NULL, 1761758886, 1761758886),
(41108, 'Judges 5:20', 'Judges', 5, 20, 'ستورو کوله چې جګړه د اسمانونو څخه چې په اسمان کې ګرځېدل به هغوی یو خوا بل خوا هغوی کوله جګړه په ضد د سیسرا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_020.mp3', NULL, 1761758886, 1761758886),
(41109, 'Judges 5:21', 'Judges', 5, 21, 'دښمنان له منځه یووړل د قیشون سېلاب د قیشون څپې وهونکي سیند ای زما ځانه، روانېږه او قوي اوسه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_021.mp3', NULL, 1761758886, 1761758886),
(41110, 'Judges 5:22', 'Judges', 5, 22, 'د سیسرا اسونه تلل ښه په ترپکو باندې ځمکه یې چیته کړله خپلو سومانو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_022.mp3', NULL, 1761758886, 1761758886),
(41111, 'Judges 5:23', 'Judges', 5, 23, 'د څښتن فرښته وایي: په میروز باندې لعنت ووایئ د هغه ځای په اوسېدونکو سخت لعنت ووایئ ځکه چې دوی د څښتن مرستې ته راغلي نه دي چې کومک وکړي د څښتن سره مقابله کې د قوي جنګیالو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_023.mp3', NULL, 1761758886, 1761758886),
(41112, 'Judges 5:24', 'Judges', 5, 24, 'یاعیل ده ډېره بختوره چې ده ښځه د حابر قیني زیات برکت دې هغه ومومي تر ټولو ښځو چې په خېمو کې اوسي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_024.mp3', NULL, 1761758886, 1761758886),
(41113, 'Judges 5:25', 'Judges', 5, 25, 'سیسرا وغوښتې اوبه خو هغې ورکړې شیدې په شاهانه جام کې یې ورکړې شړومبې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_025.mp3', NULL, 1761758886, 1761758886),
(41114, 'Judges 5:26', 'Judges', 5, 26, 'هغې واخیست په یو لاس کې د خېمې موږی او په بل لاس کې یې څټک د مزدور هغې وواهه سیسرا او کړه ورماته یې کوپړۍ او شقیقه یې کړه سورۍ د هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_026.mp3', NULL, 1761758886, 1761758886),
(41115, 'Judges 5:27', 'Judges', 5, 27, 'سیسرا ولوېدلو پښو ته د هغې هغه وغورځېد او پروت ؤ هلته هغه وغورځېده پښو ته د هغې او ولوېد هغه په ځمکه باندې مړ پرېوت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_027.mp3', NULL, 1761758886, 1761758886),
(41116, 'Judges 5:28', 'Judges', 5, 28, 'د کړکۍ نه د سیسرا مور وکتل په ځیر ځیر یې د جالۍ له شا کتل هغې وکړله پوښتنه: ولې ځنډ وکړ په راتللو کې جنګي ګاډۍ د هغه؟ ولې نه اورو اواز د ګاډۍ د ارابو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_028.mp3', NULL, 1761758886, 1761758886),
(41117, 'Judges 5:29', 'Judges', 5, 29, 'پوهه ملګرې د هغې ورته ځواب ورکوي تکراروي هغه د ځان سره دا خبرې:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_029.mp3', NULL, 1761758886, 1761758886),
(41118, 'Judges 5:30', 'Judges', 5, 30, 'هغوی نیولی غنیمت او هغه وېشي سره یوه انجلۍ یا دوه نجونې هر عسکر دپاره رنګین لباس د سیسرا دپاره ګلدوزي شوې ټوټې زما غاړې ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_030.mp3', NULL, 1761758886, 1761758886),
(41119, 'Judges 5:31', 'Judges', 5, 31, 'ای څښتنه! دښمنان دې ستا هلاک شي د سیسرا په ډول ټول خو دوستان دې ستا ځلیږي د روښانه لمر په شان له هغې وروسته په هغه خاوره کې څلوېښت کاله ارامي وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges5_verse_031.mp3', NULL, 1761758886, 1761758886),
(41120, 'Exodus 24:1', 'Exodus', 24, 1, 'څښتن موسی ته وویل: «ته، هارون، ناداب، ابیهو او د اسراییلو اویا مشران ماته غره ته راوخېژئ او د لېرې فاصلې څخه راته سجده وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_001.mp3', NULL, 1761758886, 1761758886),
(41121, 'Exodus 24:2', 'Exodus', 24, 2, 'یوازې ته ماته نژدې راشه او نور دې راته نژدې نه راځي. د اسراییلو د قوم د نورو خلکو څخه دې هېڅوک هم غره ته نه راخېژي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_002.mp3', NULL, 1761758886, 1761758886),
(41122, 'Exodus 24:3', 'Exodus', 24, 3, 'کله چې موسی راغی او خلکو ته یې د څښتن ټولې خبرې او قوانین اعلان کړل، هغوی په یو اواز په ځواب کې وویل: «مونږ به د څښتن په هره خبره باندې عمل کوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_003.mp3', NULL, 1761758886, 1761758886),
(41123, 'Exodus 24:4', 'Exodus', 24, 4, 'موسی د څښتن ټول حکمونه ولیکل. هغه سهار وختي پاڅېد او د غره په لمنه کې یې د قربانۍ ځای جوړ کړ او هلته یې دولس تیږې چې د اسراییلو د دولسو قبیلو استازیتوب یې کاوه، ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_004.mp3', NULL, 1761758886, 1761758886),
(41124, 'Exodus 24:5', 'Exodus', 24, 5, 'بیا موسی ځینې اسراییلي ځوانان ولېږل او هغوی سوځېدونکې نذرانې او ځینې غویان د سلامتۍ د نذرانې په توګه څښتن ته قرباني کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_005.mp3', NULL, 1761758886, 1761758886),
(41125, 'Exodus 24:6', 'Exodus', 24, 6, 'موسی نیمه وینه راواخیستله او په لګنونو کې یې واچوله او نیمه یې د قربانۍ په ځای باندې وشیندله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_006.mp3', NULL, 1761758886, 1761758886),
(41126, 'Exodus 24:7', 'Exodus', 24, 7, 'بیا هغه د لوظ کتاب راواخیست او خلکو ته یې په لوړ اواز سره ولوست. هغوی وویل: «مونږ به د څښتن اطاعت کوو او د هغه په ټولو امرونو باندې به عمل کوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_007.mp3', NULL, 1761758886, 1761758886),
(41127, 'Exodus 24:8', 'Exodus', 24, 8, 'بیا موسی هغه وینه چې په لګنونو کې وه، راواخیستله او په خلکو باندې یې وشیندله. هغه وویل: «دا د هغه لوظ وینه ده چې څښتن د دغو ټولو حکمونو له مخې تاسو سره کړی دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_008.mp3', NULL, 1761758886, 1761758886),
(41128, 'Exodus 24:9', 'Exodus', 24, 9, 'موسی د هارون، ناداب، ابیهو او د اسراییلو د اویا مشرانو سره غره ته وخوت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_009.mp3', NULL, 1761758886, 1761758886),
(41129, 'Exodus 24:10', 'Exodus', 24, 10, 'او د اسراییلو خدای یې ولیده. د هغه د پښو لاندې د لاجوردو د فرش په شان یو څه ښکاره کېدل چې د اسمان په شان شنه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_010.mp3', NULL, 1761758886, 1761758886),
(41130, 'Exodus 24:11', 'Exodus', 24, 11, 'که څه هم د اسراییلو دغو مشرانو خدای ولیده، خو هغه ورته زیان ونه رساوه. بیا هغوی وخوړل او ویې څښل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_011.mp3', NULL, 1761758886, 1761758886),
(41131, 'Exodus 24:12', 'Exodus', 24, 12, 'څښتن موسی ته وویل: «ماته د غره سرته راوخېژه او دلته پاتې شه. زه به تاته د تیږو لوحې چې په هغو باندې مې د خلکو د لارښوونې دپاره حکمونه لیکلي دي، درکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_012.mp3', NULL, 1761758886, 1761758886),
(41132, 'Exodus 24:13', 'Exodus', 24, 13, 'موسی او د هغه مرستیال یعنې یوشع تیار شول او موسی سپېڅلي غره ته ورپورته شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_013.mp3', NULL, 1761758886, 1761758886),
(41133, 'Exodus 24:14', 'Exodus', 24, 14, 'موسی مشرانو ته وویل: «تاسو دلته انتظار وباسئ، ترڅو مونږ بېرته راشو. هارون او حور تاسو سره دي او هرڅوک چې کومه مسئله لري، هغوی ته دې ورشي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_014.mp3', NULL, 1761758886, 1761758886),
(41134, 'Exodus 24:15', 'Exodus', 24, 15, 'کله چې موسی غره ته پورته شو، نو ورېځې غر پټ کړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_015.mp3', NULL, 1761758886, 1761758886),
(41135, 'Exodus 24:16', 'Exodus', 24, 16, 'او د څښتن جلال د سینا په غره باندې خپور شو. غر شپږ ورځې په ورېځ کې پټ ؤ او په اوومه ورځ څښتن له ورېځ څخه موسی ته غږ وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_016.mp3', NULL, 1761758886, 1761758886),
(41136, 'Exodus 24:17', 'Exodus', 24, 17, 'د څښتن جلال اسراییلیانو ته داسې ښکاره کېده لکه د غره په سر باندې چې اور بل وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_017.mp3', NULL, 1761758886, 1761758886),
(41137, 'Exodus 24:18', 'Exodus', 24, 18, 'کله چې موسی غره ته ورپورته شو، هغه په ورېځ کې ورننوت او څلوېښت ورځې او څلوېښت شپې په غره کې پاتې شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus24_verse_018.mp3', NULL, 1761758886, 1761758886),
(41138, 'Numbers 31:1', 'Numbers', 31, 1, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_001.mp3', NULL, 1761758886, 1761758886),
(41139, 'Numbers 31:2', 'Numbers', 31, 2, '«څه چې مدیانیانو د اسراییلو د خلکو سره کړي وو، د هغه په خاطر هغوی ته سزا ورکړه. چې کله دې دا کار وکړ، بیا به ته مړ شې او د خپلو نیکونو سره به یوځای شې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_002.mp3', NULL, 1761758886, 1761758886),
(41140, 'Numbers 31:3', 'Numbers', 31, 3, 'بیا موسی قوم ته وویل: «د جګړې دپاره تیار شئ، ترڅو وکولای شئ چې د څښتن په امر د مدیانیانو څخه بدل واخلئ او هغوی ته سزا ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_003.mp3', NULL, 1761758886, 1761758886),
(41141, 'Numbers 31:4', 'Numbers', 31, 4, 'د اسراییلو د هرې قبیلې څخه زر تنه جنګ ته ولېږئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_004.mp3', NULL, 1761758886, 1761758886),
(41142, 'Numbers 31:5', 'Numbers', 31, 5, 'نو د هرې قبیلې څخه زر تنه غوره شول، ټول ۱۲۰۰۰ تنه د جګړې دپاره تیار شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_005.mp3', NULL, 1761758886, 1761758886),
(41143, 'Numbers 31:6', 'Numbers', 31, 6, 'موسی هغوی جګړې ته ولېږل او د العازار کاهن زوی فینحاس د هغوی سره ؤ. هغه د سپېڅلې خېمې څخه لږ سامان او سرني واخیستل چې د جګړې د اعلانولو د اشارې دپاره ووهل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_006.mp3', NULL, 1761758886, 1761758886),
(41144, 'Numbers 31:7', 'Numbers', 31, 7, 'څنګه چې څښتن موسی ته امر کړی ؤ، اسراییلیانو د مدیانیانو سره جګړه وکړه او د هغوی ټول نارینه یې ووژل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_007.mp3', NULL, 1761758886, 1761758886),
(41145, 'Numbers 31:8', 'Numbers', 31, 8, 'په هغو کې د مدیان پنځه پاچاهان یعنې اوي، راقم، صور، حور او رابع هم شامل وو. همدارنګه هغوی د بعور زوی بلعام هم وواژه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_008.mp3', NULL, 1761758886, 1761758886),
(41146, 'Numbers 31:9', 'Numbers', 31, 9, 'د اسراییلو خلکو د مدیانیانو ښځې او ماشومان ونیول، د هغوی ټولې پادې او رمې یې بوتللې او ټوله شتمني یې ورته لوټ کړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_009.mp3', NULL, 1761758886, 1761758886),
(41147, 'Numbers 31:10', 'Numbers', 31, 10, 'او د هغوی ټول ښارونه او کمپونه یې وسوځول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_010.mp3', NULL, 1761758886, 1761758886),
(41148, 'Numbers 31:11', 'Numbers', 31, 11, 'هغه ټول غنیمت چې هغوی نیولی ؤ او په هغه کې اسیران او حیوانات هم شامل وو، واخیستل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_011.mp3', NULL, 1761758886, 1761758886),
(41149, 'Numbers 31:12', 'Numbers', 31, 12, 'او هغه یې موسی، العازار او د اسراییلو قوم ته هغه کمپ ته چې د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ ؤ، راوړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_012.mp3', NULL, 1761758886, 1761758886),
(41150, 'Numbers 31:13', 'Numbers', 31, 13, 'موسی، العازار او د قوم ټول مشران د کمپ څخه د هغوی مخې ته ورووتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_013.mp3', NULL, 1761758886, 1761758886),
(41151, 'Numbers 31:14', 'Numbers', 31, 14, 'موسی د لښکرو په قوماندانانو باندې چې د جګړې څخه راستانه شوي وو، په قهر شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_014.mp3', NULL, 1761758886, 1761758886),
(41152, 'Numbers 31:15', 'Numbers', 31, 15, 'د هغوی څخه یې پوښتنه وکړه: «تاسو ولې ټولې ښځې ژوندۍ پریښې دي؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_015.mp3', NULL, 1761758886, 1761758886),
(41153, 'Numbers 31:16', 'Numbers', 31, 16, 'هغوی هغه څوک دي چې د بلعام په مشوره یې عمل کړی ؤ او زمونږ خلکو ته یې بلنه ورکړې وه چې د بعل فغور د خدای عبادت وکړي. ځکه څښتن مونږ ته سزا راکړه او په خپل قوم باندې یې وبا راوستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_016.mp3', NULL, 1761758886, 1761758886),
(41154, 'Numbers 31:17', 'Numbers', 31, 17, 'نو اوس ټول هلکان ووژنئ او هره ښځه چې د کوم سړي سره یوځای شوې وي ووژنئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_017.mp3', NULL, 1761758886, 1761758886),
(41155, 'Numbers 31:18', 'Numbers', 31, 18, 'خو ټولې پېغلې نجونې ژوندۍ پرېږدئ او هغوی د خپلو ځانونو دپاره وساتئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_018.mp3', NULL, 1761758886, 1761758886),
(41156, 'Numbers 31:19', 'Numbers', 31, 19, 'بیا موسی جنګیالیو ته وویل: «که چېرې ستاسو څخه چا څوک وژلی وي یا مو یو مړي ته لاس وروړی وي، باید اووه ورځې د کمپ څخه دباندې پاتې شي. په درېمه او اوومه ورځ باید تاسو خپل ځانونه او هغه ښځې چې تاسو اسیرانې نیولې دي، پاکې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_019.mp3', NULL, 1761758886, 1761758886),
(41157, 'Numbers 31:20', 'Numbers', 31, 20, 'همدارنګه هغه ټول کالي او ټول شیان چې د څرمنې، د وزو د وړیو او لرګیو څخه جوړ شوي وي هم پاک کړئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_020.mp3', NULL, 1761758886, 1761758886),
(41158, 'Numbers 31:21', 'Numbers', 31, 21, 'العازار کاهن هغو کسانو ته چې د جګړې څخه راستانه شوي وو، وویل: «دا هغه مقررات دي چې څښتن موسی ته ورکړي دي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_021.mp3', NULL, 1761758886, 1761758886),
(41159, 'Numbers 31:22', 'Numbers', 31, 22, 'سره زر، سپین زر، برنج، اوسپنه، قلعي او سرپ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_022.mp3', NULL, 1761758886, 1761758886),
(41160, 'Numbers 31:23', 'Numbers', 31, 23, 'او نور ټول هغه شیان چې نه سوځي، باید په سره اور کې واچول شي او هغه به پاک شي. خو هغه هم باید د هغو اوبو په وسیله پاک شي چې د پاکوالي دپاره کارول کیږي او هغه شیان چې په اور کې سوځي باید د اوبو په وسیله پاک شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_023.mp3', NULL, 1761758886, 1761758886),
(41161, 'Numbers 31:24', 'Numbers', 31, 24, 'په اوومه ورځ باید خپل کالي ووینځئ، بیا به په مذهبي لحاظ پاک شئ او کمپ ته د ننوتلو اجازه به ولرئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_024.mp3', NULL, 1761758886, 1761758886),
(41162, 'Numbers 31:25', 'Numbers', 31, 25, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_025.mp3', NULL, 1761758886, 1761758886),
(41163, 'Numbers 31:26', 'Numbers', 31, 26, '«باید ته او العازار د قوم د نورو مشرانو سره د اسیرانو او حیواناتو په شمول هغه ټول شیان وشمارئ چې د مدیانیانو څخه نیول شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_026.mp3', NULL, 1761758886, 1761758886),
(41164, 'Numbers 31:27', 'Numbers', 31, 27, 'هغه نیول شوي شیان په دوو مساوي برخو ووېشئ، یوه برخه یې هغو جنګیالیو ته چې جګړې ته تللي وو او بله برخه یې پاتې قوم ته ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_027.mp3', NULL, 1761758886, 1761758886),
(41165, 'Numbers 31:28', 'Numbers', 31, 28, 'د هغو جنګیالیو د برخې څخه چې په جګړه کې جنګېدلي دي، د هرو پنځو سوو اسیرانو، غویانو، خرو، پسونو او یا وزو څخه یو یو څښتن ته د هغه د برخې په توګه بېل کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_028.mp3', NULL, 1761758886, 1761758886),
(41166, 'Numbers 31:29', 'Numbers', 31, 29, 'هغه څښتن ته د ځانګړې اعانې په توګه العازار ته ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_029.mp3', NULL, 1761758886, 1761758886),
(41167, 'Numbers 31:30', 'Numbers', 31, 30, 'د پاتې قوم د برخې څخه د هرو پنځوسو اسیرانو څخه یو او هماغه شان د پنځوسو غویانو، خرو، پسونو او وزو څخه یو یو واخلئ او هغو لاویانو ته یې ورکړئ چې د سپېڅلې خېمې مسوولان دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_030.mp3', NULL, 1761758886, 1761758886),
(41168, 'Numbers 31:31', 'Numbers', 31, 31, 'څښتن چې کوم حکم کړی ؤ، موسی او العازار هماغسې وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_031.mp3', NULL, 1761758886, 1761758886),
(41169, 'Numbers 31:41', 'Numbers', 31, 41, 'نو څنګه چې څښتن حکم کړی ؤ، موسی د څښتن ټوله برخه العازار کاهن ته ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_041.mp3', NULL, 1761758886, 1761758886),
(41170, 'Numbers 31:47', 'Numbers', 31, 47, 'د دې برخې څخه موسی د هرو پنځوسو اسیرانو او حیواناتو څخه یو یو واخیست او هغه یې د څښتن د حکم له مخې لاویانو ته چې د سپېڅلې خېمې مسوولان وو، ورکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_047.mp3', NULL, 1761758886, 1761758886),
(41171, 'Numbers 31:48', 'Numbers', 31, 48, 'د لښکرو قوماندانان موسی ته ورغلل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_048.mp3', NULL, 1761758886, 1761758886),
(41172, 'Numbers 31:49', 'Numbers', 31, 49, 'او ورته ویې ویل: «باداره، مونږ خپلې لښکرې وشمېرلې، یو کس هم کم نه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_049.mp3', NULL, 1761758886, 1761758886),
(41173, 'Numbers 31:50', 'Numbers', 31, 50, 'نو مونږ د سرو زرو ګاڼې، بازوبندونه، بنګړي، ګوتې، غوږوالۍ او غاړکۍ چې مونږ هر یو نیولي دي، راوړي دي. مونږ هغه څښتن ته د خپل ژوند د بیې د ادا کولو دپاره وړاندې کوو، ترڅو هغه زمونږ ساتنه وکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_050.mp3', NULL, 1761758886, 1761758886),
(41174, 'Numbers 31:51', 'Numbers', 31, 51, 'موسی او العازار هغه سره زر واخیستل چې ټول د ګاڼو په شکل کې وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_051.mp3', NULL, 1761758886, 1761758886),
(41175, 'Numbers 31:52', 'Numbers', 31, 52, 'د قوماندانانو د ټولې اعانې وزن نژدې دوه سوه کیلو ګرامه ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_052.mp3', NULL, 1761758886, 1761758886),
(41176, 'Numbers 31:53', 'Numbers', 31, 53, 'په دې کې هغه شیان شامل نه وو کوم چې جنګیالیو د خپلو ځانونو دپاره ساتلي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_053.mp3', NULL, 1761758886, 1761758886),
(41177, 'Numbers 31:54', 'Numbers', 31, 54, 'نو موسی او العازار سره زر سپېڅلې خېمې ته راوړل، ترڅو اسراییلیان هغه د یادګار په توګه وساتي چې څښتن د هغوی سره مرسته کړې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers31_verse_054.mp3', NULL, 1761758886, 1761758886),
(41178, 'Proverbs 19:1', 'Proverbs', 19, 1, 'هغه غریب چې خپل ژوند په صداقت تېروي له هغه چا نه ښه دی چې کم‌عقل او دروغجن وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_001.mp3', NULL, 1761758886, 1761758886),
(41179, 'Proverbs 19:2', 'Proverbs', 19, 2, 'له علم پرته د خپلو غوښتنو ښکاره کول ښه کار نه دی ځکه څوک چې بیړه کوي خپله لار خطا کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_002.mp3', NULL, 1761758886, 1761758886),
(41180, 'Proverbs 19:3', 'Proverbs', 19, 3, 'انسان په خپل جهالت ځان تباه کوي او بیا ګناه او ملامتیا په څښتن اچوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_003.mp3', NULL, 1761758886, 1761758886),
(41181, 'Proverbs 19:4', 'Proverbs', 19, 4, 'شتمن سړی ډېر دوستان پیدا کوي خو غریبي له انسان نه خپل ورور هم جدا کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_004.mp3', NULL, 1761758886, 1761758886),
(41182, 'Proverbs 19:5', 'Proverbs', 19, 5, 'دروغجن شاهد به بې‌سزا پاتې نه شي او څوک چې دروغ بادوي د سزا نه به خلاص نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_005.mp3', NULL, 1761758886, 1761758886),
(41183, 'Proverbs 19:6', 'Proverbs', 19, 6, 'ډېر خلک له مشرانو نه مرسته غواړي او د تحفې ورکوونکي سره هرڅوک دوستي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_006.mp3', NULL, 1761758886, 1761758886),
(41184, 'Proverbs 19:7', 'Proverbs', 19, 7, 'که د غریب سړي نه ټول خپلوان کرکه کوي نو دوستان به څومره ترې ځان لېرې ساتي او حتی د خبرو کولو کوښښ یې هم ځای ته نه رسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_007.mp3', NULL, 1761758886, 1761758886),
(41185, 'Proverbs 19:8', 'Proverbs', 19, 8, 'څوک چې پوهه حاصلوي نو د خپل ځان سره مینه کوي بریالی دی هغه څوک چې پوهې ته په درنه سترګه ګوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_008.mp3', NULL, 1761758886, 1761758886),
(41186, 'Proverbs 19:9', 'Proverbs', 19, 9, 'دروغجن شاهد به بې‌سزا پاتې نه شي او څوک چې دروغ بادوي هغه به تباه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_009.mp3', NULL, 1761758886, 1761758886),
(41187, 'Proverbs 19:10', 'Proverbs', 19, 10, 'که د کم‌عقل سره د عیش او عشرت ژوند ښه نه ښکاري نو په شهزادګانو به د غلام حکومت کول څومره نامناسبه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_010.mp3', NULL, 1761758886, 1761758886),
(41188, 'Proverbs 19:11', 'Proverbs', 19, 11, 'هوښیار انسان زر نه په قهریږي او څوک چې د بل په ګناه پرده اچوي سرلوړې به شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_011.mp3', NULL, 1761758886, 1761758886),
(41189, 'Proverbs 19:12', 'Proverbs', 19, 12, 'د پاچا قهر د غړمبېدونکي زمري په څېر دی خو رحم یې د پرخې په شان په شنو واښو وریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_012.mp3', NULL, 1761758886, 1761758886),
(41190, 'Proverbs 19:13', 'Proverbs', 19, 13, 'کم‌عقل زوی د خپل پلار دپاره لوی مصیبت دی او د جګړه‌مارې ښځې جنګ د تل څڅېدونکي چت په څېر دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_013.mp3', NULL, 1761758886, 1761758886),
(41191, 'Proverbs 19:14', 'Proverbs', 19, 14, 'کور او مال د مور او پلار نه په میراث پاتې کیږي خو هوښیاره ښځه د څښتن له خوا ښه سوغات دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_014.mp3', NULL, 1761758886, 1761758886),
(41192, 'Proverbs 19:15', 'Proverbs', 19, 15, 'لټي په انسان دروند خوب راولي او ناراسته انسان وږی پاتې کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_015.mp3', NULL, 1761758886, 1761758886),
(41193, 'Proverbs 19:16', 'Proverbs', 19, 16, 'څوک چې د څښتن په حکمونو عمل کوي نو خپل ځان ساتي څوک چې د هغه لارو ته په سپکه سترګه ګوري نو مړ به شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_016.mp3', NULL, 1761758886, 1761758886),
(41194, 'Proverbs 19:17', 'Proverbs', 19, 17, 'څوک چې په غریب رحم کوي لکه څښتن ته چې پور ورکوي او څښتن به ورته د دې اجر ورکوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_017.mp3', NULL, 1761758886, 1761758886),
(41195, 'Proverbs 19:18', 'Proverbs', 19, 18, 'په پوره هیلې خپل زوی ته نصیحت کوه هسې نه چې په اخر کې یې ژوند تباه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_018.mp3', NULL, 1761758886, 1761758886),
(41196, 'Proverbs 19:19', 'Proverbs', 19, 19, 'پرېږده چې غوسه ناک انسان د خپل قهر نتیجه وګوري. که یوځل یې د سزا نه وژغورې نو بیا به یې تل ژغورې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_019.mp3', NULL, 1761758886, 1761758886),
(41197, 'Proverbs 19:20', 'Proverbs', 19, 20, 'لارښوونه قبوله کړه او نصیحت واوره نو په اخر کې به د حکمت خاوند شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_020.mp3', NULL, 1761758886, 1761758886),
(41198, 'Proverbs 19:21', 'Proverbs', 19, 21, 'د انسان په زړه کې ډېرې نقشې وي خو هغه څه کیږي چې د څښتن خوښه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_021.mp3', NULL, 1761758886, 1761758886),
(41199, 'Proverbs 19:22', 'Proverbs', 19, 22, 'مینه او وفا د انسان ښکلا ده او یو غریب انسان د دروغجن نه غوره دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_022.mp3', NULL, 1761758886, 1761758886),
(41200, 'Proverbs 19:23', 'Proverbs', 19, 23, 'له څښتن څخه وېره انسان ته ژوند وربخښي او په مړه ګېډه شپه تېروي او د هرې بلا نه یې خوندي ساتي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_023.mp3', NULL, 1761758886, 1761758886),
(41201, 'Proverbs 19:24', 'Proverbs', 19, 24, 'لټ انسان کاسې ته لاس غزولی شي خو خپله مړۍ خولې ته وړلی نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_024.mp3', NULL, 1761758886, 1761758886),
(41202, 'Proverbs 19:25', 'Proverbs', 19, 25, 'ملنډې وهونکي ته په لښته سزا ورکړه چې د ساده سړي د عبرت سبب شي او که د عقل خاوند اصلاح کړې هغه به نور هم علم حاصل کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_025.mp3', NULL, 1761758886, 1761758886),
(41203, 'Proverbs 19:26', 'Proverbs', 19, 26, 'څوک چې په پلار لاس اوچتوي او مور له کوره شړي نو داسې زوی شرم او رسوایي راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_026.mp3', NULL, 1761758886, 1761758886),
(41204, 'Proverbs 19:27', 'Proverbs', 19, 27, 'نو ای زما زویه! که ته نصیحت ته غوږ ونه نیسې نو د علم د خبرو نه به بې‌لارې شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_027.mp3', NULL, 1761758886, 1761758886),
(41205, 'Proverbs 19:28', 'Proverbs', 19, 28, 'بدکاره شاهد په انصاف پورې خندا کوي او بدکاران د شرارت نه خوند اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_028.mp3', NULL, 1761758886, 1761758886),
(41206, 'Proverbs 19:29', 'Proverbs', 19, 29, 'د ملنډو وهونکو دپاره سزا ده او د کم‌عقلانو د ملا دپاره لښته ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs19_verse_029.mp3', NULL, 1761758886, 1761758886),
(41207, 'Psalms 78:1', 'Psalms', 78, 1, 'ای زما قومه، زما تعلیم ته غوږ شئ واورئ په غور زما د خولې خبرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_001.mp3', NULL, 1761758886, 1761758886),
(41208, 'Psalms 78:2', 'Psalms', 78, 2, 'خبرې وبه کړمه زه په مثالونو باندې زه به رازونه کړم بیان د تېرو شویو وختو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_002.mp3', NULL, 1761758886, 1761758886),
(41209, 'Psalms 78:3', 'Psalms', 78, 3, 'هغه شیان چې اورېدلي او زده کړي مو دي هغه شیان چې مو نیکونو بیان کړي راته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_003.mp3', NULL, 1761758886, 1761758886),
(41210, 'Psalms 78:4', 'Psalms', 78, 4, 'هغه به پټ نه ساتو خپلو اولادونو څخه کړو به یې بیان راتلونکي نسل ته وړ د ستایلو کارنامې او هم قدرت د څښتن او هم کارونه عجیبه کوم چې هغه کړي دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_004.mp3', NULL, 1761758886, 1761758886),
(41211, 'Psalms 78:5', 'Psalms', 78, 5, 'ورکړ هغه د اسراییلو قوم ته خپل شریعت هغه ولس چې د یعقوب نسل دی زمونږ نیکونو ته یې وکړ حکم چې اولادونو ته ورزده کړي هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_005.mp3', NULL, 1761758886, 1761758886),
(41212, 'Psalms 78:6', 'Psalms', 78, 6, 'ترڅو راتلونکی نسل زده کړي هغه هم هغه کوچنیان چې لا پیدا نه دي او په خپل وار سره بیان خپل اولادونو ته کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_006.mp3', NULL, 1761758886, 1761758886),
(41213, 'Psalms 78:7', 'Psalms', 78, 7, 'نو په دې توګه به هغوی هم توکل وکاندي خدای باندې او هېر به نه کړي کوم کارونه چې هغه کړي دي بلکې هغوی به اطاعت یې د حکمونو کوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_007.mp3', NULL, 1761758886, 1761758886),
(41214, 'Psalms 78:8', 'Psalms', 78, 8, 'او دوی به نه وي سرکښان او نافرمانه خلک لکه د خپلو نیکه‌ګانو په شان د چا چې زړه ټینګ باور نه درلود خدای باندې او نه یې روح ؤ وفادار هغه ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_008.mp3', NULL, 1761758886, 1761758886),
(41215, 'Psalms 78:9', 'Psalms', 78, 9, 'سره له دې چې وو سمبال افرایمیان په لیندو خو د جګړې په ورځ یې تېښته وکړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_009.mp3', NULL, 1761758886, 1761758886),
(41216, 'Psalms 78:10', 'Psalms', 78, 10, 'هغوی د خدای سره خپل لوظ باندې وفا ونه کړه هغوی انکار وکړ ویې نه منلو قانون د هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_010.mp3', NULL, 1761758886, 1761758886),
(41217, 'Psalms 78:11', 'Psalms', 78, 11, 'هغوی دا هېر کړل چې هغه څه وکړل هغه معجزې چې خدای ښودلې وې هغوی ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_011.mp3', NULL, 1761758886, 1761758886),
(41218, 'Psalms 78:12', 'Psalms', 78, 12, 'په داسې حال کې چې نیکونو یې کتل خدای معجزې ښودلې د مصر ملک او د ‎صوعن سیمه کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_012.mp3', NULL, 1761758886, 1761758886),
(41219, 'Psalms 78:13', 'Psalms', 78, 13, 'خدای په دریاب کې کړله جوړه لاره هغوی یې پورې ویستل اوبه یې سمې د دېوال په شانتې ودرولې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_013.mp3', NULL, 1761758886, 1761758886),
