(41221, 'Psalms 78:15', 'Psalms', 78, 15, 'هغه به دښته کې ګټونه چول او ورکولې به یې اوبه هغوی ته داسې پرېمانه د بحرونو په شان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_015.mp3', NULL, 1761758886, 1761758886),
