(41225, 'Psalms 78:19', 'Psalms', 78, 19, 'دوی به د خدای په ضد خبرې کړلې ویل به هغوی: «ایا کولای شي خدای مونږ ته دسترخوان وغوړوي دښته کې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_019.mp3', NULL, 1761758886, 1761758886),
