(41227, 'Psalms 78:21', 'Psalms', 78, 21, 'نو څښتن دوی باندې شو ډېر په قهر چې کله یې واورېدې د دوی خبرې او د یعقوب په خلاف بل شولو اور په اسراییلو باندې یې قهر په ډېرېدلو شولو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_021.mp3', NULL, 1761758886, 1761758886),
(41228, 'Psalms 78:22', 'Psalms', 78, 22, 'ځکه چې دوی په خدای ایمان نه درلود باور یې نه درلود چې هغوی ته به خلاصون ورکړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_022.mp3', NULL, 1761758886, 1761758886),
(41229, 'Psalms 78:23', 'Psalms', 78, 23, 'خو پاس اسمان ته هغه حکم وکړ او دروازې یې د اسمان پرانیستې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_023.mp3', NULL, 1761758886, 1761758886),
(41230, 'Psalms 78:24', 'Psalms', 78, 24, 'ورته ویې لېږلو من چې دوی یې وخوري او ویې بخښلې دوی ته د اسمان غلې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_024.mp3', NULL, 1761758886, 1761758886),
