(41234, 'Psalms 78:28', 'Psalms', 78, 28, 'هغوی یې پرېښودل چې ولویږي د کمپ په منځ کې ټولو خېمو په شاوخوا باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms78_verse_028.mp3', NULL, 1761758886, 1761758886),
